1	"use client";
2	
3	/**
4	 * CUSTOMER-FACING (brand-voice checked): steps 2-4 of the bare-metal flow —
5	 * Configure (location, memory, storage, network, OS, term, name) -> Review (the
6	 * server's own quote) -> Pay (card or wallet).
7	 *
8	 * Every price on Review/Pay is the SERVER quote (lib/actions-dedicated-order.ts);
9	 * the Configure figures come from the same server-computed price table, so
10	 * displayed === charged.
11	 *
12	 * Payment: the portal's standard card path — the same Stripe Custom Checkout
13	 * session + inline card form (components/nx/NxCardFields) the VPS / game
14	 * deploy wizard uses — or the wallet balance, or both (balance first, card
15	 * for the rest). The customer picks; nothing is charged before they press Pay.
16	 */
17	import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
18	import Link from "next/link";
19	import { useRouter } from "next/navigation";
20	import type { OrderBuild, OrderOption, OrderVariant } from "@/lib/dedicated/order";
21	import type { DedicatedQuoteResult } from "@/lib/actions-dedicated-order";
22	import { payDedicatedOrder, quoteDedicatedOrderAction } from "@/lib/actions-dedicated-order";
23	import { DEDICATED_OS, renewalLabel, type DedicatedTerm } from "@/lib/dedicated/order-core";
24	import { NX_FAMILY_INFO } from "@/lib/dedicated/nx-names";
25	import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
26	import { Icon } from "@/components/nx/Icon";
27	import { NxCardFields } from "@/components/nx/NxCardFields";
28	import { BrandLogo } from "../BrandLogo";
29	import { Flag, StockDot, Tags, usd } from "../ui";
30	
31	export const FLOW_STEPS = ["Choose a build", "Configure", "Review", "Pay"] as const;
32	
33	function newKey(): string {
34	  const a = new Uint8Array(16);
35	  crypto.getRandomValues(a);
36	  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
37	}
38	
39	const comboKey = (m: string | null, d: string | null) => `${m ?? ""}|${d ?? ""}`;
40	const priceKey = (m: string | null, d: string | null, b: string | null) => `${m ?? ""}|${d ?? ""}|${b ?? ""}`;
41	const defId = (list: OrderOption[]) => list.find((o) => o.isDefault)?.id ?? list[0]?.id ?? null;
42	
43	function bestPartner(v: OrderVariant, fixed: "memory" | "storage", id: string | null): string | null {
44	  const other = fixed === "memory" ? v.storage : v.memory;
45	  if (!other.length) return null;
46	  const ok = other.filter((o) => v.inStock.includes(fixed === "memory" ? comboKey(id, o.id) : comboKey(o.id, id)));
47	  return (ok[0] ?? other.find((o) => o.isDefault) ?? other[0]).id;
48	}
49	
50	type Method = "card" | "wallet" | "split";
51	
52	export function Stepper({ at, onJump }: { at: number; onJump: (i: number) => void }) {
53	  return (
54	    <ol className="flex items-center gap-1.5 overflow-x-auto noscroll" aria-label="Order progress">
55	      {FLOW_STEPS.map((s, i) => {
56	        const done = i < at, on = i === at;
57	        return (
58	          <li key={s} className="flex flex-none items-center gap-1.5">
59	            <button type="button" disabled={i > at} onClick={() => onJump(i)} aria-current={on ? "step" : undefined}
60	                    className={"flex items-center gap-2 rounded-full px-2.5 py-1.5 text-[12px] font-bold transition " + (on ? "bm-ink" : done ? "bm-ink-2 hover:bm-ink" : "bm-ink-4")}
61	                    style={on ? { background: "var(--bm-accent-soft)", boxShadow: "0 0 0 1px var(--bm-accent) inset" } : undefined}>
62	              <span className="grid h-5 w-5 place-items-center rounded-full text-[10.5px]"
63	                    style={{ background: done ? "var(--bm-ok-soft)" : on ? "var(--bm-grad)" : "var(--bm-card-3)", color: done ? "var(--bm-ok)" : on ? "#fff" : "var(--bm-ink-3)" }}>
64	                {done ? <Icon name="check" size={9} tone="inherit" /> : i + 1}
65	              </span>
66	              <span className={i === at ? "" : "hidden sm:inline"}>{s}</span>
67	            </button>
68	            {i < FLOW_STEPS.length - 1 && <span aria-hidden className="h-px w-4 flex-none sm:w-8" style={{ background: "var(--bm-line-2)" }} />}
69	          </li>
70	        );
71	      })}
72	    </ol>
73	  );
74	}
75	
76	export function Configurator({ build, initialRegion, balanceCents, email, onBack }: {
77	  build: OrderBuild; initialRegion: string | null; balanceCents: number; email: string; onBack: () => void;
78	}) {
79	  const router = useRouter();
80	  const firstRegion = build.variants.find((v) => v.region === initialRegion && v.inStock.length) ?? build.variants.find((v) => v.inStock.length) ?? build.variants[0];
81	  const [step, setStep] = useState(1);
82	  const [region, setRegion] = useState(firstRegion.region);
83	  const variant = build.variants.find((v) => v.region === region) ?? firstRegion;
84	  const initialCombo = (v: OrderVariant): { m: string | null; d: string | null } => {
85	    const m = defId(v.memory), d = defId(v.storage);
86	    if (v.inStock.includes(comboKey(m, d)) || !v.inStock.length) return { m, d };
87	    const [mm, dd] = v.inStock[0].split("|");
88	    return { m: mm || null, d: dd || null };
89	  };
90	  const [memoryId, setMemoryId] = useState<string | null>(initialCombo(firstRegion).m);
91	  const [storageId, setStorageId] = useState<string | null>(initialCombo(firstRegion).d);
92	  const [bandwidthId, setBandwidthId] = useState<string | null>(defId(firstRegion.bandwidth));
93	  const [os, setOs] = useState(DEDICATED_OS[0].id);
94	  const [term, setTerm] = useState<DedicatedTerm>(1);
95	  const [label, setLabel] = useState("");
96	  const orderKey = useRef<string>("");
97	  if (!orderKey.current) orderKey.current = newKey();
98	  useEffect(() => { window.scrollTo({ top: 0 }); }, [step]);
99	
100	  const chooseRegion = (code: string) => {
101	    const next = build.variants.find((v) => v.region === code);
102	    if (!next) return;
103	    const byLabel = (from: OrderOption[], to: OrderOption[], id: string | null): string | null => to.find((o) => o.label === from.find((x) => x.id === id)?.label)?.id ?? defId(to);
104	    let m: string | null = byLabel(variant.memory, next.memory, memoryId);
105	    let d: string | null = byLabel(variant.storage, next.storage, storageId);
106	    if (next.inStock.length && !next.inStock.includes(comboKey(m, d))) {
107	      const alt = bestPartner(next, "memory", m);
108	      if (next.inStock.includes(comboKey(m, alt))) d = alt;
109	      else ({ m, d } = initialCombo(next));
110	    }
111	    setRegion(code);
112	    setMemoryId(m);
113	    setStorageId(d);
114	    setBandwidthId(byLabel(variant.bandwidth, next.bandwidth, bandwidthId));
115	  };
116	  const chooseMemory = (id: string) => {
117	    setMemoryId(id);
118	    if (!variant.inStock.includes(comboKey(id, storageId))) setStorageId(bestPartner(variant, "memory", id));
119	  };
120	  const chooseStorage = (id: string) => {
121	    setStorageId(id);
122	    if (!variant.inStock.includes(comboKey(memoryId, id))) setMemoryId(bestPartner(variant, "storage", id));
123	  };
124	
125	  const inStock = variant.inStock.includes(comboKey(memoryId, storageId));
126	  const monthly = variant.prices[priceKey(memoryId, storageId, bandwidthId)] ?? null;
127	  const memOk = (id: string) => variant.inStock.some((k) => k.startsWith(`${id}|`));
128	  const diskOk = (id: string) => variant.inStock.some((k) => k.endsWith(`|${id}`));
129	
130	  const intent = useMemo(() => ({
131	    itemId: variant.itemId, region, os, termMonths: term, memoryId, storageId, bandwidthId, label: label.trim(), orderKey: orderKey.current,
132	  }), [variant.itemId, region, os, term, memoryId, storageId, bandwidthId, label]);
133	
134	  /* ---------- review: the server's quote ---------- */
135	  const [quote, setQuote] = useState<DedicatedQuoteResult | null>(null);
136	  const [quoting, startQuote] = useTransition();
137	  const runQuote = useCallback(() => startQuote(async () => setQuote(await quoteDedicatedOrderAction(intent, true))), [intent]);
138	  useEffect(() => { if (step === 2) runQuote(); }, [step, runQuote]);
139	  const q = quote && quote.ok ? quote : null;
140	  const total = q?.quote.money.totalCents ?? 0;
141	
142	  /* ---------- pay ---------- */
143	  const canWallet = balanceCents >= total && total > 0;
144	  const canSplit = balanceCents > 0 && balanceCents < total;
145	  const [method, setMethod] = useState<Method>("card");
146	  // Chosen synchronously when entering Pay (an effect would render one frame as "card" first and
147	  // open a card session the customer never sees).
148	  const toPay = () => { setMethod(canWallet ? "wallet" : "card"); setStep(3); };
149	  const useWallet = method !== "card";
150	  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number; walletApplied: number; method: Method } | null>(null);
151	  const [payError, setPayError] = useState<string | null>(null);
152	  const [paying, setPaying] = useState(false);
153	  const [preparing, startPrep] = useTransition();
154	  const cardConfirm = useRef<(() => Promise<void>) | null>(null);
155	  const [canConfirm, setCanConfirm] = useState(false);
156	  const onConfirmReady = useCallback((fn: (() => Promise<void>) | null) => { cardConfirm.current = fn; setCanConfirm(!!fn); }, []);
157	  const onBusy = useCallback((b: boolean, err: string | null) => { setPaying(b); setPayError(err); }, []);
158	
159	  // Open the card session for the chosen method (card or wallet+card) once per method.
160	  useEffect(() => {
161	    if (step !== 3 || method === "wallet" || !q) return;
162	    if (checkout && checkout.method === method) return;
163	    setCheckout(null);
164	    setCanConfirm(false);
165	    setPayError(null);
166	    startPrep(async () => {
167	      const r = await payDedicatedOrder(intent, method === "split");
168	      if (!r.ok) setPayError(r.error);
169	      else if ("checkout" in r) setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied, method });
170	      else router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`);
171	    });
172	    // eslint-disable-next-line react-hooks/exhaustive-deps
173	  }, [step, method, q]);
174	
175	  const payNow = () => {
176	    setPayError(null);
177	    if (method === "wallet") {
178	      setPaying(true);
179	      startPrep(async () => {
180	        const r = await payDedicatedOrder(intent, true);
181	        if (!r.ok) { setPayError(r.error); setPaying(false); return; }
182	        if ("serverId" in r) router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`);
183	        else { setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied, method: "split" }); setMethod("split"); setPaying(false); }
184	      });
185	      return;
186	    }
187	    void cardConfirm.current?.();
188	  };
189	
190	  const mem = variant.memory.find((o) => o.id === memoryId);
191	  const disk = variant.storage.find((o) => o.id === storageId);
192	  const bw = variant.bandwidth.find((o) => o.id === bandwidthId);
193	  const osObj = DEDICATED_OS.find((o) => o.id === os)!;
194	  const canContinue = inStock && monthly != null;
195	  const cardDue = method === "card" ? total : method === "split" ? (checkout?.method === "split" ? checkout.cardCents : Math.max(0, total - balanceCents)) : 0;
196	  const walletDue = method === "wallet" ? total : method === "split" ? (checkout?.method === "split" ? checkout.walletApplied : Math.min(balanceCents, total)) : 0;
197	
198	  return (
199	    <div className="bm-enter flex flex-col gap-5">
200	      <div className="flex flex-wrap items-center justify-between gap-3">
201	        <button type="button" onClick={step === 1 ? onBack : () => setStep(step - 1)} className="bm-btn-ghost">
202	          <span aria-hidden>←</span>{step === 1 ? "All builds" : "Back"}
203	        </button>
204	        <Stepper at={step} onJump={(i) => (i === 0 ? onBack() : i === 3 ? toPay() : setStep(i))} />
205	      </div>
206	
207	      <BuildHeader build={build} />
208	
209	      {step === 1 && (
210	        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_370px]">
211	          <div className="flex min-w-0 flex-col gap-4">
212	            <Section n={1} title="Location" help="Only locations with this build in stock can be ordered.">
213	              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
214	                {build.variants.map((v) => {
215	                  const ok = v.inStock.length > 0;
216	                  const from = ok ? Math.min(...Object.values(v.prices)) : null;
217	                  return (
218	                    <button key={v.region} type="button" className="bm-pick flex items-center gap-3 p-3" aria-pressed={v.region === region} disabled={!ok} onClick={() => ok && chooseRegion(v.region)}>
219	                      <Flag country={v.country} width={24} />
220	                      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
221	                        <span className="trunc text-[13.5px] font-bold bm-ink">{v.label}</span>
222	                        <span className="flex items-center gap-1.5 text-[11.5px] bm-ink-3"><StockDot on={ok} />{ok ? `from ${usd(from!)}/mo` : "Sold out here"}</span>
223	                      </span>
224	                    </button>
225	                  );
226	                })}
227	              </div>
228	            </Section>
229	            {variant.memory.length > 0 && (
230	              <Section n={2} title="Memory" help="Dedicated RAM, installed before handover.">
231	                <Options list={variant.memory} on={memoryId} ok={memOk} pick={chooseMemory} />
232	              </Section>
233	            )}
234	            {variant.storage.length > 0 && (
235	              <Section n={3} title="Storage" help="Disks in software RAID unless the option says otherwise.">
236	                <Options list={variant.storage} on={storageId} ok={diskOk} pick={chooseStorage} />
237	              </Section>
238	            )}
239	            {variant.bandwidth.length > 1 && (
240	              <Section n={4} title="Network" help="Unmetered public bandwidth. DDoS protection is always included.">
241	                <Options list={variant.bandwidth} on={bandwidthId} ok={() => true} pick={setBandwidthId} />
242	              </Section>
243	            )}
244	            <Section n={5} title="Operating system" help="Installed and hardened by our team. You get full root.">
245	              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
246	                {DEDICATED_OS.map((o) => (
247	                  <button key={o.id} type="button" className="bm-pick flex items-center gap-3 p-3" aria-pressed={o.id === os} onClick={() => setOs(o.id)}>
248	                    <Icon name="terminal" size={14} tone="inherit" className="bm-ink-3" />
249	                    <span className="flex min-w-0 flex-col gap-0.5">
250	                      <span className="trunc text-[13.5px] font-bold bm-ink">{o.label}</span>
251	                      <span className="trunc text-[11.5px] bm-ink-3">{o.note}</span>
252	                    </span>
253	                  </button>
254	                ))}
255	              </div>
256	            </Section>
257	            <Section n={6} title="Billing term" help="Pay monthly, or a year up front. Renews at the same price.">
258	              <div className="grid gap-2.5 sm:grid-cols-2">
259	                {([1, 12] as const).map((t) => (
260	                  <button key={t} type="button" className="bm-pick flex flex-col gap-1 p-3.5" aria-pressed={term === t} onClick={() => setTerm(t)}>
261	                    <span className="text-[14px] font-extrabold bm-ink">{t === 1 ? "Monthly" : "Annual"}</span>
262	                    <span className="bm-num text-[13px] font-bold bm-ink-2">{monthly != null ? renewalLabel(monthly, t) : "—"}</span>
263	                    <span className="text-[11.5px] bm-ink-3">{t === 1 ? "Billed every month." : "Billed once a year, up front."}</span>
264	                  </button>
265	                ))}
266	              </div>
267	            </Section>
268	            <Section n={7} title="Name it" help="Optional. Shown on your dashboard and invoices.">
269	              <input value={label} onChange={(e) => setLabel(e.target.value.slice(0, 40))} placeholder="e.g. Production database" className="bm-field max-w-[420px]" aria-label="Server name" />
270	            </Section>
271	          </div>
272	          <aside className="xl:sticky xl:top-4 xl:self-start">
273	            <section className="bm-card flex flex-col gap-4 p-5">
274	              <span className="text-[15px] font-extrabold bm-ink">Your server</span>
275	              <ul className="flex flex-col gap-2.5 text-[13px] bm-ink-2">
276	                <Li icon={<BrandLogo brand={cpuBrandOf(build.cpu)} h={11} />}>{build.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")} · {build.cores}c / {build.threads}t</Li>
277	                {build.gpu && <Li icon={<BrandLogo brand={gpuBrandOf(build.gpu)} h={11} />}>{build.gpu}</Li>}
278	                <Li icon={<Icon name="ram" size={13} tone="inherit" />}>{mem ? mem.label : `${build.ramGb} GB`}</Li>
279	                <Li icon={<Icon name="database" size={13} tone="inherit" />}>{disk ? disk.label : build.storage}</Li>
280	                {(bw || build.bandwidth) && <Li icon={<Icon name="nodes" size={13} tone="inherit" />}>{bw ? bw.label : build.bandwidth}</Li>}
281	                <Li icon={<Flag country={variant.country} width={16} />}>{variant.label}</Li>
282	                <Li icon={<Icon name="terminal" size={13} tone="inherit" />}>{osObj.label}</Li>
283	              </ul>
284	              <div className="bm-hr" />
285	              {canContinue ? (
286	                <div className="flex flex-col gap-1.5">
287	                  <div className="flex items-baseline justify-between"><span className="text-[12px] bm-ink-3">{term === 12 ? "Annual" : "Monthly"}</span><span className="bm-price text-[24px]">{renewalLabel(monthly!, term)}</span></div>
288	                  <div className="flex items-baseline justify-between text-[12.5px]"><span className="bm-ink-3">One-time setup</span><span className="font-bold bm-ink-2">{variant.setupCents > 0 ? usd(variant.setupCents) : "Free"}</span></div>
289	                  <span className="mt-1 flex items-center gap-1.5 text-[11.5px] font-semibold bm-ok"><Icon name="clock" size={11} tone="inherit" />Online within 24 hours</span>
290	                </div>
291	              ) : (
292	                <p className="rounded-[11px] px-3 py-2.5 text-[12.5px]" style={{ background: "var(--bm-warn-soft)", color: "var(--bm-warn)" }}>
293	                  This combination isn&apos;t in stock in {variant.label}. Pick another memory or storage option, or another location.
294	                </p>
295	              )}
296	              <button type="button" disabled={!canContinue} onClick={() => setStep(2)} className="bm-btn w-full">Review order <span aria-hidden>→</span></button>
297	              <span className="text-center text-[11px] bm-ink-4">Tax, if any, is shown on the next step.</span>
298	            </section>
299	          </aside>
300	        </div>
301	      )}
302	
303	      {step === 2 && (
304	        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
305	          <section className="bm-card flex min-w-0 flex-col gap-4 p-5">
306	            <div className="flex items-start justify-between gap-3">
307	              <div>
308	                <span className="text-[17px] font-extrabold bm-ink">Review your order</span>
309	                <p className="text-[12px] bm-ink-3">Priced just now from live stock.</p>
310	              </div>
311	              <button type="button" onClick={() => setStep(1)} className="bm-btn-ghost">Change</button>
312	            </div>
313	            {!quote || quoting ? (
314	              <div className="grid gap-3 sm:grid-cols-2" aria-busy="true" aria-label="Pricing your order">{Array.from({ length: 6 }, (_, i) => <div key={i} className="bm-skel h-[64px]" />)}</div>
315	            ) : !quote.ok ? (
316	              <ErrorBox msg={quote.error} onBack={() => setStep(1)} onRetry={runQuote} />
317	            ) : (
318	              <>
319	                <dl className="grid gap-3 sm:grid-cols-2">
320	                  {[
321	                    ["Server", quote.quote.spec.name, NX_FAMILY_INFO[quote.quote.spec.family].blurb],
322	                    ["Processor", quote.quote.spec.cpu, `${quote.quote.spec.cores} cores · ${quote.quote.spec.threads} threads`],
323	                    ["Memory", `${quote.quote.spec.ramGb} GB`, "Dedicated to you"],
324	                    ["Storage", quote.quote.spec.storage, "Your own disks"],
325	                    ["Network", quote.quote.spec.bandwidth || "—", "DDoS protection included"],
326	                    ["Location", quote.quote.regionLabel, ""],
327	                    ["Operating system", quote.quote.osLabel, "Full root access"],
328	                    ...(quote.quote.spec.gpu ? [["GPU", quote.quote.spec.gpu, "Dedicated to you"]] : []),
329	                  ].map(([k, v, sub]) => (
330	                    <div key={k} className="bm-sub px-3.5 py-3">
331	                      <dt className="bm-label">{k}</dt>
332	                      <dd className="mt-0.5 text-[13.5px] font-bold bm-ink">{v}</dd>
333	                      {sub && <dd className="text-[11.5px] bm-ink-3">{sub}</dd>}
334	                    </div>
335	                  ))}
336	                </dl>
337	                <WhatNext />
338	              </>
339	            )}
340	          </section>
341	          <aside className="xl:self-start">
342	            <section className="bm-card flex flex-col gap-3 p-5">
343	              <span className="text-[15px] font-extrabold bm-ink">Order summary</span>
344	              {q ? (
345	                <>
346	                  <Money rows={[
347	                    [`${q.quote.termLabel} term`, usd(q.quote.money.termCents)],
348	                    ["One-time setup", q.quote.money.setupCents ? usd(q.quote.money.setupCents) : "Free"],
349	                    ...(q.quote.money.taxCents ? [[`Tax (${q.quote.money.taxRatePercent}%${q.quote.money.taxCountry ? ` ${q.quote.money.taxCountry}` : ""})`, usd(q.quote.money.taxCents)] as [string, string]] : []),
350	                  ]} total={["Total today", usd(q.quote.money.totalCents)]} />
351	                  <p className="text-[12px] bm-ink-3">Renews at <b className="bm-ink-2">{q.quote.renewal}</b>{q.quote.money.taxCents ? " plus tax" : ""}.</p>
352	                  <button type="button" onClick={toPay} className="bm-btn w-full">Continue to payment <span aria-hidden>→</span></button>
353	                  <span className="flex items-center justify-center gap-1.5 text-[11px] bm-ink-4"><Icon name="card" size={11} tone="inherit" />Card or wallet balance on the next step</span>
354	                </>
355	              ) : (
356	                <div className="flex flex-col gap-2" aria-hidden><div className="bm-skel h-4" /><div className="bm-skel h-4 w-2/3" /><div className="bm-skel h-10" /></div>
357	              )}
358	            </section>
359	          </aside>
360	        </div>
361	      )}
362	
363	      {step === 3 && q && (
364	        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
365	          <section className="bm-card flex min-w-0 flex-col gap-4 p-5">
366	            <div className="flex items-center gap-2.5">
367	              <Icon name="lock" size={16} tone="inherit" className="bm-accent" />
