3	/**
4	 * CUSTOMER-FACING (brand-voice checked): /dashboard/dedicated IS the order flow
5	 * (catalogue -> configure -> review -> pay). One client component holds it so
6	 * moving between the catalogue and a build never re-renders the page on the
7	 * server:
8	 *
9	 *   - the catalogue stays mounted (hidden) while a build is configured, so its
10	 *     filters, layout and scroll position come back instantly;
11	 *   - opening a build pushes `#build=<id>[&region=<code>]` onto history, so the
12	 *     browser Back button, a refresh and a shared link all work. The HASH, not
13	 *     the query: Next.js keys the page segment by its search params, so a
14	 *     `?build=` change made Next refetch the whole page from the server on every
15	 *     open and every Back (measured: one RSC request each). A hash change never
16	 *     does. Incoming `?build=<id>` links (the NXM page, the old /order URLs) are
17	 *     still rendered server-side straight into the configurator;
18	 *   - build data comes from a gated server action, prefetched when a card is
19	 *     hovered or focused, and kept in memory for the visit.
20	 */
21	import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
22	import type { OrderBuild, OrderCatalogCard } from "@/lib/dedicated/order";
23	import { loadDedicatedBuildAction } from "@/lib/actions-dedicated-order";
24	import { Catalogue } from "./Catalogue";
25	import { Configurator, Stepper } from "./Configurator";
26	
27	type Open = { id: string; region: string | null };
28	
29	const ID_RE = /^[a-z0-9]{8,40}$/i;
30	function readUrl(): Open | null {
31	  const h = new URLSearchParams(window.location.hash.replace(/^#/, ""));
32	  const hid = h.get("build");
33	  if (hid && ID_RE.test(hid)) return { id: hid, region: h.get("region") };
34	  const sp = new URLSearchParams(window.location.search);
35	  const id = sp.get("build");
36	  return id && ID_RE.test(id) ? { id, region: sp.get("region") } : null;
37	}
