39	export function BareMetalFlow({ cards, initialOpen, initialBuild, balanceCents, email, preview, previewAll, hero, notice }: {
40	  cards: OrderCatalogCard[];
41	  initialOpen: Open | null;
42	  initialBuild: OrderBuild | null;
43	  balanceCents: number;
44	  email: string;
45	  preview: boolean;
46	  previewAll: boolean;
47	  hero: ReactNode;
48	  notice?: ReactNode;
49	}) {
50	  const cache = useRef(new Map<string, Promise<OrderBuild | null>>());
51	  if (initialBuild && !cache.current.has(initialBuild.id)) cache.current.set(initialBuild.id, Promise.resolve(initialBuild));
52	  const [open, setOpen] = useState<Open | null>(initialOpen);
53	  const [build, setBuild] = useState<OrderBuild | null | undefined>(initialOpen ? initialBuild ?? undefined : undefined);
54	  const scrollY = useRef(0);
55	
56	  const fetchBuild = useCallback((id: string) => {
57	    let p = cache.current.get(id);
58	    if (!p) {
59	      p = loadDedicatedBuildAction(id).catch(() => null);
60	      cache.current.set(id, p);
61	      // a failed/empty fetch should not be cached forever
62	      void p.then((b) => { if (!b) cache.current.delete(id); });
63	    }
64	    return p;
65	  }, []);
66	
67	  // Resolve whichever build is open.
68	  useEffect(() => {
69	    if (!open) { setBuild(undefined); return; }
70	    let live = true;
71	    setBuild((b) => (b && b.id === open.id ? b : undefined));
72	    void fetchBuild(open.id).then((b) => { if (live) setBuild(b); });
73	    return () => { live = false; };
74	  }, [open, fetchBuild]);
75	
76	  // Browser Back / Forward, and a hand-edited hash.
77	  useEffect(() => {
78	    const onPop = () => {
79	      const next = readUrl();
80	      setOpen(next);
81	      if (!next) requestAnimationFrame(() => window.scrollTo({ top: scrollY.current }));
82	    };
83	    // A refresh / shared link with #build= (the server never sees the hash).
84	    if (!initialOpen) { const h = readUrl(); if (h) setOpen(h); }
85	    window.addEventListener("popstate", onPop);
86	    window.addEventListener("hashchange", onPop);
87	    return () => { window.removeEventListener("popstate", onPop); window.removeEventListener("hashchange", onPop); };
88	    // eslint-disable-next-line react-hooks/exhaustive-deps
89	  }, []);
90	
91	  const configure = (id: string, region: string | null) => {
92	    scrollY.current = window.scrollY;
93	    const url = new URL(window.location.href);
94	    url.hash = new URLSearchParams(region ? { build: id, region } : { build: id }).toString();
95	    window.history.pushState({ ...(window.history.state ?? {}), bm: 1 }, "", url);
96	    setOpen({ id, region });
97	    window.scrollTo({ top: 0 });
98	  };
99	
100	  const back = () => {
101	    // If we pushed the entry, go back through history so Forward still works.
102	    if (window.history.state?.bm) { window.history.back(); return; }
103	    // Arrived on a server-rendered ?build= link: drop it (one server refresh of the URL, then client-only).
104	    const url = new URL(window.location.href);
105	    url.searchParams.delete("build");
106	    url.searchParams.delete("region");
107	    url.hash = "";
108	    window.history.replaceState(window.history.state, "", url);
109	    setOpen(null);
110	    requestAnimationFrame(() => window.scrollTo({ top: scrollY.current }));
111	  };
112	
113	  return (
114	    <div className="bm mx-auto flex w-full max-w-[1480px] flex-col gap-5">
115	      {notice}
116	      <div hidden={!!open}>
117	        <Catalogue cards={cards} preview={preview} previewAll={previewAll} hero={hero} onConfigure={configure} onPrefetch={(id) => void fetchBuild(id)} />
118	      </div>
119	      {open && (
120	        build === undefined ? (
121	          <ConfigureSkeleton onBack={back} />
122	        ) : build === null ? (
123	          <section className="bm-card flex flex-col items-center gap-2 px-6 py-14 text-center">
124	            <span className="text-[16px] font-extrabold bm-ink">This build is no longer available</span>
125	            <span className="max-w-[48ch] text-[13px] bm-ink-3">It sold out or was withdrawn while you were browsing. Pick another in-stock build.</span>
126	            <button type="button" onClick={back} className="bm-btn bm-btn-sm mt-2">Back to all builds</button>
127	          </section>
128	        ) : (
129	          <Configurator key={build.id} build={build} initialRegion={open.region} balanceCents={balanceCents} email={email} onBack={back} />
130	        )
131	      )}
132	    </div>
133	  );
134	}
