"use server";

/**
 * CUSTOMER checkout actions for dedicated servers (/dashboard/dedicated/order/*).
 *
 * Gate: every action re-checks dedicatedAccessFor(user) (public flag OR the
 * private-preview allowlist) and answers "Not found" otherwise — the feature
 * does not exist for anyone else.
 *
 * Money path = the portal's wallet-then-card shape (lib/actions-dedicated-ip.ts,
 * payAndDeploy): server quote -> walletSplit -> either place now from the wallet,
 * or open a Stripe Custom Checkout session for the card remainder (rendered by
 * components/nx/NxCardFields) whose fulfilment places the order. The client never
 * supplies a price.
 */
import { requireUser, assertNotImpersonating } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { walletSplit } from "./wallet-split";
import { emailVerificationError } from "./email-verification";
import { createDedicatedOrderPaymentSession, type CustomCheckout } from "./stripe";
import { dedicatedAccessFor } from "./dedicated/gate";
import { DedicatedOrderError, loadOrderBuild, orderPreviewAll, placeDedicatedOrder, quoteDedicatedOrder, toCustomerQuote, type CustomerQuote, type OrderBuild } from "./dedicated/order";
import { parseDedicatedIntent } from "./dedicated/order-core";

const NOT_FOUND = "Not found";

async function gatedUser() {
  const user = await requireUser();
  const access = await dedicatedAccessFor(user);
  if (!access.allowed) throw new Error(NOT_FOUND);
  return { user, previewAll: await orderPreviewAll(access.preview) };
}

/**
 * One build for the configurator, fetched by the client when a catalogue card is
 * opened (or hovered, as a prefetch), so catalogue -> configure -> back never
 * reloads the page. Read-only; served from the catalogue cache.
 */
export async function loadDedicatedBuildAction(id: unknown): Promise<OrderBuild | null> {
  try {
    const { previewAll } = await gatedUser();
    if (typeof id !== "string" || !/^[a-z0-9]{8,40}$/i.test(id)) return null;
    return await loadOrderBuild(id, previewAll);
  } catch {
    return null;
  }
}

export type DedicatedQuoteResult =
  | { ok: true; quote: CustomerQuote; balanceCents: number; walletApplied: number; cardCents: number }
  | { ok: false; error: string };

/** Re-price a configuration (review step). Read-only. */
export async function quoteDedicatedOrderAction(raw: unknown, useWallet = true): Promise<DedicatedQuoteResult> {
  try {
    const { user, previewAll } = await gatedUser();
    const intent = parseDedicatedIntent(raw);
    if (!intent) return { ok: false, error: "That configuration isn't valid. Please pick again." };
    const q = await quoteDedicatedOrder(intent, user, { previewAll });
    const split = walletSplit({ dueCents: q.money.totalCents, balanceCents: user.balanceCents, useWallet });
    return { ok: true, quote: toCustomerQuote(q), balanceCents: user.balanceCents, walletApplied: split.walletApplied, cardCents: split.cardCents };
  } catch (e) {
    if (e instanceof DedicatedOrderError) return { ok: false, error: e.message };
    return { ok: false, error: e instanceof Error && e.message === NOT_FOUND ? NOT_FOUND : "We couldn't price that configuration. Please try again." };
  }
}

export type DedicatedPayResult =
  | { ok: true; serverId: string }
  | { ok: true; checkout: CustomCheckout; cardCents: number; walletApplied: number }
  | { ok: false; error: string };

/**
 * Pay for a configuration. Wallet covers it -> the order is placed now.
 * Otherwise -> a card session for exactly the remainder; the order is placed when
 * the card clears (lib/fulfil-checkout.ts), never before.
 */
export async function payDedicatedOrder(raw: unknown, useWallet = true): Promise<DedicatedPayResult> {
  try {
    try {
      await assertNotImpersonating();
    } catch {
      return { ok: false, error: "Payments are disabled while you are viewing this account as an admin." };
    }
    const { user, previewAll } = await gatedUser();
    const unverified = await emailVerificationError(user);
    if (unverified) return { ok: false, error: unverified };
    if (!checkRateLimit(`dedicated-pay:${user.id}`, { max: 10, windowMs: 10 * 60_000 }).ok) {
      return { ok: false, error: "Too many attempts. Please wait a few minutes and try again." };
    }
    const intent = parseDedicatedIntent(raw);
    if (!intent) return { ok: false, error: "That configuration isn't valid. Please pick again." };
    const q = await quoteDedicatedOrder(intent, user, { previewAll });
    const split = walletSplit({ dueCents: q.money.totalCents, balanceCents: user.balanceCents, useWallet });
    if (split.cardCents <= 0) {
      const { serverId } = await placeDedicatedOrder(user, intent, { previewAll, via: "wallet" });
      return { ok: true, serverId };
    }
    const checkout = await createDedicatedOrderPaymentSession(user, split.cardCents, intent, q.money, `${q.spec.name} · ${q.regionLabel}`);
    if (!checkout) return { ok: false, error: "Card payments aren't available right now. Top up your wallet to cover the order instead." };
    return { ok: true, checkout, cardCents: split.cardCents, walletApplied: split.walletApplied };
  } catch (e) {
    if (e instanceof DedicatedOrderError) return { ok: false, error: e.message };
    if (e instanceof Error && e.message === NOT_FOUND) return { ok: false, error: NOT_FOUND };
    return { ok: false, error: "Something went wrong preparing your payment. Nothing was charged. Please try again." };
  }
}
/**
 * PURE pieces of the dedicated-server checkout (no DB, no clock, safe for client
 * bundles): the operating systems we install, billing terms, the order intent
 * parser, and the money/renewal wording. test/dedicated-order.test.ts covers it.
 *
 * Prices are always computed server-side (lib/dedicated/order.ts) from the
 * pricing rules; nothing here invents a price.
 */

export type DedicatedOs = { id: string; label: string; family: "Ubuntu" | "Debian" | "AlmaLinux" | "Rocky Linux" | "Proxmox"; note: string };

/** What our team installs by hand at handover. Linux only (no licence resale). */
export const DEDICATED_OS: DedicatedOs[] = [
  { id: "ubuntu-2404", label: "Ubuntu 24.04 LTS", family: "Ubuntu", note: "Recommended. Supported to 2029." },
  { id: "ubuntu-2204", label: "Ubuntu 22.04 LTS", family: "Ubuntu", note: "Supported to 2027." },
  { id: "debian-12", label: "Debian 12", family: "Debian", note: "Lean and stable." },
  { id: "alma-9", label: "AlmaLinux 9", family: "AlmaLinux", note: "RHEL-compatible." },
  { id: "rocky-9", label: "Rocky Linux 9", family: "Rocky Linux", note: "RHEL-compatible." },
  { id: "proxmox-9", label: "Proxmox VE 9", family: "Proxmox", note: "Run your own virtual machines." },
];

export function osById(id: string): DedicatedOs | null {
  return DEDICATED_OS.find((o) => o.id === id) ?? null;
}

/**
 * Billing terms. The pricing rules define one monthly price; a 12-month term is
 * that price x 12 paid up front (no discount exists in the rules, so none is
 * shown or applied). Renewal is stated as charged: "$X/yr", never a monthly split.
 */
export const DEDICATED_TERMS = [1, 12] as const;
export type DedicatedTerm = (typeof DEDICATED_TERMS)[number];

export function isDedicatedTerm(n: unknown): n is DedicatedTerm {
  return n === 1 || n === 12;
}

export const usd = (cents: number) =>
  `$${(Math.round(cents) / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

/** The renewal as it is charged: "$189.99/mo", "$2,279.88/yr", "$549.00 every 3 months". */
export function renewalLabel(monthlyCents: number, termMonths: number): string {
  const t = Math.max(1, Math.round(termMonths || 1));
  const total = monthlyCents * t;
  if (t === 1) return `${usd(total)}/mo`;
  if (t === 12) return `${usd(total)}/yr`;
  return `${usd(total)} every ${t} months`;
}

export function termLabel(termMonths: number): string {
  return termMonths === 12 ? "Annual" : termMonths === 1 ? "Monthly" : `Every ${termMonths} months`;
}

/** Customer promise for an in-stock build. */
export const SETUP_ETA = "Online within 24 hours";

export type DedicatedOrderIntent = {
  /** Catalogue item id of the regional build (opaque id, not an upstream code). */
  itemId: string;
  /** Nxeon region code, e.g. "sgp1". */
  region: string;
  os: string;
  termMonths: DedicatedTerm;
  /** Chosen option ids per family; null = the build's default. */
  memoryId: string | null;
  storageId: string | null;
  bandwidthId: string | null;
  /** Customer label for the machine. */
  label: string;
  /** Client idempotency key: one key places at most one order. */
  orderKey: string;
};

const ID_RE = /^[a-z0-9]{8,40}$/i;
const REGION_RE = /^[a-z]{3}\d$/;
const KEY_RE = /^[A-Za-z0-9_-]{12,64}$/;

/** Strict parser for anything that crosses the client/server or Stripe-metadata boundary. */
export function parseDedicatedIntent(raw: unknown): DedicatedOrderIntent | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const optId = (v: unknown) => (v == null || v === "" ? null : typeof v === "string" && ID_RE.test(v) ? v : undefined);
  const memoryId = optId(r.memoryId);
  const storageId = optId(r.storageId);
  const bandwidthId = optId(r.bandwidthId);
  const termMonths = r.termMonths;
  if (typeof r.itemId !== "string" || !ID_RE.test(r.itemId)) return null;
  if (typeof r.region !== "string" || !REGION_RE.test(r.region)) return null;
  if (typeof r.os !== "string" || !osById(r.os)) return null;
  if (!isDedicatedTerm(termMonths)) return null;
  if (memoryId === undefined || storageId === undefined || bandwidthId === undefined) return null;
  if (typeof r.orderKey !== "string" || !KEY_RE.test(r.orderKey)) return null;
  const label = typeof r.label === "string" ? r.label.replace(/[\u0000-\u001f<>]/g, "").trim().slice(0, 40) : "";
  return { itemId: r.itemId, region: r.region, os: r.os, termMonths, memoryId, storageId, bandwidthId, label, orderKey: r.orderKey };
}

/** The money for one order. All integer USD cents. */
export type DedicatedOrderMoney = {
  monthlyCents: number;
  termMonths: DedicatedTerm;
  /** monthly x term */
  termCents: number;
  setupCents: number;
  /** term + setup, before tax */
  netCents: number;
  taxCents: number;
  taxRatePercent: number;
  taxCountry: string;
  /** what is charged today */
  totalCents: number;
};

export function orderMoney(args: { monthlyCents: number; termMonths: DedicatedTerm; setupCents: number; taxRatePercent: number; taxCountry?: string }): DedicatedOrderMoney {
  const monthlyCents = Math.max(0, Math.round(args.monthlyCents));
  const setupCents = Math.max(0, Math.round(args.setupCents));
  const termCents = monthlyCents * args.termMonths;
  const netCents = termCents + setupCents;
  const rate = Number.isFinite(args.taxRatePercent) && args.taxRatePercent > 0 ? args.taxRatePercent : 0;
  const taxCents = Math.round((netCents * rate) / 100);
  return { monthlyCents, termMonths: args.termMonths, termCents, setupCents, netCents, taxCents, taxRatePercent: rate, taxCountry: rate > 0 ? args.taxCountry ?? "" : "", totalCents: netCents + taxCents };
}

/** Parse a price stamped into Stripe metadata (null when malformed). */
export function parseStampedMoney(raw: unknown): DedicatedOrderMoney | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as Record<string, unknown>;
  const int = (v: unknown) => (typeof v === "number" && Number.isInteger(v) && v >= 0 ? v : null);
  const monthly = int(r.monthlyCents), setup = int(r.setupCents), total = int(r.totalCents), tax = int(r.taxCents);
  const term = r.termMonths === 1 || r.termMonths === 12 ? r.termMonths : null;
  if (monthly == null || setup == null || total == null || tax == null || term == null) return null;
  const rate = typeof r.taxRatePercent === "number" && Number.isFinite(r.taxRatePercent) ? r.taxRatePercent : 0;
  const m = orderMoney({ monthlyCents: monthly, termMonths: term, setupCents: setup, taxRatePercent: 0 });
  // Re-derive the totals; refuse a stamp whose arithmetic doesn't add up.
  if (m.netCents + tax !== total) return null;
  return { ...m, taxCents: tax, taxRatePercent: rate, taxCountry: typeof r.taxCountry === "string" ? r.taxCountry.slice(0, 2) : "", totalCents: total };
}

/** Renewal date for a term starting at `from` (calendar months, clamped to month end). */
export function addMonths(from: Date, months: number): Date {
  const d = new Date(from.getTime());
  const day = d.getUTCDate();
  d.setUTCDate(1);
  d.setUTCMonth(d.getUTCMonth() + months);
  const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
  d.setUTCDate(Math.min(day, last));
  return d;
}

/** Status timeline for the customer dashboard. */
export type TimelineStep = { key: "ordered" | "building" | "online"; label: string; state: "done" | "current" | "todo"; at: string | null; note: string };

export function serverTimeline(s: { statusKey: string; orderedAt: string; provisionedAt: string | null }): TimelineStep[] {
  const k = s.statusKey;
  const online = k === "ACTIVE" || k === "SUSPENDED" || (k === "CANCELLED" && !!s.provisionedAt);
  const building = online || k === "PROVISIONING";
  return [
    { key: "ordered", label: "Order received", state: "done", at: s.orderedAt, note: "Payment confirmed. Your machine is reserved." },
    { key: "building", label: "Being built", state: building ? (online ? "done" : "current") : k === "PENDING" ? "current" : "todo", at: null, note: "Our engineers install your OS, harden it and run burn-in checks." },
    { key: "online", label: "Online", state: online ? "done" : "todo", at: s.provisionedAt, note: "IP addresses and your login appear here." },
  ];
}

/**
 * Dedicated-server CHECKOUT — the server side of /dashboard/dedicated/order.
 *
 *   catalogue  loadOrderCatalog()        brand-safe cards (one per hardware build)
 *   configure  loadOrderBuild(id)        one build's regions, options, in-stock combos, exact prices
 *   quote      quoteDedicatedOrder()     re-prices an intent from the pricing rules (never trusts the client)
 *   place      placeDedicatedOrder()     wallet debit + PAID invoice + DedicatedServer(PENDING), atomically
 *
 * Money path is the portal's standard wallet-then-card shape (same as the VPS /
 * dedicated-IP flows): quote -> walletSplit -> card remainder via a Stripe
 * Custom Checkout session whose metadata stamps the intent + the price ->
 * lib/fulfil-checkout.ts credits the card leg to the wallet and calls
 * placeDedicatedOrder with the STAMPED price. The wallet is only ever debited
 * here, once, guarded by a FulfilledSession claim on the order key.
 *
 * Nothing is provisioned automatically: the row lands as PENDING in
 * /admin/dedicated/servers and staff build the machine by hand. Upstream plan
 * codes, datacenters and costs are written ONLY to admin-only columns.
 *
 * Every function that returns data to a customer returns brand-safe fields only
 * (see lib/dedicated/customer-view.ts). Option and item ids are opaque cuids.
 */
import type { DedicatedCatalogItem, DedicatedCatalogOption, User } from "@prisma/client";
import { db } from "../db";
import { debitWallet, InsufficientBalanceError } from "../wallet";
import { invoiceCreateData } from "../invoices";
import { taxContextForUser } from "../tax";
import { assertSpendCap, SpendCapError } from "../spend-caps";
import { itemRegions, loadAvailability, loadRules, priceView, stockByDc, type AvailRow } from "./catalog-view";
import { catalogSnapshot, memo, type CatalogSnapshot } from "./catalog-snapshot";
import { disambiguateNames, nxFamily, nxName, NX_FAMILY_INFO, type NxFamily } from "./nx-names";
import { computeTags, type TagKind } from "./tags";
import { brandSafe, publicStock, type PublicStock } from "./customer-view";
import { regionByCode } from "./regions";
import { stockRank } from "./ovh-catalog";
import type { PricingRules } from "./pricing";
import { addMonths, orderMoney, osById, renewalLabel, termLabel, type DedicatedOrderIntent, type DedicatedOrderMoney } from "./order-core";

type ItemWithOptions = DedicatedCatalogItem & { options: DedicatedCatalogOption[] };

export class DedicatedOrderError extends Error {}

/** Stock codes a customer may order: delivered within 24h. */
export function orderableStock(code: string | undefined | null): boolean {
  const s = publicStock(code ?? "");
  return s === "in-stock" || s === "limited";
}

/* ---------------- loading ---------------- */

/**
 * Items a customer may order. Normally only items an admin marked `visible`.
 * `previewAll`: the private preview shows every live item while NO item has been
 * published yet, so the owner can test the flow before curating the catalogue.
 */
export async function orderPreviewAll(preview: boolean): Promise<boolean> {
  if (!preview) return false;
  const snap = await catalogSnapshot();
  return !snap.items.some((i) => i.visible);
}

/** Items this viewer may order, from the cached snapshot (lib/dedicated/catalog-snapshot.ts). */
function snapItems(snap: CatalogSnapshot, previewAll: boolean): ItemWithOptions[] {
  return previewAll ? snap.items : snap.items.filter((i) => i.visible);
}

const live = (o: DedicatedCatalogOption) => !o.removedAt;
const fam = (it: ItemWithOptions, f: string) => it.options.filter((o) => live(o) && o.family === f);
const defaultOf = (it: ItemWithOptions, f: string) => fam(it, f).find((o) => o.isDefault) ?? fam(it, f)[0] ?? null;

function hardwareKey(it: ItemWithOptions): string {
  return `${it.cpuBrand}|${it.cpuModel}|${it.cpuCount}|${it.defaultRamGb}|${it.defaultStorage}|${defaultOf(it, "gpu")?.label ?? ""}`;
}

/** Monthly option cost delta of a chosen option over its family default (never negative). */
function optionDelta(it: ItemWithOptions, f: string, chosen: DedicatedCatalogOption | null): number {
  if (!chosen) return 0;
  const d = defaultOf(it, f);
  return Math.max(0, chosen.monthlyCents - (d?.monthlyCents ?? 0));
}

function sellFor(it: ItemWithOptions, rules: PricingRules, mem: DedicatedCatalogOption | null, disk: DedicatedCatalogOption | null, bw: DedicatedCatalogOption | null) {
  const optCost = optionDelta(it, "memory", mem) + optionDelta(it, "storage", disk) + optionDelta(it, "bandwidth", bw);
  return { ...priceView(it, rules, optCost), optCost };
}

/** Best stock code for one memory x storage combo across a region's datacenters. */
function comboStock(rows: AvailRow[], dcs: string[], mem: DedicatedCatalogOption | null, disk: DedicatedCatalogOption | null): { code: string; dc: string | null } {
  const m = stockByDc(rows, { memory: mem?.productCode ?? null, storage: disk?.productCode ?? null });
  let best: { code: string; dc: string | null } = { code: "", dc: null };
  for (const dc of dcs) {
    const c = m.get(dc);
    if (c && (!best.code || stockRank(c) < stockRank(best.code))) best = { code: c, dc };
  }
  return best;
}

const bwText = (mbps: number | null) => (mbps == null ? "" : mbps >= 1000 ? `${+(mbps / 1000).toFixed(1)} Gbps` : `${mbps} Mbps`);

function optLabel(o: DedicatedCatalogOption): string {
  return brandSafe(o.label).replace(/\s*unmetered and guaranteed public bandwidth/i, " unmetered bandwidth");
}

function cpuText(it: ItemWithOptions): string {
  return brandSafe(`${it.cpuCount > 1 ? `${it.cpuCount}x ` : ""}${it.cpuBrand} ${it.cpuModel}`);
}

function totalStorageGb(label: string | null | undefined): number {
  let gb = 0;
  for (const m of (label ?? "").matchAll(/(\d+)\s*x\s*([\d.]+)\s*(TB|GB)/gi)) gb += Number(m[1]) * Number(m[2]) * (m[3].toUpperCase() === "TB" ? 1000 : 1);
  return Math.round(gb);
}

/* ---------------- customer projections ---------------- */

export type OrderRegion = { code: string; label: string; area: string; country: string; itemId: string; inStock: boolean; fromMonthlyCents: number; setupCents: number };

export type OrderCatalogCard = {
  id: string;
  /** Nxeon name, e.g. "NX-Forge 8-64" (lib/dedicated/nx-names.ts), or the admin's display name. */
  name: string;
  /** NX family ("NX-Forge"); `tier*` kept as aliases for older call sites. */
  family: NxFamily;
  tier: string;
  tierBlurb: string;
  tierOrder: number;
  /** Badges (lib/dedicated/tags.ts), already ordered by priority. */
  tags: TagKind[];
  cpu: string;
  cpuBrand: "AMD" | "Intel" | "Other";
  /** Default GPU fitted to the build ("2x NVIDIA L4"), null when none. */
  gpu: string | null;
  cores: number;
  threads: number;
  baseGhz: number | null;
  boostGhz: number | null;
  ramGb: number;
  maxRamGb: number;
  storage: string;
  storageGb: number;
  /** True when the build ships with no default disk and storage is picked when configuring. */
  storageChoose: boolean;
  bandwidth: string;
  fromMonthlyCents: number;
  regions: OrderRegion[];
};

export type OrderOption = { id: string; label: string; isDefault: boolean; extraMonthlyCents: number; ramGb: number | null };

export type OrderVariant = {
  region: string;
  label: string;
  area: string;
  country: string;
  itemId: string;
  setupCents: number;
  memory: OrderOption[];
  storage: OrderOption[];
  bandwidth: OrderOption[];
  /** "memoryId|storageId" pairs in stock (<= 24h) in this region; "" stands for a family with no options. */
  inStock: string[];
  /** Exact Nxeon monthly price per "memoryId|storageId|bandwidthId" for every in-stock combo. */
  prices: Record<string, number>;
};

export type OrderBuild = Omit<OrderCatalogCard, "regions"> & { variants: OrderVariant[] };

function nxInput(it: ItemWithOptions) {
  return {
    cpu: cpuText(it),
    cpuCount: it.cpuCount,
    cores: it.cpuCores * Math.max(1, it.cpuCount),
    ramGb: it.defaultRamGb ?? 0,
    gpu: defaultOf(it, "gpu") ? brandSafe(defaultOf(it, "gpu")!.label) : null,
  };
}

/** hardware key -> NX name, over EVERY live item (not just in-stock ones), so names don't shift with stock. */
function nxNames(snap: CatalogSnapshot): Map<string, string> {
  return memo(snap, "nx-names", () =>
    disambiguateNames(snap.items.map((it) => ({ key: hardwareKey(it), input: nxInput(it), sortKey: `${it.cpuModel}|${it.defaultStorage ?? ""}` }))));
}

function cardBase(it: ItemWithOptions, names?: Map<string, string>): Omit<OrderCatalogCard, "regions" | "fromMonthlyCents" | "tags"> {
  const family = nxFamily(nxInput(it));
  const t = NX_FAMILY_INFO[family];
  const cpu = cpuText(it);
  const mem = fam(it, "memory");
  const brand = /amd/i.test(it.cpuBrand) ? "AMD" : /intel/i.test(it.cpuBrand) ? "Intel" : "Other";
  const storageGb = totalStorageGb(it.defaultStorage);
  const disks = fam(it, "storage").filter((o) => totalStorageGb(o.label) > 0).sort((a, b) => a.monthlyCents - b.monthlyCents);
  const storageChoose = storageGb === 0 && disks.length > 0;
  return {
    id: it.id,
    name: brandSafe(it.displayName) || names?.get(hardwareKey(it)) || `${family} ${nxInput(it).cores}-${nxInput(it).ramGb}`,
    family,
    tier: family,
    tierBlurb: t.blurb,
    tierOrder: t.order,
    cpu,
    cpuBrand: brand,
    gpu: defaultOf(it, "gpu") ? brandSafe(defaultOf(it, "gpu")!.label) : null,
    cores: it.cpuCores * Math.max(1, it.cpuCount),
    threads: it.cpuThreads * Math.max(1, it.cpuCount),
    baseGhz: it.cpuFrequencyGhz,
    boostGhz: it.cpuBoostGhz,
    ramGb: it.defaultRamGb ?? 0,
    maxRamGb: Math.max(it.defaultRamGb ?? 0, ...mem.map((m) => m.ramGb ?? 0)),
    storage: storageChoose ? optLabel(disks[0]) : brandSafe(it.defaultStorage),
    storageGb: storageChoose ? totalStorageGb(disks[0].label) : storageGb,
    storageChoose,
    bandwidth: it.defaultBandwidthMbps ? bwText(it.defaultBandwidthMbps) : "",
  };
}

function anyComboInStock(it: ItemWithOptions, rows: AvailRow[], dcs: string[]): boolean {
  const mems: (DedicatedCatalogOption | null)[] = fam(it, "memory").length ? fam(it, "memory") : [null];
  const disks: (DedicatedCatalogOption | null)[] = fam(it, "storage").length ? fam(it, "storage") : [null];
  for (const m of mems) for (const d of disks) if (orderableStock(comboStock(rows, dcs, m, d).code)) return true;
  return false;
}

/** Regions (offered, not hidden) for one item with "any combo in stock" and the default price. */
function regionsFor(it: ItemWithOptions, rows: AvailRow[], rules: PricingRules, enabled: Set<string>): OrderRegion[] {
  const any = stockByDc(rows);
  const price = priceView(it, rules);
  return itemRegions(it.datacenters, any, enabled, it.hiddenRegions)
    .filter((r) => r.offered && !r.hidden && !r.code.startsWith("unmapped:"))
    .map((r) => ({
      code: r.code,
      label: r.customerLabel,
      area: r.area,
      country: r.country,
      itemId: it.id,
      // In stock = at least one combination of THIS item's own memory x storage
      // options is deliverable within 24h (the feed also lists configurations the
      // item does not sell, so "any row in stock" is not enough).
      inStock: r.dcs.some((dc) => orderableStock(any.get(dc))) && anyComboInStock(it, rows, r.dcs),
      fromMonthlyCents: price.sellMonthly,
      setupCents: price.sellSetup,
    }));
}

/** The catalogue: one card per hardware build, regional variants merged (cheapest per region wins). Cached per snapshot. */
export async function loadOrderCatalog(previewAll: boolean): Promise<OrderCatalogCard[]> {
  const snap = await catalogSnapshot();
  return memo(snap, `catalog:${previewAll}`, () => buildCatalog(snap, previewAll));
}

function buildCatalog(snap: CatalogSnapshot, previewAll: boolean): OrderCatalogCard[] {
  const { rules, enabledRegions } = snap;
  const names = nxNames(snap);
  const items = snapItems(snap, previewAll);
  const groups = new Map<string, OrderCatalogCard & { _items: ItemWithOptions[] }>();
  for (const it of items) {
    const regions = regionsFor(it, snap.avail.get(it.planCode) ?? [], rules, enabledRegions);
    if (!regions.length) continue;
    const key = hardwareKey(it);
    const g = groups.get(key);
    if (!g) {
      groups.set(key, { ...cardBase(it, names), tags: [], regions, fromMonthlyCents: Math.min(...regions.map((r) => r.fromMonthlyCents)), _items: [it] });
      continue;
    }
    g._items.push(it);
    for (const r of regions) {
      const have = g.regions.find((x) => x.code === r.code);
      if (!have) g.regions.push(r);
      else if ((r.inStock && !have.inStock) || (r.inStock === have.inStock && r.fromMonthlyCents < have.fromMonthlyCents)) Object.assign(have, r);
    }
  }
  const all = [...groups.values()];
  for (const c of all) {
    const inStock = c.regions.filter((r) => r.inStock);
    c.fromMonthlyCents = Math.min(...(inStock.length ? inStock : c.regions).map((r) => r.fromMonthlyCents));
    c.regions.sort((a, b) => Number(b.inStock) - Number(a.inStock) || a.label.localeCompare(b.label));
  }
  const tags = computeTags(all.map((c) => ({
    key: c.id,
    family: c.family,
    cores: c.cores,
    threads: c.threads,
    ramGb: c.ramGb,
    baseGhz: c.baseGhz,
    boostGhz: c.boostGhz,
    gpu: c.gpu,
    fromMonthlyCents: c.fromMonthlyCents,
    inStock: c.regions.some((r) => r.inStock),
    pinned: c._items.some((i) => i.popularPinned),
    orders: c._items.reduce((n, i) => n + (snap.orders.get(i.id) ?? 0), 0),
    firstSeenAt: new Date(Math.min(...c._items.map((i) => i.firstSeenAt.getTime()))),
  })));
  return all
    .map(({ _items, ...c }) => ({ ...c, tags: tags.get(c.id) ?? [] }))
    .sort((a, b) => a.fromMonthlyCents - b.fromMonthlyCents);
}

/** One build for the configurator (null when it is not orderable by this viewer). */
export async function loadOrderBuild(id: string, previewAll: boolean): Promise<OrderBuild | null> {
  const snap = await catalogSnapshot();
  return memo(snap, `build:${previewAll}:${id}`, () => buildOne(snap, id, previewAll));
}

function buildOne(snap: CatalogSnapshot, id: string, previewAll: boolean): OrderBuild | null {
  const pool = snapItems(snap, previewAll);
  const seed = pool.find((i) => i.id === id);
  if (!seed) return null;
  const key = hardwareKey(seed);
  const { rules, enabledRegions } = snap;
  const siblings = pool.filter((it) => hardwareKey(it) === key);
  const avail = snap.avail;
  const byRegion = new Map<string, OrderVariant & { _rank: number }>();
  for (const it of siblings) {
    const rows = avail.get(it.planCode) ?? [];
    const mems = fam(it, "memory");
    const disks = fam(it, "storage");
    const bws = fam(it, "bandwidth");
    const memList: (DedicatedCatalogOption | null)[] = mems.length ? mems : [null];
    const diskList: (DedicatedCatalogOption | null)[] = disks.length ? disks : [null];
    const bwList: (DedicatedCatalogOption | null)[] = bws.length ? bws : [null];
    const base = sellFor(it, rules, defaultOf(it, "memory"), defaultOf(it, "storage"), defaultOf(it, "bandwidth"));
    const extra = (f: "memory" | "storage" | "bandwidth", o: DedicatedCatalogOption) =>
      sellFor(it, rules, f === "memory" ? o : defaultOf(it, "memory"), f === "storage" ? o : defaultOf(it, "storage"), f === "bandwidth" ? o : defaultOf(it, "bandwidth")).sellMonthly - base.sellMonthly;
    const view = (f: "memory" | "storage" | "bandwidth", list: DedicatedCatalogOption[]): OrderOption[] =>
      list
        .map((o) => ({ id: o.id, label: optLabel(o), isDefault: o.id === defaultOf(it, f)?.id, extraMonthlyCents: Math.max(0, extra(f, o)), ramGb: o.ramGb }))
        .sort((a, b) => a.extraMonthlyCents - b.extraMonthlyCents);
    for (const r of itemRegions(it.datacenters, stockByDc(rows), enabledRegions, it.hiddenRegions)) {
      if (!r.offered || r.hidden || r.code.startsWith("unmapped:")) continue;
      const inStock: string[] = [];
      const prices: Record<string, number> = {};
      for (const m of memList) for (const d of diskList) {
        if (!orderableStock(comboStock(rows, r.dcs, m, d).code)) continue;
        inStock.push(`${m?.id ?? ""}|${d?.id ?? ""}`);
        for (const b of bwList) prices[`${m?.id ?? ""}|${d?.id ?? ""}|${b?.id ?? ""}`] = sellFor(it, rules, m, d, b).sellMonthly;
      }
      const v: OrderVariant & { _rank: number } = {
        region: r.code, label: r.customerLabel, area: r.area, country: r.country, itemId: it.id, setupCents: base.sellSetup,
        memory: view("memory", mems), storage: view("storage", disks), bandwidth: view("bandwidth", bws), inStock, prices,
        _rank: (inStock.length ? 0 : 1e9) + base.sellMonthly,
      };
      const prev = byRegion.get(r.code);
      if (!prev || v._rank < prev._rank) byRegion.set(r.code, v);
    }
  }
  if (byRegion.size === 0) return null;
  const variants = [...byRegion.values()].map(({ _rank, ...v }) => v);
  variants.sort((a, b) => Number(b.inStock.length > 0) - Number(a.inStock.length > 0) || a.label.localeCompare(b.label));
  const card = cardBase(seed, nxNames(snap));
  const listed = memo(snap, `catalog:${previewAll}`, () => buildCatalog(snap, previewAll)).find((c) => c.id === seed.id || siblings.some((x) => x.id === c.id));
  const all = variants.flatMap((v) => Object.values(v.prices));
  return { ...card, tags: listed?.tags ?? [], fromMonthlyCents: all.length ? Math.min(...all) : priceView(seed, rules).sellMonthly, variants };
}

/* ---------------- quote ---------------- */

export type DedicatedSpec = { name: string; family: NxFamily; cpu: string; cores: number; threads: number; ramGb: number; storage: string; bandwidth: string; gpu: string | null };

export type InternalQuote = {
  item: ItemWithOptions;
  memory: DedicatedCatalogOption | null;
  storage: DedicatedCatalogOption | null;
  bandwidth: DedicatedCatalogOption | null;
  /** ADMIN-ONLY */
  datacenter: string | null;
  /** ADMIN-ONLY */
  costMonthlyCents: number;
  stock: PublicStock;
  spec: DedicatedSpec;
  regionLabel: string;
  osLabel: string;
  money: DedicatedOrderMoney;
};

/** What a customer may see of a quote. */
export type CustomerQuote = {
  spec: DedicatedSpec;
  regionLabel: string;
  osLabel: string;
  termLabel: string;
  renewal: string;
  stock: PublicStock;
  money: DedicatedOrderMoney;
};

export function toCustomerQuote(q: InternalQuote): CustomerQuote {
  return {
    spec: q.spec,
    regionLabel: q.regionLabel,
    osLabel: q.osLabel,
    termLabel: termLabel(q.money.termMonths),
    renewal: renewalLabel(q.money.monthlyCents, q.money.termMonths),
    stock: q.stock,
    money: q.money,
  };
}

function pickOption(it: ItemWithOptions, f: string, id: string | null): DedicatedCatalogOption | null {
  const list = fam(it, f);
  if (!list.length) {
    if (id) throw new DedicatedOrderError("That option isn't available for this build.");
    return null;
  }
  if (!id) return defaultOf(it, f);
  const o = list.find((x) => x.id === id);
  if (!o) throw new DedicatedOrderError("That option isn't available for this build any more. Please pick again.");
  return o;
}

/**
 * Re-price an intent from the catalogue + pricing rules. Throws DedicatedOrderError
 * with a customer-safe message when the build, region, option or stock is not orderable.
 * `requireStock` is false only at card-leg fulfilment (the card already cleared; a
 * stock change in the meantime is handled by staff, never by eating the payment).
 */
export async function quoteDedicatedOrder(
  intent: DedicatedOrderIntent,
  user: Pick<User, "billingCountry" | "vatId">,
  opts: { previewAll: boolean; requireStock?: boolean },
): Promise<InternalQuote> {
  const item = await db.dedicatedCatalogItem.findFirst({
    where: { id: intent.itemId, currency: "USD", ...(opts.requireStock === false ? {} : { removedAt: null, ...(opts.previewAll ? {} : { visible: true }) }) },
    include: { options: true },
  });
  if (!item) throw new DedicatedOrderError("This build is no longer available.");
  const os = osById(intent.os);
  if (!os) throw new DedicatedOrderError("Pick an operating system.");
  const region = regionByCode(intent.region);
  if (!region) throw new DedicatedOrderError("Pick a location.");
  const { rules, enabledRegions } = await loadRules();
  const rows = (await loadAvailability([item.planCode])).get(item.planCode) ?? [];
  const regionRow = itemRegions(item.datacenters, stockByDc(rows), enabledRegions, item.hiddenRegions).find((r) => r.code === intent.region);
  if (!regionRow || (opts.requireStock !== false && (!regionRow.offered || regionRow.hidden))) throw new DedicatedOrderError("This build isn't offered in that location.");

  const memory = pickOption(item, "memory", intent.memoryId);
  const storage = pickOption(item, "storage", intent.storageId);
  const bandwidth = pickOption(item, "bandwidth", intent.bandwidthId);
  const st = comboStock(rows, regionRow.dcs, memory, storage);
  const stock = publicStock(st.code);
  if (opts.requireStock !== false && !orderableStock(st.code)) {
    throw new DedicatedOrderError(`That configuration isn't in stock in ${region.customerLabel} right now. Try another memory or storage choice, or another location.`);
  }
  const price = sellFor(item, rules, memory, storage, bandwidth);
  const tax = await taxContextForUser(user);
  const money = orderMoney({ monthlyCents: price.sellMonthly, termMonths: intent.termMonths, setupCents: price.sellSetup, taxRatePercent: tax.ratePercent, taxCountry: tax.country });
  const fallbackDc = regionRow.dcs[0] ?? null;
  return {
    item,
    memory,
    storage,
    bandwidth,
    datacenter: st.dc ?? fallbackDc,
    costMonthlyCents: price.costMonthly,
    stock,
    spec: {
      name: brandSafe(item.displayName) || nxNames(await catalogSnapshot()).get(hardwareKey(item)) || nxName(nxInput(item)),
      family: nxFamily(nxInput(item)),
      cpu: cpuText(item),
      cores: item.cpuCores * Math.max(1, item.cpuCount),
      threads: item.cpuThreads * Math.max(1, item.cpuCount),
      ramGb: memory?.ramGb ?? item.defaultRamGb ?? 0,
      storage: storage ? optLabel(storage) : brandSafe(item.defaultStorage),
      bandwidth: bandwidth ? optLabel(bandwidth) : item.defaultBandwidthMbps ? `${bwText(item.defaultBandwidthMbps)} public bandwidth` : "",
      gpu: defaultOf(item, "gpu") ? brandSafe(defaultOf(item, "gpu")!.label) : null,
    },
    regionLabel: region.customerLabel,
    osLabel: os.label,
    money,
  };
}

/* ---------------- place ---------------- */

/** Claim an order key exactly once (FulfilledSession's UNIQUE id is the lock). */
async function claimOrderKey(userId: string, orderKey: string): Promise<boolean> {
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: `dedorder:${userId}:${orderKey}`, kind: "dedicatedOrder" } });
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false;
    throw e;
  }
}

/**
 * Debit the wallet for the order total, write the PAID invoice and the PENDING
 * DedicatedServer row — one transaction. `sold` is the price stamped before a card
 * leg cleared (fulfilment path); omitted on the wallet-only path, where the price
 * is the fresh quote taken in the same request. Idempotent on intent.orderKey:
 * a repeat returns the server created the first time.
 */
export async function placeDedicatedOrder(
  user: User,
  intent: DedicatedOrderIntent,
  opts: { previewAll: boolean; sold?: DedicatedOrderMoney | null; via: "wallet" | "card" },
): Promise<{ serverId: string; created: boolean }> {
  const existing = await db.dedicatedServer.findFirst({ where: { userId: user.id, orderKey: intent.orderKey }, select: { id: true } });
  if (existing) return { serverId: existing.id, created: false };

  const q = await quoteDedicatedOrder(intent, user, { previewAll: opts.previewAll, requireStock: opts.via === "wallet" });
  const money = opts.sold ?? q.money;
  if (!(await claimOrderKey(user.id, intent.orderKey))) {
    const again = await db.dedicatedServer.findFirst({ where: { userId: user.id, orderKey: intent.orderKey }, select: { id: true } });
    if (again) return { serverId: again.id, created: false };
    throw new DedicatedOrderError("This order is already being placed. Refresh in a moment.");
  }

  const now = new Date();
  const renewalDate = addMonths(now, money.termMonths);
  const nxLabel = q.spec.name;
  const label = intent.label || `${nxLabel} · ${q.regionLabel}`;
  const desc = `Bare Metal Dedicated Server — ${label}`;
  const lines = [
    {
      description:
        `${nxLabel}: ${q.spec.cpu}, ${q.spec.ramGb} GB RAM, ${q.spec.storage}${q.spec.bandwidth ? `, ${q.spec.bandwidth}` : ""} · ${q.regionLabel} · ${q.osLabel}\n` +
        `${termLabel(money.termMonths)} term · renews ${renewalLabel(money.monthlyCents, money.termMonths)} on ${renewalDate.toISOString().slice(0, 10)}`,
      qty: 1,
      unitCents: money.termCents,
      amountCents: money.termCents,
    },
    ...(money.setupCents > 0 ? [{ description: "One-time setup", qty: 1, unitCents: money.setupCents, amountCents: money.setupCents }] : []),
  ];
  const orderConfig = {
    via: opts.via,
    catalogItemId: q.item.id,
    planCode: q.item.planCode, // ADMIN-ONLY (orderConfig never reaches a customer view)
    memory: q.memory ? { id: q.memory.id, label: q.memory.label, productCode: q.memory.productCode } : null,
    storage: q.storage ? { id: q.storage.id, label: q.storage.label, productCode: q.storage.productCode } : null,
    bandwidth: q.bandwidth ? { id: q.bandwidth.id, label: q.bandwidth.label, productCode: q.bandwidth.productCode } : null,
    os: intent.os,
    osLabel: q.osLabel,
    region: intent.region,
    datacenter: q.datacenter,
    stockAtOrder: q.stock,
    money,
  };

  try {
    const serverId = await db.$transaction(async (tx) => {
      await assertSpendCap(user, money.totalCents, tx);
      await debitWallet(tx, user.id, money.totalCents);
      await tx.walletTransaction.create({ data: { userId: user.id, amountCents: -money.totalCents, description: desc.slice(0, 190) } });
      const inv = await tx.invoice.create({
        data: invoiceCreateData({
          userId: user.id,
          description: desc.slice(0, 190),
          status: "PAID",
          lineItems: lines,
          taxCents: money.taxCents,
          taxRatePercent: money.taxRatePercent,
          taxCountry: money.taxCountry || null,
          period: { start: now, end: renewalDate },
        }),
        select: { id: true },
      });
      const s = await tx.dedicatedServer.create({
        data: {
          userId: user.id,
          label,
          catalogItemId: q.item.id,
          cpu: q.spec.cpu,
          cores: q.spec.cores,
          threads: q.spec.threads,
          ramGb: q.spec.ramGb,
          storage: q.spec.storage,
          bandwidth: q.spec.bandwidth,
          region: intent.region,
          datacenter: q.datacenter,
          costMonthlyCents: q.costMonthlyCents,
          os: q.osLabel,
          status: "PENDING",
          renewalDate,
          renewalMonthlyCents: money.monthlyCents,
          termMonths: money.termMonths,
          setupFeeCents: money.setupCents,
          invoiceIds: [inv.id],
          orderKey: intent.orderKey,
          orderConfig: orderConfig as object,
          notes: `Ordered online (${opts.via}). Build: ${q.item.planCode} in ${q.datacenter ?? "?"}; memory ${q.memory?.label ?? "default"}; storage ${q.storage?.label ?? "default"}; bandwidth ${q.bandwidth?.label ?? "default"}; OS ${q.osLabel}. Stock at order: ${q.stock}.`,
        },
        select: { id: true },
      });
      await tx.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, actorId: user.id, action: "ordered", detail: `paid ${money.totalCents}c via ${opts.via}; invoice ${inv.id}` } });
      await tx.auditLog.create({ data: { userId: user.id, action: "dedicated.order", detail: `${s.id} item=${q.item.id} region=${intent.region} total=${money.totalCents} via=${opts.via}` } });
      return s.id;
    });

    // Best-effort notices (never undo a placed, paid order).
    try {
      await db.notification.create({
        data: { userId: user.id, title: "Bare metal server ordered", body: `We're building ${label}. It will be online within 24 hours; we'll post its IP and login on the server page.`, href: `/dashboard/dedicated/${serverId}` },
      });
      const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
      if (admins.length) {
        await db.notification.createMany({
          data: admins.map((a) => ({ userId: a.id, title: `New bare metal order: ${label}`, body: `${user.email} paid ${renewalLabel(money.monthlyCents, money.termMonths)} (${q.regionLabel}). Build it by hand.`, href: `/admin/dedicated/servers/${serverId}` })),
        });
      }
    } catch {
      /* notices are best-effort */
    }
    return { serverId, created: true };
  } catch (e) {
    // Release the claim so a retry (after a top-up) can place the order.
    await db.fulfilledSession.delete({ where: { stripeSessionId: `dedorder:${user.id}:${intent.orderKey}` } }).catch(() => {});
    if (e instanceof InsufficientBalanceError) throw new DedicatedOrderError("Insufficient balance. Top up your wallet or pay the rest by card.");
    if (e instanceof SpendCapError) throw new DedicatedOrderError(e.message);
    throw e;
  }
}


/** The NX name of the build a machine was ordered from (null when unknown / withdrawn). */
export async function planNameForItem(itemId: string | null | undefined): Promise<string | null> {
  if (!itemId) return null;
  const snap = await catalogSnapshot();
  const it = snap.items.find((i) => i.id === itemId);
  if (!it) return null;
  return brandSafe(it.displayName) || nxNames(snap).get(hardwareKey(it)) || null;
}

/**
 * PURE + client-safe: which of the owner's server renders a bare-metal build
 * gets. Two sets, each sliced onto ONE shared transparent canvas per set and
 * bottom-aligned, so shown in equal boxes they keep their true relative size:
 * a bigger machine always looks bigger (public/nx/art/bm/README.md).
 *
 * CPU builds, public/nx/art/bm/tier-{1..4}.webp:
 *   4 Ultra   48+ cores
 *   3 Large   24-47 cores
 *   2 Medium  8-23 cores
 *   1 Small   fewer than 8 cores
 *
 * GPU builds (a GPU is fitted), public/nx/art/bm/gpu-{1..5}.webp, by GPU count:
 *   1 -> 1 GPU, 2 -> 2, 3 -> 3-4, 4 -> 5-7, 5 -> 8+
 *
 * Used by the portal catalogue, My Services and the NXM marketing page, so the
 * same build gets the same picture everywhere.
 */
export type SizeTier = 1 | 2 | 3 | 4;
export type GpuTier = 1 | 2 | 3 | 4 | 5;

export const SIZE_TIERS: SizeTier[] = [1, 2, 3, 4];
export const GPU_TIERS: GpuTier[] = [1, 2, 3, 4, 5];
export const SIZE_NAME: Record<SizeTier, string> = { 1: "Small", 2: "Medium", 3: "Large", 4: "Ultra" };
/** What each GPU size holds, for labels ("2 GPUs"). */
export const GPU_TIER_LABEL: Record<GpuTier, string> = { 1: "1 GPU", 2: "2 GPUs", 3: "3–4 GPUs", 4: "5–7 GPUs", 5: "8+ GPUs" };

/** CPU size by core count (GPU builds still get one, for anything that only shows CPU sizes). */
export function sizeTier(b: { cores: number }): SizeTier {
  if (b.cores >= 48) return 4;
  if (b.cores >= 24) return 3;
  if (b.cores >= 8) return 2;
  return 1;
}

/** "2x NVIDIA L4" -> 2; "NVIDIA A100" -> 1; null/empty -> 0. */
export function gpuCount(gpu: string | null | undefined): number {
  if (!gpu) return 0;
  const m = /^\s*(\d+)\s*[x×]/i.exec(gpu);
  return m ? Math.max(1, Number(m[1])) : 1;
}

export function gpuTier(gpu: string | null | undefined): GpuTier | null {
  const n = gpuCount(gpu);
  if (!n) return null;
  if (n >= 8) return 5;
  if (n >= 5) return 4;
  if (n >= 3) return 3;
  return n as 1 | 2;
}

export const sizeTierArt = (t: SizeTier) => `/nx/art/bm/tier-${t}.webp`;
export const gpuTierArt = (t: GpuTier) => `/nx/art/bm/gpu-${t}.webp`;

/** The render for one build: the GPU set when a GPU is fitted, else the CPU set. */
export function buildArt(b: { cores: number; gpu?: string | null }): string {
  const g = gpuTier(b.gpu);
  return g ? gpuTierArt(g) : sizeTierArt(sizeTier(b));
}
