}

/**
 * Dual-thumb range over a list of steps (index based, so uneven steps like
 * 32/64/128 GB work). Pointer-driven instead of two stacked native inputs:
 *  - while dragging, the thumbs follow the pointer continuously (no jumping
 *    between steps) and the readout updates instantly from LOCAL state; the
 *    parent is told about the new step range at most once per frame, and the
 *    parent applies it in a transition so the 77-build filter never blocks the drag;
 *  - on release the thumb eases to the nearest step;
 *  - the thumbs are real `role="slider"` elements: arrow keys, Home/End, PageUp/PageDown;
 *  - touch-action:none so a drag on a phone never scrolls the page.
 */
export function RangeSlider({ label, icon, steps, value, onChange, format }: {
  label: string;
  icon?: string;
  steps: number[];
  value: [number, number];
  onChange: (v: [number, number]) => void;
  format: (n: number, edge: "min" | "max") => string;
}) {
  const id = useId();
  const max = steps.length - 1;
  const track = useRef<HTMLDivElement>(null);
  const drag = useRef<"lo" | "hi" | null>(null);
  const raf = useRef(0);
  const pending = useRef<[number, number] | null>(null);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  // position in step units (floats while dragging, integers at rest)
  const [pos, setPos] = useState<[number, number]>(value);
  const [dragging, setDragging] = useState<"lo" | "hi" | null>(null);

  // follow the parent (reset, presets) whenever the user is not dragging
  useEffect(() => { if (!drag.current) setPos(value); }, [value]);
  useEffect(() => () => cancelAnimationFrame(raf.current), []);

  const idx = (x: number) => Math.round(Math.min(max, Math.max(0, x)));
  const lo = idx(pos[0]), hi = idx(pos[1]);
  const pct = (x: number) => (max === 0 ? 0 : (x / max) * 100);
  const active = lo > 0 || hi < max;

  const commit = useCallback((next: [number, number]) => {
    pending.current = next;
    if (raf.current) return;
    raf.current = requestAnimationFrame(() => {
      raf.current = 0;
      const v = pending.current; pending.current = null;
      if (v) onChangeRef.current(v);
    });
  }, []);

  const fromPointer = (clientX: number) => {
    const r = track.current?.getBoundingClientRect();
    if (!r || r.width === 0) return 0;
    return Math.min(1, Math.max(0, (clientX - r.left) / r.width)) * max;
  };
  const move = (which: "lo" | "hi", raw: number, from: [number, number]): [number, number] =>
    which === "lo" ? [Math.min(Math.max(0, raw), from[1]), from[1]] : [from[0], Math.max(Math.min(max, raw), from[0])];

  const startDrag = (which: "lo" | "hi", e: React.PointerEvent) => {
    drag.current = which; setDragging(which);
    (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId);
  };
  const onTrackDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).closest("[role=slider]")) return;
    const raw = fromPointer(e.clientX);
    // nearest thumb; on a tie, the side the click landed on
    const dLo = Math.abs(raw - pos[0]), dHi = Math.abs(raw - pos[1]);
    const which: "lo" | "hi" = dLo < dHi ? "lo" : dHi < dLo ? "hi" : raw > pos[1] ? "hi" : "lo";
    const next = move(which, raw, pos);
    setPos(next); commit([idx(next[0]), idx(next[1])]);
    // hand the pointer to that thumb so the drag continues smoothly
    const el = track.current?.querySelector<HTMLElement>(`[data-thumb="${which}"]`);
    drag.current = which; setDragging(which);
    el?.setPointerCapture?.(e.pointerId);
  };
  const onThumbMove = (e: React.PointerEvent) => {
    const which = drag.current; if (!which) return;
    const next = move(which, fromPointer(e.clientX), pos);
    if (next[0] === pos[0] && next[1] === pos[1]) return;
    setPos(next);
    const a: [number, number] = [idx(next[0]), idx(next[1])];
    if (a[0] !== value[0] || a[1] !== value[1]) commit(a);
  };
  const endDrag = () => {
    if (!drag.current) return;
    drag.current = null; setDragging(null);
    const snapped: [number, number] = [idx(pos[0]), idx(pos[1])];
    setPos(snapped);              // ease to the nearest step
    commit(snapped);
  };
  const onKey = (which: "lo" | "hi") => (e: ReactKeyboardEvent) => {
    const cur = which === "lo" ? lo : hi;
    const d = e.key === "ArrowLeft" || e.key === "ArrowDown" ? -1 : e.key === "ArrowRight" || e.key === "ArrowUp" ? 1
      : e.key === "PageDown" ? -2 : e.key === "PageUp" ? 2 : 0;
    let target = cur + d;
    if (e.key === "Home") target = 0; else if (e.key === "End") target = max; else if (!d) return;
    e.preventDefault();
    const next = move(which, Math.min(max, Math.max(0, target)), [lo, hi]);
    setPos(next); commit(next);
  };

  const loOnTop = lo === hi && hi >= max / 2;   // so a pair parked at the top end can still be pulled apart
  const thumb = (which: "lo" | "hi", at: number, v: number) => (
    <span
      key={which} role="slider" tabIndex={0} data-thumb={which}
      aria-label={`${label} ${which === "lo" ? "minimum" : "maximum"}`}
      aria-valuemin={0} aria-valuemax={max} aria-valuenow={v}
      aria-valuetext={format(steps[v], which === "lo" ? "min" : "max")}
      className={"bm-rs-thumb" + (dragging === which ? " bm-rs-thumb-on" : "")}
      style={{ left: `${pct(at)}%`, zIndex: dragging === which ? 4 : (which === "lo") === loOnTop ? 3 : 2 }}
      onPointerDown={(e) => startDrag(which, e)} onPointerMove={onThumbMove}
      onPointerUp={endDrag} onPointerCancel={endDrag} onLostPointerCapture={endDrag}
      onKeyDown={onKey(which)}
    />
  );

  return (
    <div className="flex min-w-0 flex-col gap-2.5">
      <div className="flex items-center justify-between gap-2">
        <span className="flex min-w-0 items-center gap-2" id={`${id}-l`}>
          {icon && <span className="bm-rs-ico"><Icon name={icon} size={11} tone="inherit" /></span>}
          <span className="bm-label !mb-0 truncate">{label}</span>
        </span>
        <span className={"bm-rs-val bm-num " + (active ? "bm-rs-val-on" : "")}>
          {!active ? "Any" : `${format(steps[lo], "min")} – ${format(steps[hi], "max")}`}
        </span>
      </div>
      <div ref={track} className={"bm-rs" + (dragging ? " bm-rs-dragging" : "")} onPointerDown={onTrackDown} aria-labelledby={`${id}-l`}>
        <span className="bm-rs-rail" />
        {steps.map((_, i) => <span key={i} aria-hidden className="bm-rs-tick" style={{ left: `${pct(i)}%` }} data-in={i >= lo && i <= hi ? "1" : "0"} />)}
        <span className="bm-rs-fill" style={{ left: `${pct(pos[0])}%`, width: `${Math.max(0, pct(pos[1]) - pct(pos[0]))}%` }} />
        {thumb("lo", pos[0], lo)}
        {thumb("hi", pos[1], hi)}
      </div>
    </div>
  );
}

/**
 * A styled dropdown (listbox): replaces the unstyled native <select>. Keyboard:
 * Enter/Space/ArrowDown open, arrows move, Enter picks, Esc/Tab close, Home/End.
 * Closes on an outside press.
 */
export function Dropdown<T extends string>({ value, options, onChange, ariaLabel, icon, align = "right" }: {
  value: T;
  options: { value: T; label: string; icon?: string; hint?: string }[];
  onChange: (v: T) => void;
  ariaLabel: string;
  icon?: string;
  align?: "left" | "right";
}) {
  const id = useId();
  const [open, setOpen] = useState(false);
  const cur = options.find((o) => o.value === value) ?? options[0];
  const [hot, setHot] = useState(0);
  const root = useRef<HTMLDivElement>(null);
  const btn = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!open) return;
    const away = (e: PointerEvent) => { if (!root.current?.contains(e.target as Node)) setOpen(false); };
    document.addEventListener("pointerdown", away);
    return () => document.removeEventListener("pointerdown", away);
  }, [open]);

  const openMenu = () => { setHot(Math.max(0, options.findIndex((o) => o.value === value))); setOpen(true); };
  const pick = (i: number) => { onChange(options[i].value); setOpen(false); btn.current?.focus(); };
  const onKey = (e: ReactKeyboardEvent) => {
    if (!open) { if (e.key === "ArrowDown" || e.key === "ArrowUp" || e.key === "Enter" || e.key === " ") { e.preventDefault(); openMenu(); } return; }
    if (e.key === "Escape") { e.preventDefault(); setOpen(false); btn.current?.focus(); }
    else if (e.key === "Tab") setOpen(false);
    else if (e.key === "ArrowDown") { e.preventDefault(); setHot((h) => (h + 1) % options.length); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setHot((h) => (h - 1 + options.length) % options.length); }
    else if (e.key === "Home") { e.preventDefault(); setHot(0); }
    else if (e.key === "End") { e.preventDefault(); setHot(options.length - 1); }
    else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(hot); }
  };

  return (
    <div ref={root} className="bm-dd" onKeyDown={onKey}>
      <button ref={btn} type="button" className="bm-dd-btn" aria-haspopup="listbox" aria-expanded={open} aria-label={`${ariaLabel}: ${cur.label}`}
              aria-controls={`${id}-m`} onClick={() => (open ? setOpen(false) : openMenu())}>
        {icon && <Icon name={icon} size={13} tone="inherit" className="bm-dd-ico" />}
        <span className="min-w-0 flex-1 truncate text-left">{cur.label}</span>
        <svg aria-hidden width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" className={"bm-dd-chev" + (open ? " bm-dd-chev-up" : "")}><path d="m6 9 6 6 6-6" /></svg>
      </button>
      {open && (
        <ul id={`${id}-m`} role="listbox" aria-label={ariaLabel} className={"bm-dd-menu " + (align === "right" ? "bm-dd-right" : "bm-dd-left")}>
          {options.map((o, i) => (
            <li key={o.value} role="option" aria-selected={o.value === value} data-hot={i === hot ? "1" : "0"}
                className="bm-dd-opt" onPointerEnter={() => setHot(i)} onClick={() => pick(i)}>
              {o.icon && <span className="bm-dd-oico"><Icon name={o.icon} size={12} tone="inherit" /></span>}
              <span className="min-w-0 flex-1"><span className="block truncate">{o.label}</span>{o.hint && <span className="block truncate text-[11px] font-medium bm-ink-3">{o.hint}</span>}</span>
              {o.value === value && <Icon name="check" size={13} tone="inherit" className="bm-dd-tick" />}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/** A modern check row: whole row is the target, animated tick, count on the right. */
export function CheckRow({ checked, onChange, disabled, children, count }: {
  checked: boolean; onChange: () => void; disabled?: boolean; children: ReactNode; count?: ReactNode;
}) {
  return (
    <label className={"bm-check" + (disabled ? " bm-check-off" : "")}>
      <input type="checkbox" className="sr-only" checked={checked} disabled={disabled} onChange={onChange} />
      <span className="bm-checkbox" aria-hidden>
        <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M3.5 8.5l3 3 6-6.5" pathLength="1" /></svg>
      </span>
      <span className="flex min-w-0 flex-1 items-center gap-2.5">{children}</span>
      {count != null && <span className="bm-check-count bm-num">{count}</span>}
    </label>
  );
}

