/* ── image picker ─────────────────────────────────────────────────────────
   One tab per ImageCategory. A tab with nothing in it is not rendered — an
   empty "Control panels" teaches the customer the feature is broken.

   Plain OS is grouped by FAMILY: each OsTemplate row is one version, so
   "Ubuntu 24.04", "Ubuntu 22.04" and "Ubuntu 20.04" are one card with three
   version chips, not three cards. Control panels and applications have one row
   each and need no second level. */
function ImagePicker() {
  const { o, set, cat } = useOrder();
  const TABS: [OsOption["category"], string][] = [
    ["PLAIN_OS", "Operating system"],
    ["CONTROL_PANEL", "Control panels"],
    ["APPLICATION", "Applications"],
  ];
  const available = TABS.filter(([k]) => cat.oses.some((x) => x.category === k));
  const [tab, setTab] = useState<OsOption["category"]>(available[0]?.[0] ?? "PLAIN_OS");
  const shown = useMemo(() => cat.oses.filter((x) => x.category === tab), [cat.oses, tab]);

  /* Families, in the order the platform sorts them, each with its versions
     newest-first the way the catalogue already orders them. */
  const families = useMemo(() => {
    const m = new Map<string, OsOption[]>();
    for (const x of shown) {
      const list = m.get(x.family) ?? [];
      list.push(x);
      m.set(x.family, list);
