/** Words that would reveal a third-party supplier. Case-insensitive. */
export const BANNED_TERMS = ["ovhcloud", "ovh", "kimsufi", "so you start", "soyoustart", "so-you-start", "vrack", "hgr"] as const;
const BANNED_RE = new RegExp(`\\b(${BANNED_TERMS.map((t) => t.replace(/[-\s]/g, "[-\\s]?")).join("|")})\\b`, "gi");
export function containsBannedTerm(s: string): boolean {
  BANNED_RE.lastIndex = 0;
  return BANNED_RE.test(s);
}
/** Strip any supplier-revealing token from a string (and tidy the gaps it leaves). */
export function brandSafe(s: string | null | undefined): string {
  if (!s) return "";
  return s
    .replace(BANNED_RE, "")
    .replace(/\(\s*\)/g, "")
    .replace(/\s{2,}/g, " ")
    .replace(/^[\s|·,-]+|[\s|·,-]+$/g, "")
    .trim();
}
/** The supplier's default reverse-DNS hostname pattern (e.g. ns123.ip-1-2-3.net) gives the supplier away. */
export function isUpstreamDefaultHostname(h: string): boolean {
  return /^ns\d+\.ip-\d+-\d+-\d+\.[a-z]+$/i.test(h.trim());
}
