    if (secret.length < 8) throw new Error("Password/secret must be at least 8 characters.");
    const s = await db.dedicatedServer.findUnique({ where: { id }, select: { id: true } });
    if (!s) throw new Error("Not found.");
    await db.dedicatedServer.update({ where: { id }, data: { credentialsUser: u, credentialsEnc: encryptSecret(secret), credentialsDeliveredAt: new Date() } });
    await event(id, admin.id, "credentials_delivered", `user ${u}`); // never the secret
    revalidatePath(`/admin/dedicated/servers/${id}`);
    return { ok: true };
  } catch (e) {
    return fail(e);
  }
}

export async function completeDedicatedRequest(requestId: string, status: "DONE" | "CANCELLED"): Promise<Result> {
  const admin = await requireAdmin();
  try {
    const r = await db.dedicatedServerRequest.findUnique({ where: { id: requestId }, select: { id: true, dedicatedServerId: true, kind: true, status: true } });
    if (!r || r.status !== "OPEN") throw new Error("Request not open.");
