/**
 * PURE + client-safe: the bare-metal ORDER TRACKER. Turns what our own records
 * know about an order (status, timestamps, the install job, the stock code at
 * order time, how long earlier orders took) into the customer's step tracker,
 * a progress figure and an honest wait estimate. No DB, no clock (pass `now`),
 * no supplier calls: the loader (lib/dedicated/tracking-load.ts) reads OUR rows
 * only, so the page never waits on an upstream API.
 *
 * CUSTOMER-FACING wording lives here (brand-voice checked): it speaks as the
 * owner of the data centers ("our Montreal data center") and never names a
 * supplier. Upstream free text (job step comments etc.) is never passed through.
 *
 * Contract for the backend (bm-ops): fill `TrackingFacts` from cached records.
 * Every field is optional except `statusKey` and `orderedAt`; a missing fact
 * just makes the tracker less specific, never wrong.
 *
 * Estimates (never invented):
 *   1. history  - when >= HISTORY_MIN earlier online orders were delivered, the
 *                 75th-percentile order-to-online time ("Typically ready within
 *                 about N hours", based on recent orders);
 *   2. stock    - otherwise the delivery window of the stock code the build had
 *                 when it was ordered (1H/24H = our 24-hour promise, 72H = 3 days,
 *                 240H = 10 days, ...);
 *   3. promise  - otherwise our standing promise for in-stock builds (24 hours).
 * An order is "delayed" once it is past max(estimate, window) and still not online,
 * or when an install attempt failed.
 */

export type TrackingStepKey = "received" | "paid" | "setup" | "install" | "ready";
export type TrackingStepState = "done" | "current" | "todo" | "delayed";

export type TrackingStep = {
  key: TrackingStepKey;
  label: string;
  state: TrackingStepState;
  /** When the step finished (done) or started (current/delayed); null when unknown. */
  at: string | null;
  note: string;
};

/** Cached supplier-side delivery phase, when the backend records one (never fetched at render). */
export type SupplierPhase = "ordered" | "delivering" | "delivered" | "error";

export type TrackingFacts = {
  /** DedicatedServer.status: PENDING | PROVISIONING | ACTIVE | SUSPENDED | CANCELLED */
  statusKey: string;
  /** Order placed (= paid: an order row only exists once payment cleared). ISO. */
  orderedAt: string;
  /** Payment confirmed, when recorded separately (defaults to orderedAt). */
  paidAt?: string | null;
  /** Staff/automation started building (the "provisioning" event). */
  buildStartedAt?: string | null;
  /** Cached supplier delivery phase + when it was last seen. */
  supplierPhase?: SupplierPhase | null;
  supplierPhaseAt?: string | null;
  /** The OS install / handover job, from our DedicatedJob row. */
  install?: { status: "QUEUED" | "RUNNING" | "WAITING" | "DONE" | "FAILED" | string; progress: number; startedAt: string | null; finishedAt: string | null } | null;
  /** DedicatedServer.provisionedAt. */
  deliveredAt?: string | null;
  cancelledAt?: string | null;
  /** Raw stock code when ordered ("1H-high", "24H", "72H", ...), or the public bucket ("in-stock", "made-to-order"). */
  availability?: string | null;
  /** Hours from order to online for earlier delivered orders (any order; recent first is fine). */
  historyHours?: number[];
  /** Customer-facing city/area of the location ("Montreal", "Singapore"). */
  locationLabel: string;
  /** Credentials and an IP are on the server page. */
  credentialsReady?: boolean;
  hasIp?: boolean;
};

export type TrackingEta = {
  /** "Typically ready within about 6 hours" / "Usually ready within 24 hours". */
  text: string;
  /** The estimate in hours (null when not estimable). */
  hours: number | null;
  /** When it should be ready by (ISO), from orderedAt + hours. */
  dueAt: string | null;
  basis: "history" | "stock" | "promise";
  /** Short explanation for a tooltip / small print. */
  basisText: string;
};

export type TrackingView = {
  steps: TrackingStep[];
  /** 0-100, from finished steps plus the install job's own progress. Never time-faked. */
  progress: number;
  /** The step in progress (null when delivered or ended). */
  current: TrackingStepKey | null;
  delivered: boolean;
  /** Cancelled before it went online. */
  ended: boolean;
  delayed: boolean;
  headline: string;
  sub: string;
  eta: TrackingEta | null;
  /** Elapsed since the order, "3h 20m". */
  elapsedText: string;
};

export const HISTORY_MIN = 3;
/** Our standing promise for in-stock builds (matches SETUP_ETA in order-core.ts). */
export const PROMISE_HOURS = 24;

const H = 3_600_000;
const iso = (d: Date) => d.toISOString();
const ms = (s: string | null | undefined) => (s ? Date.parse(s) : NaN);

/** Delivery window in hours for a stock code ("1H-low" -> 1, "72H" -> 72); null when unknown. */
export function availabilityHours(code: string | null | undefined): number | null {
  if (!code) return null;
  const m = /^(\d+)H/i.exec(code.trim());
  if (m) return Number(m[1]);
  if (code === "in-stock" || code === "limited") return PROMISE_HOURS;
  if (code === "made-to-order") return 72;
  return null;
}

/** p-th percentile (0-1) of a list, linear interpolation; null when empty. */
export function percentile(xs: number[], p: number): number | null {
  const v = xs.filter((x) => Number.isFinite(x) && x >= 0).sort((a, b) => a - b);
  if (!v.length) return null;
  const i = Math.min(v.length - 1, Math.max(0, (v.length - 1) * p));
  const lo = Math.floor(i), hi = Math.ceil(i);
  return v[lo] + (v[hi] - v[lo]) * (i - lo);
}

/** Friendly duration: 0.4 -> "1 hour", 5.2 -> "6 hours", 30 -> "2 days" (always rounds UP). */
export function waitText(hours: number): string {
  if (hours <= 1) return "1 hour";
  if (hours <= 36) return `${Math.ceil(hours)} hours`;
  const d = Math.ceil(hours / 24);
  return `${d} days`;
}

export function elapsedText(fromIso: string, now: Date): string {
  const m = Math.max(0, Math.floor((now.getTime() - ms(fromIso)) / 60_000));
  if (!Number.isFinite(m)) return "";
  if (m < 1) return "just now";
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 48) return `${h}h ${m % 60}m`;
  return `${Math.floor(h / 24)}d ${h % 24}h`;
}

/** The wait estimate (see the header for the order of evidence). */
export function estimateEta(f: Pick<TrackingFacts, "orderedAt" | "availability" | "historyHours">): TrackingEta {
  const hist = (f.historyHours ?? []).filter((x) => Number.isFinite(x) && x >= 0);
  const window = availabilityHours(f.availability);
  const at = (h: number) => { const t = ms(f.orderedAt); return Number.isFinite(t) ? iso(new Date(t + h * H)) : null; };
  if (hist.length >= HISTORY_MIN) {
    const p75 = percentile(hist, 0.75)!;
    // A machine from a slower stock window can't be quicker than that window says.
    const hours = Math.max(p75, window != null && window > PROMISE_HOURS ? window : 0, 0.5);
    return {
      text: `Typically ready within about ${waitText(hours)}`,
      hours,
      dueAt: at(hours),
      basis: "history",
      basisText: `Based on how long our last ${hist.length} bare metal orders took to come online.`,
    };
  }
  if (window != null) {
    const hours = Math.max(window, PROMISE_HOURS);
    return {
      text: `Usually ready within ${waitText(hours)}`,
      hours,
      dueAt: at(hours),
      basis: "stock",
      basisText: hours <= PROMISE_HOURS ? "This build was in stock when you ordered it." : "This configuration is built to order, which takes longer than in-stock builds.",
    };
  }
  return { text: `Usually ready within ${waitText(PROMISE_HOURS)}`, hours: PROMISE_HOURS, dueAt: at(PROMISE_HOURS), basis: "promise", basisText: "Our standard set-up time for in-stock builds." };
}

const STEP_WEIGHT: Record<TrackingStepKey, number> = { received: 5, paid: 10, setup: 45, install: 35, ready: 5 };

/** The whole tracker. */
export function trackOrder(f: TrackingFacts, now: Date): TrackingView {
  const k = f.statusKey;
  const loc = (f.locationLabel || "").trim();
  const setupLabel = loc ? `Someone at our ${loc} data center is setting up your dedicated server` : "Someone at our data center is setting up your dedicated server";
  const deliveredAt = f.deliveredAt ?? null;
  const delivered = k === "ACTIVE" || k === "SUSPENDED" || (!!deliveredAt && k !== "PENDING" && k !== "PROVISIONING");
  const ended = k === "CANCELLED" && !deliveredAt;
  const inst = f.install ?? null;
  const installFailed = inst?.status === "FAILED";
  const installing = !delivered && !!inst && !installFailed && inst.status !== "DONE" && (inst.status === "RUNNING" || inst.status === "WAITING");
  const installDone = delivered || inst?.status === "DONE";
  const hardwareReady = installDone || installing || f.supplierPhase === "delivered";
  const eta = delivered || ended ? null : estimateEta(f);
  const elapsedH = (now.getTime() - ms(f.orderedAt)) / H;
  const window = availabilityHours(f.availability);
  const limit = Math.max(eta?.hours ?? PROMISE_HOURS, window ?? 0, PROMISE_HOURS);
  const late = !delivered && !ended && Number.isFinite(elapsedH) && elapsedH > limit;
  const delayed = !delivered && !ended && (late || installFailed || f.supplierPhase === "error");

  const paidAt = f.paidAt ?? f.orderedAt;
  const setupStart = f.buildStartedAt ?? paidAt;
  const steps: TrackingStep[] = [
    { key: "received", label: "Order received", state: "done", at: f.orderedAt, note: "Your build is reserved for you." },
    { key: "paid", label: "Payment confirmed", state: "done", at: paidAt, note: "Your invoice is in Billing." },
    {
      key: "setup", label: setupLabel,
      state: ended ? "todo" : hardwareReady ? "done" : delayed ? "delayed" : "current",
      at: hardwareReady ? (inst?.startedAt ?? f.supplierPhaseAt ?? deliveredAt ?? null) : setupStart,
      note: hardwareReady ? "Hardware racked, cabled and tested."
        : delayed ? "This is taking longer than usual. Our team is on it, and you don't need to do anything."
        : f.supplierPhase === "delivering" || k === "PROVISIONING" ? "Your hardware is being racked, cabled and burn-in tested."
        : "Your machine is being prepared for its first boot.",
    },
    {
      key: "install", label: "Installing your operating system",
      state: ended ? "todo" : installDone ? "done" : installFailed ? "delayed" : installing ? "current" : "todo",
      at: installDone ? (inst?.finishedAt ?? deliveredAt) : installing || installFailed ? inst?.startedAt ?? null : null,
      note: installDone ? "Installed and hardened."
        : installFailed ? "The first install attempt didn't finish. Our team has been alerted and is retrying it."
        : installing ? `In progress${inst && inst.progress > 0 ? `, ${Math.min(99, Math.round(inst.progress))}% done` : ""}.`
        : "Your chosen system, with your SSH key.",
    },
    {
      key: "ready", label: "Ready", state: delivered ? "done" : "todo", at: delivered ? deliveredAt : null,
      note: delivered ? (f.credentialsReady || f.hasIp ? "IP address and login are on your server page." : "Online. Your IP address and login appear on your server page.") : "We'll notify you, and post its IP address and login on your server page.",
    },
  ];

  let progress = 0;
  for (const s of steps) {
    if (s.state === "done") progress += STEP_WEIGHT[s.key];
    else if (s.key === "install" && installing && inst) progress += (STEP_WEIGHT.install * Math.min(99, Math.max(0, inst.progress))) / 100;
  }
  progress = delivered ? 100 : Math.min(99, Math.round(progress));
  const cur = steps.find((s) => s.state === "current" || s.state === "delayed")?.key ?? null;

  let headline: string, sub: string;
  if (ended) { headline = "This order was cancelled"; sub = "Contact support if you have any questions about it."; }
  else if (delivered) { headline = "Your server is ready"; sub = "It's online. Its IP address and login are on the server page."; }
  else if (installFailed) { headline = "Almost there, with a short delay"; sub = "The operating system install is being retried by our team."; }
  else if (delayed) { headline = "Taking a little longer than usual"; sub = "Our team is on it. You don't need to do anything, and we'll notify you the moment it's online."; }
  else if (installing) { headline = "Installing your operating system"; sub = eta ? `${eta.text}.` : ""; }
  else { headline = loc ? `Setting up your server in ${loc}` : "Setting up your server"; sub = eta ? `${eta.text}.` : ""; }

  return { steps, progress, current: delivered || ended ? null : cur, delivered, ended, delayed, headline, sub, eta, elapsedText: elapsedText(f.orderedAt, now) };
}

/** True while the tracker should poll (not delivered, not cancelled). */
export const trackingActive = (v: Pick<TrackingView, "delivered" | "ended">) => !v.delivered && !v.ended;

/** Poll interval for the cached order record (never the supplier): 25 s. */
export const TRACKING_POLL_MS = 25_000;

