        : f.supplierPhase === "delivering" || k === "PROVISIONING" ? "Your hardware is being racked, cabled and burn-in tested."
        : "Your machine is being prepared for its first boot.",
    },
    {
      key: "install", label: "Installing your operating system",
      state: ended ? "todo" : installDone ? "done" : installFailed ? "delayed" : installing ? "current" : "todo",
      at: installDone ? (inst?.finishedAt ?? deliveredAt) : installing || installFailed ? inst?.startedAt ?? null : null,
      note: installDone ? "Installed and hardened."
        : installFailed ? "The first install attempt didn't finish. Our team has been alerted and is retrying it."
        : installing ? `In progress${inst && inst.progress > 0 ? `, ${Math.min(99, Math.round(inst.progress))}% done` : ""}.`
        : "Your chosen system, with your SSH key.",
    },
    {
      key: "ready", label: "Ready", state: delivered ? "done" : "todo", at: delivered ? deliveredAt : null,
      note: delivered ? (f.credentialsReady || f.hasIp ? "IP address and login are on your server page." : "Online. Your IP address and login appear on your server page.") : "We'll notify you, and post its IP address and login on your server page.",
    },
  ];

  let progress = 0;
  for (const s of steps) {
    if (s.state === "done") progress += STEP_WEIGHT[s.key];
    else if (s.key === "install" && installing && inst) progress += (STEP_WEIGHT.install * Math.min(99, Math.max(0, inst.progress))) / 100;
  }
  progress = delivered ? 100 : Math.min(99, Math.round(progress));
  const cur = steps.find((s) => s.state === "current" || s.state === "delayed")?.key ?? null;

  let headline: string, sub: string;
  if (ended) { headline = "This order was cancelled"; sub = "Contact support if you have any questions about it."; }
  else if (delivered) { headline = "Your server is ready"; sub = "It's online. Its IP address and login are on the server page."; }
  else if (installFailed) { headline = "Almost there, with a short delay"; sub = "The operating system install is being retried by our team."; }
  else if (delayed) { headline = "Taking a little longer than usual"; sub = "Our team is on it. You don't need to do anything, and we'll notify you the moment it's online."; }
  else if (installing) { headline = "Installing your operating system"; sub = eta ? `${eta.text}.` : ""; }
  else { headline = loc ? `Setting up your server in ${loc}` : "Setting up your server"; sub = eta ? `${eta.text}.` : ""; }

  return { steps, progress, current: delivered || ended ? null : cur, delivered, ended, delayed, headline, sub, eta, elapsedText: elapsedText(f.orderedAt, now) };
}

/** True while the tracker should poll (not delivered, not cancelled). */
export const trackingActive = (v: Pick<TrackingView, "delivered" | "ended">) => !v.delivered && !v.ended;

/** Poll interval for the cached order record (never the supplier): 25 s. */
export const TRACKING_POLL_MS = 25_000;

