/**
 * "our ___ data center" from a customer location label (lib/dedicated/regions.ts
 * customerLabel): "Canada (Montreal)" -> "Montreal", "France (Paris A)" -> "Paris",
 * "France (North 1)" -> "northern France", "United States (East)" -> "US East",
 * "Singapore" -> "Singapore". Only customer labels go in, so nothing upstream leaks.
 */
export function dataCenterName(customerLabel: string | null | undefined): string {
  const s = (customerLabel ?? "").trim();
  if (!s || /^other location$/i.test(s)) return "";
  const m = /^(.+?)\s*\((.+)\)$/.exec(s);
  if (!m) return s;
  const [, country, inner] = m;
  const dir = /^(North|South|East|West)\b/i.exec(inner)?.[1].toLowerCase();
  if (dir) {
    if (/^United States$/i.test(country)) return `US ${dir[0].toUpperCase()}${dir.slice(1)}`;
    return `${dir}ern ${country}`;
  }
  return inner.replace(/\s+[A-Z0-9]$/, "");
}

