import { test } from "node:test";
import assert from "node:assert/strict";
import {
  availabilityHours, dataCenterName, elapsedText, estimateEta, HISTORY_MIN, percentile, PROMISE_HOURS, trackOrder, trackingActive, waitText,
  type TrackingFacts,
} from "../lib/dedicated/tracking.ts";
import { DEDICATED_DC_REGIONS } from "../lib/dedicated/regions.ts";
import { containsBannedTerm } from "../lib/dedicated/customer-view.ts";

/** The bare-metal order tracker (lib/dedicated/tracking.ts): pure status + timestamps -> steps, progress, ETA. */

const T0 = "2026-10-08T10:00:00.000Z";
const at = (h: number) => new Date(Date.parse(T0) + h * 3_600_000);
const base: TrackingFacts = { statusKey: "PENDING", orderedAt: T0, locationLabel: "Montreal" };
const state = (v: ReturnType<typeof trackOrder>) => Object.fromEntries(v.steps.map((s) => [s.key, s.state]));

test("data center names come from the customer label only", () => {
  assert.equal(dataCenterName("Canada (Montreal)"), "Montreal");
  assert.equal(dataCenterName("Germany (Frankfurt)"), "Frankfurt");
  assert.equal(dataCenterName("France (Paris B)"), "Paris");
  assert.equal(dataCenterName("France (North 1)"), "northern France");
  assert.equal(dataCenterName("France (East)"), "eastern France");
  assert.equal(dataCenterName("United States (West)"), "US West");
  assert.equal(dataCenterName("Singapore"), "Singapore");
  assert.equal(dataCenterName("Other location"), "");
  assert.equal(dataCenterName(null), "");
  for (const r of Object.values(DEDICATED_DC_REGIONS)) {
    const v = trackOrder({ ...base, locationLabel: dataCenterName(r.customerLabel) }, at(1));
    const json = JSON.stringify(v);
    assert.equal(containsBannedTerm(json), false, `${r.customerLabel}: ${json}`);
    assert.ok(!json.includes(r.label.split(",")[0]) || r.customerLabel.includes(r.label.split(",")[0]), `admin city leaks for ${r.code}`);
  }
});

test("availability codes map to delivery windows", () => {
  assert.equal(availabilityHours("1H-high"), 1);
  assert.equal(availabilityHours("1H-low"), 1);
  assert.equal(availabilityHours("24H"), 24);
  assert.equal(availabilityHours("72H"), 72);
  assert.equal(availabilityHours("240H"), 240);
  assert.equal(availabilityHours("in-stock"), PROMISE_HOURS);
  assert.equal(availabilityHours("made-to-order"), 72);
  assert.equal(availabilityHours("unavailable"), null);
  assert.equal(availabilityHours(null), null);
});

test("percentile, wait and elapsed text", () => {
  assert.equal(percentile([], 0.5), null);
  assert.equal(percentile([4], 0.75), 4);
  assert.equal(percentile([1, 2, 3, 4, 5], 0.75), 4);
  assert.equal(percentile([2, 1, NaN, -3, 4], 0.5), 2);
  assert.equal(waitText(0.3), "1 hour");
  assert.equal(waitText(5.2), "6 hours");
  assert.equal(waitText(24), "24 hours");
  assert.equal(waitText(72), "3 days");
  assert.equal(elapsedText(T0, at(0)), "just now");
  assert.equal(elapsedText(T0, at(0.5)), "30m");
  assert.equal(elapsedText(T0, at(3.25)), "3h 15m");
  assert.equal(elapsedText(T0, at(50)), "2d 2h");
});

test("ETA: history beats the stock window, which beats the promise", () => {
  const h = estimateEta({ orderedAt: T0, availability: "1H-high", historyHours: [2, 3, 4, 5, 9] });
  assert.equal(h.basis, "history");
  assert.equal(h.hours, 5);
  assert.equal(h.text, "Typically ready within about 5 hours");
  assert.equal(h.dueAt, at(5).toISOString());

  const few = estimateEta({ orderedAt: T0, availability: "1H-high", historyHours: [2, 3].slice(0, HISTORY_MIN - 1) });
  assert.equal(few.basis, "stock");
  assert.equal(few.hours, 24, "fast stock still uses our 24h promise, never a 1-hour claim");
  assert.equal(few.text, "Usually ready within 24 hours");

  const slow = estimateEta({ orderedAt: T0, availability: "72H", historyHours: [] });
  assert.equal(slow.hours, 72);
  assert.equal(slow.text, "Usually ready within 3 days");

  const slowHist = estimateEta({ orderedAt: T0, availability: "72H", historyHours: [3, 4, 5] });
  assert.equal(slowHist.hours, 72, "a built-to-order window is never undercut by fast history");

  const none = estimateEta({ orderedAt: T0, availability: null });
  assert.equal(none.basis, "promise");
  assert.equal(none.hours, 24);
});

test("queued: received + paid done, data-center setup in progress", () => {
  const v = trackOrder({ ...base, availability: "24H" }, at(1));
  assert.deepEqual(state(v), { received: "done", paid: "done", setup: "current", install: "todo", ready: "todo" });
  assert.equal(v.current, "setup");
  assert.equal(v.progress, 15);
  assert.equal(v.delayed, false);
  assert.equal(v.steps[2].label, "Someone at our Montreal data center is setting up your dedicated server");
  assert.equal(v.headline, "Setting up your server in Montreal");
  assert.match(v.sub, /within 24 hours/);
  assert.ok(trackingActive(v));
});

test("provisioning started: setup step uses the build start time", () => {
  const v = trackOrder({ ...base, statusKey: "PROVISIONING", buildStartedAt: at(2).toISOString() }, at(3));
  assert.equal(v.steps[2].state, "current");
  assert.equal(v.steps[2].at, at(2).toISOString());
  assert.match(v.steps[2].note, /racked/);
});

test("installing: setup done, install current with the job's progress", () => {
  const v = trackOrder({ ...base, statusKey: "PROVISIONING", install: { status: "WAITING", progress: 40, startedAt: at(4).toISOString(), finishedAt: null } }, at(5));
  assert.deepEqual(state(v), { received: "done", paid: "done", setup: "done", install: "current", ready: "todo" });
  assert.equal(v.progress, 5 + 10 + 45 + 14);
  assert.equal(v.headline, "Installing your operating system");
  assert.match(v.steps[3].note, /40% done/);
});

test("delayed: past the window and not online", () => {
  const v = trackOrder({ ...base, availability: "24H" }, at(30));
  assert.equal(v.delayed, true);
  assert.equal(v.steps[2].state, "delayed");
  assert.equal(v.current, "setup");
  assert.match(v.headline, /longer than usual/);
  assert.ok(trackingActive(v));
  // not delayed one hour before the window ends
  assert.equal(trackOrder({ ...base, availability: "24H" }, at(23)).delayed, false);
  // built-to-order gets its own, longer window
  assert.equal(trackOrder({ ...base, availability: "72H" }, at(30)).delayed, false);
});

test("a failed install shows as a delay on the install step, never as an error code", () => {
  const v = trackOrder({ ...base, statusKey: "PROVISIONING", install: { status: "FAILED", progress: 100, startedAt: at(2).toISOString(), finishedAt: at(3).toISOString() } }, at(4));
  assert.equal(v.delayed, true);
  assert.equal(v.steps[3].state, "delayed");
  assert.equal(v.steps[2].state, "done");
  assert.ok(v.progress < 100);
});

test("supplier phase (cached) refines the setup step", () => {
  assert.match(trackOrder({ ...base, supplierPhase: "delivering" }, at(1)).steps[2].note, /racked/);
  assert.equal(trackOrder({ ...base, supplierPhase: "delivered", supplierPhaseAt: at(2).toISOString() }, at(3)).steps[2].state, "done");
  assert.equal(trackOrder({ ...base, supplierPhase: "error" }, at(1)).delayed, true);
});

test("delivered: everything done, 100%, no ETA, polling stops", () => {
  const v = trackOrder({ ...base, statusKey: "ACTIVE", deliveredAt: at(6).toISOString(), install: { status: "DONE", progress: 100, startedAt: at(4).toISOString(), finishedAt: at(6).toISOString() }, credentialsReady: true, hasIp: true }, at(7));
  assert.deepEqual(state(v), { received: "done", paid: "done", setup: "done", install: "done", ready: "done" });
  assert.equal(v.progress, 100);
  assert.equal(v.eta, null);
  assert.equal(v.current, null);
  assert.equal(v.delivered, true);
  assert.equal(v.steps[4].at, at(6).toISOString());
  assert.equal(trackingActive(v), false);
});

test("delivered by hand (no install job) still completes", () => {
  const v = trackOrder({ ...base, statusKey: "ACTIVE", deliveredAt: at(5).toISOString() }, at(6));
  assert.equal(v.progress, 100);
  assert.equal(v.steps[3].state, "done");
});

test("cancelled before delivery ends the tracker", () => {
  const v = trackOrder({ ...base, statusKey: "CANCELLED", cancelledAt: at(2).toISOString() }, at(3));
  assert.equal(v.ended, true);
  assert.equal(v.current, null);
  assert.equal(v.eta, null);
  assert.equal(trackingActive(v), false);
  assert.equal(v.headline, "This order was cancelled");
});

test("no location label still reads naturally", () => {
  const v = trackOrder({ ...base, locationLabel: "" }, at(1));
  assert.equal(v.steps[2].label, "Someone at our data center is setting up your dedicated server");
  assert.equal(v.headline, "Setting up your server");
});

