/**
 * DB side of the bare-metal order tracker: fills lib/dedicated/tracking.ts
 * `TrackingFacts` from OUR OWN records only (DedicatedServer, its events and
 * install job, and earlier orders' delivery times). Never calls the supplier,
 * so the server page, My Services and the tracker's 25 s poll render instantly
 * whatever the upstream API is doing.
 *
 * Brand-safe output only: the customer location label, never the datacenter
 * code; the install job's progress number, never its upstream step text.
 *
 * When the backend starts caching the supplier's delivery task (bm-ops), map it
 * onto `supplierPhase`/`supplierPhaseAt` in `factsFor` — nothing else changes.
 */
import type { DedicatedJob, DedicatedServer, DedicatedServerEvent } from "@prisma/client";
import { db } from "../db";
import { catalogSnapshot } from "./catalog-snapshot";
import { brandSafe } from "./customer-view";
import { customerDedicatedRegionLabel, regionByCode } from "./regions";
import { buildArt } from "./size-tier";
import { dataCenterName, trackOrder, type TrackingFacts, type TrackingView } from "./tracking";

export type CustomerTracking = {
  serverId: string;
  name: string;
  /** The size render for this machine (lib/dedicated/size-tier.ts). */
  art: string;
  /** "Canada (Montreal)" + its flag country. */
  location: string;
  country: string;
  view: TrackingView;
  /** When this snapshot of our records was read (the "Last updated" line). */
  fetchedAt: string;
};

/* ---------- delivery history (cached in-process for 5 minutes) ---------- */

const HISTORY_TTL_MS = 5 * 60_000;
let historyCache: { at: number; hours: number[] } | null = null;

/** Order-to-online hours of the most recent delivered ONLINE orders (180 days, newest 50). */
export async function deliveryHistoryHours(now = new Date()): Promise<number[]> {
  if (historyCache && now.getTime() - historyCache.at < HISTORY_TTL_MS) return historyCache.hours;
  const rows = await db.dedicatedServer.findMany({
    where: { orderKey: { not: null }, provisionedAt: { not: null }, createdAt: { gte: new Date(now.getTime() - 180 * 86_400_000) } },
    select: { createdAt: true, provisionedAt: true },
    orderBy: { provisionedAt: "desc" },
    take: 50,
  });
  const hours = rows.map((r) => (r.provisionedAt!.getTime() - r.createdAt.getTime()) / 3_600_000).filter((h) => h >= 0 && h < 24 * 60);
  historyCache = { at: now.getTime(), hours };
  return hours;
}

/** For tests / after a delivery: forget the cached history. */
export function resetDeliveryHistoryCache(): void {
  historyCache = null;
}

/* ---------- facts ---------- */

type Row = Pick<DedicatedServer, "id" | "status" | "createdAt" | "provisionedAt" | "cancelledAt" | "region" | "orderConfig" | "credentialsDeliveredAt" | "credentialsEnc" | "ipv4">;
type JobRow = Pick<DedicatedJob, "status" | "progress" | "startedAt" | "finishedAt" | "createdAt">;
type EventRow = Pick<DedicatedServerEvent, "action" | "createdAt">;

/** The stock code stamped at order time (raw code when recorded, else the public bucket). */
function availabilityAtOrder(cfg: unknown): string | null {
  if (!cfg || typeof cfg !== "object") return null;
  const c = cfg as { availabilityCode?: unknown; stockAtOrder?: unknown };
  if (typeof c.availabilityCode === "string" && c.availabilityCode) return c.availabilityCode;
  if (typeof c.stockAtOrder === "string" && c.stockAtOrder) return c.stockAtOrder;
  return null;
}

export function factsFor(s: Row, job: JobRow | null, events: EventRow[], historyHours: number[]): TrackingFacts {
  const buildStarted = events.filter((e) => e.action === "provisioning").sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime())[0];
  return {
    statusKey: s.status,
    orderedAt: s.createdAt.toISOString(),
    paidAt: s.createdAt.toISOString(),
    buildStartedAt: buildStarted?.createdAt.toISOString() ?? null,
    supplierPhase: null,
    supplierPhaseAt: null,
    install: job ? { status: job.status, progress: job.progress, startedAt: (job.startedAt ?? job.createdAt).toISOString(), finishedAt: job.finishedAt?.toISOString() ?? null } : null,
    deliveredAt: s.provisionedAt?.toISOString() ?? null,
    cancelledAt: s.cancelledAt?.toISOString() ?? null,
    availability: availabilityAtOrder(s.orderConfig),
    historyHours,
    locationLabel: dataCenterName(customerDedicatedRegionLabel(s.region)),
    credentialsReady: !!s.credentialsDeliveredAt && !!s.credentialsEnc,
    hasIp: s.ipv4.length > 0,
  };
}

/** GPU fitted to the build a machine came from (for its render); null when none / unknown. */
async function gpuFor(itemId: string | null): Promise<string | null> {
  if (!itemId) return null;
  try {
    const snap = await catalogSnapshot();
    const it = snap.items.find((i) => i.id === itemId);
    const g = it?.options.find((o) => o.family === "gpu" && !o.removedAt && o.isDefault) ?? it?.options.find((o) => o.family === "gpu" && !o.removedAt);
    return g ? brandSafe(g.label) : null;
  } catch {
    return null;
  }
}

/** Latest install (handover) job per server, and the "provisioning" events, in two queries. */
async function jobsAndEvents(ids: string[]) {
  const [jobs, events] = ids.length
    ? await Promise.all([
        db.dedicatedJob.findMany({ where: { dedicatedServerId: { in: ids }, kind: "HANDOVER" }, orderBy: { createdAt: "desc" }, select: { dedicatedServerId: true, status: true, progress: true, startedAt: true, finishedAt: true, createdAt: true } }),
        db.dedicatedServerEvent.findMany({ where: { dedicatedServerId: { in: ids }, action: "provisioning" }, select: { dedicatedServerId: true, action: true, createdAt: true } }),
      ])
    : [[], []];
  const job = new Map<string, JobRow>();
  for (const j of jobs) if (!job.has(j.dedicatedServerId)) job.set(j.dedicatedServerId, j);
  const ev = new Map<string, EventRow[]>();
  for (const e of events) ev.set(e.dedicatedServerId, [...(ev.get(e.dedicatedServerId) ?? []), e]);
  return { job, ev };
}

const SELECT = {
  id: true, userId: true, label: true, status: true, createdAt: true, provisionedAt: true, cancelledAt: true, region: true, orderConfig: true,
  credentialsDeliveredAt: true, credentialsEnc: true, ipv4: true, cores: true, catalogItemId: true,
} as const;

/** The tracker for one machine, ONLY when it belongs to `userId` (null skips the owner check: admin preview). */
export async function loadCustomerTracking(id: string, userId: string | null, now = new Date()): Promise<CustomerTracking | null> {
  const s = await db.dedicatedServer.findUnique({ where: { id }, select: SELECT });
  if (!s || (userId !== null && s.userId !== userId)) return null;
  const [{ job, ev }, hist, gpu] = await Promise.all([jobsAndEvents([s.id]), deliveryHistoryHours(now), gpuFor(s.catalogItemId)]);
  const region = regionByCode(s.region);
  return {
    serverId: s.id,
    name: brandSafe(s.label) || "Bare metal server",
    art: buildArt({ cores: s.cores, gpu }),
    location: customerDedicatedRegionLabel(s.region),
    country: region?.country ?? "",
    view: trackOrder(factsFor(s, job.get(s.id) ?? null, ev.get(s.id) ?? [], hist), now),
    fetchedAt: now.toISOString(),
  };
}

/** Trackers for several machines at once (My Services), for those not yet delivered. */
export async function trackingForServers(rows: Row[], now = new Date()): Promise<Map<string, TrackingView>> {
  const open = rows.filter((r) => r.status === "PENDING" || r.status === "PROVISIONING");
  const out = new Map<string, TrackingView>();
  if (!open.length) return out;
  const [{ job, ev }, hist] = await Promise.all([jobsAndEvents(open.map((r) => r.id)), deliveryHistoryHours(now)]);
  for (const r of open) out.set(r.id, trackOrder(factsFor(r, job.get(r.id) ?? null, ev.get(r.id) ?? [], hist), now));
  return out;
}

