/**
 * PURE + client-safe: the configurator's itemised monthly price, built from the
 * server's exact price table (OrderVariant.allPrices, lib/dedicated/order.ts —
 * the same function the charge uses), so the lines ALWAYS add up to the real
 * monthly price to the cent:
 *
 *   base build (default options)          P(m0, d0, b0)
 *   + memory upgrade                      P(m,  d0, b0) - P(m0, d0, b0)
 *   + storage upgrade                     P(m,  d,  b0) - P(m,  d0, b0)
 *   + network upgrade                     P(m,  d,  b)  - P(m,  d,  b0)
 *   = monthly                             P(m,  d,  b)
 *
 * Each picker shows the same marginal figure for its options, so the "+$X/mo"
 * on a tile is exactly the line it adds to the summary. (Pricing rounds every
 * total up to $X.99, so adding stand-alone option prices would drift by a
 * dollar or two; telescoping differences of exact totals cannot.)
 *
 * No discounts exist for bare metal: no coupon, promo or term discount enters
 * here. Annual = 12 x monthly, paid up front.
 */
export type PriceTable = {
  allPrices: Record<string, number>;
  baseMonthlyCents: number;
  defaults: { memory: string; storage: string; bandwidth: string };
  setupCents: number;
};

export type Pick3 = { memoryId: string | null; storageId: string | null; bandwidthId: string | null };
export type PriceLine = { key: "base" | "memory" | "storage" | "bandwidth"; cents: number };
export type PriceSummary = {
  lines: PriceLine[];
  /** Exact monthly price of the chosen configuration (null when the table has no price for it). */
  monthlyCents: number | null;
  termMonths: number;
  /** monthly x term */
  termCents: number | null;
  setupCents: number;
  /** term + setup, before any tax (tax is added on the Review step from the account's billing country). */
  dueTodayCents: number | null;
};

const key = (m: string | null, d: string | null, b: string | null) => `${m ?? ""}|${d ?? ""}|${b ?? ""}`;
const nn = (s: string) => (s === "" ? null : s);

function price(t: PriceTable, m: string | null, d: string | null, b: string | null): number | null {
  const v = t.allPrices[key(m, d, b)];
  return typeof v === "number" ? v : null;
}

const diff = (a: number | null, b: number | null) => (a == null || b == null ? 0 : Math.max(0, a - b));

export function priceSummary(t: PriceTable, p: Pick3, termMonths: number): PriceSummary {
  const m0 = nn(t.defaults.memory), d0 = nn(t.defaults.storage), b0 = nn(t.defaults.bandwidth);
  const { memoryId: m, storageId: d, bandwidthId: b } = p;
  const base = price(t, m0, d0, b0) ?? t.baseMonthlyCents;
  const monthly = price(t, m, d, b);
  const lines: PriceLine[] = [
    { key: "base", cents: base },
    { key: "memory", cents: diff(price(t, m, d0, b0), price(t, m0, d0, b0) ?? base) },
    { key: "storage", cents: diff(price(t, m, d, b0), price(t, m, d0, b0)) },
    { key: "bandwidth", cents: diff(price(t, m, d, b), price(t, m, d, b0)) },
  ];
  // If an intermediate combo is missing from the table, fold the remainder into the
  // base line so the shown lines still sum to the exact total.
  if (monthly != null) {
    const sum = lines.reduce((n, l) => n + l.cents, 0);
    if (sum !== monthly) lines[0] = { key: "base", cents: lines[0].cents + (monthly - sum) };
  }
  const term = Math.max(1, Math.round(termMonths || 1));
  const termCents = monthly == null ? null : monthly * term;
  return { lines, monthlyCents: monthly, termMonths: term, termCents, setupCents: t.setupCents, dueTodayCents: termCents == null ? null : termCents + t.setupCents };
}

/** "+$X/mo" for one option tile: the line it would add given the other current choices. */
export function optionDelta(t: PriceTable, family: "memory" | "storage" | "bandwidth", optionId: string, p: Pick3): number {
  const m0 = nn(t.defaults.memory), d0 = nn(t.defaults.storage), b0 = nn(t.defaults.bandwidth);
  if (family === "memory") return diff(price(t, optionId, d0, b0), price(t, m0, d0, b0));
  if (family === "storage") return diff(price(t, p.memoryId, optionId, b0), price(t, p.memoryId, d0, b0));
  return diff(price(t, p.memoryId, p.storageId, optionId), price(t, p.memoryId, p.storageId, b0));
}

