import { test } from "node:test";
import assert from "node:assert/strict";
import { optionDelta, priceSummary, type PriceTable } from "../lib/dedicated/price-lines.ts";
import { DEFAULT_RULES, sellMonthlyCents } from "../lib/dedicated/pricing.ts";

/** The configurator's itemised summary always adds up to the exact charged monthly price. */

// A build with cost $107 and real upstream option costs, priced by the real rules ($X.99 rounding).
const COST = 10700;
const mem: Record<string, number> = { m32: 0, m64: 1150, m128: 3300 };
const disk: Record<string, number> = { d960: 0, d1920: 4400, d3x1920: 6700 };
const bw: Record<string, number> = { b1: 0, b2: 11000 };
const P = (m: string, d: string, b: string) => sellMonthlyCents(COST, DEFAULT_RULES, {}, mem[m] + disk[d] + bw[b]);
const allPrices: Record<string, number> = {};
for (const m of Object.keys(mem)) for (const d of Object.keys(disk)) for (const b of Object.keys(bw)) allPrices[`${m}|${d}|${b}`] = P(m, d, b);
const T: PriceTable = { allPrices, baseMonthlyCents: P("m32", "d960", "b1"), defaults: { memory: "m32", storage: "d960", bandwidth: "b1" }, setupCents: 4650 };

test("every combination: lines sum to the exact monthly price, never negative", () => {
  for (const m of Object.keys(mem)) for (const d of Object.keys(disk)) for (const b of Object.keys(bw)) {
    const s = priceSummary(T, { memoryId: m, storageId: d, bandwidthId: b }, 1);
    assert.equal(s.monthlyCents, P(m, d, b));
    assert.equal(s.lines.reduce((n, l) => n + l.cents, 0), s.monthlyCents, `${m}/${d}/${b}`);
    for (const l of s.lines) assert.ok(l.cents >= 0, `${l.key} negative`);
    // the tile figure equals the line it adds
    assert.equal(optionDelta(T, "memory", m, { memoryId: m, storageId: d, bandwidthId: b }), s.lines[1].cents);
    assert.equal(optionDelta(T, "storage", d, { memoryId: m, storageId: d, bandwidthId: b }), s.lines[2].cents);
    assert.equal(optionDelta(T, "bandwidth", b, { memoryId: m, storageId: d, bandwidthId: b }), s.lines[3].cents);
  }
});

test("defaults: only the base line, due today = month + setup", () => {
  const s = priceSummary(T, { memoryId: "m32", storageId: "d960", bandwidthId: "b1" }, 1);
  assert.deepEqual(s.lines.map((l) => l.cents), [T.baseMonthlyCents, 0, 0, 0]);
  assert.equal(s.dueTodayCents, T.baseMonthlyCents + 4650);
});

test("annual = 12 x monthly up front, no discount", () => {
  const s = priceSummary(T, { memoryId: "m64", storageId: "d1920", bandwidthId: "b2" }, 12);
  assert.equal(s.termCents, s.monthlyCents! * 12);
  assert.equal(s.dueTodayCents, s.monthlyCents! * 12 + 4650);
});

test("builds without option families (null ids) still price", () => {
  const t: PriceTable = { allPrices: { "||": 9999 }, baseMonthlyCents: 9999, defaults: { memory: "", storage: "", bandwidth: "" }, setupCents: 0 };
  const s = priceSummary(t, { memoryId: null, storageId: null, bandwidthId: null }, 1);
  assert.equal(s.monthlyCents, 9999);
  assert.deepEqual(s.lines.map((l) => l.cents), [9999, 0, 0, 0]);
  assert.equal(s.dueTodayCents, 9999);
});

test("a configuration missing from the table has no price (Continue stays disabled)", () => {
  const s = priceSummary(T, { memoryId: "nope", storageId: "d960", bandwidthId: "b1" }, 1);
  assert.equal(s.monthlyCents, null);
  assert.equal(s.dueTodayCents, null);
});

