/**
 * What part of a customer's wallet may pay for a bare-metal server.
 *
 * Owner decision 2026-10-08: signup credit and promotional / bonus wallet credit
 * must NOT pay for a dedicated server (no discounts on bare metal, and free
 * credit spent on a machine we pay for upstream is a discount in effect). The
 * wallet is one balance, so the promotional part is estimated conservatively:
 * every promotional grant the account ever received is assumed to still be in
 * the balance (spent last), capped at the balance.
 *
 * INTERIM (bm-wizard branch): the bm-ops branch owns the definitive server-side
 * rule and the full list of credit sources. This module is the single place the
 * order actions (lib/actions-dedicated-order.ts) and the wizard read it from, so
 * swapping in bm-ops' helper is a one-file change. Contract:
 *   { balanceCents, spendableCents, promoCents }  with spendable + promo = balance.
 *
 * Sources counted here: signup credit (User.signupCreditCents), top-up promo-code
 * bonuses (CouponRedemption context "topup", CONSUMED), riddle awards
 * (RiddleWinner.awardCents) and referral welcome rewards (wallet transactions
 * "Referral bonus ...").
 */
import { db } from "../db";

export type DedicatedWallet = { balanceCents: number; spendableCents: number; promoCents: number };

/** PURE: split a balance into real funds and promotional credit (promo assumed unspent, capped at the balance). */
export function splitPromoCredit(balanceCents: number, promoGrantedCents: number): DedicatedWallet {
  const bal = Math.max(0, Math.round(balanceCents));
  const promo = Math.min(bal, Math.max(0, Math.round(promoGrantedCents)));
  return { balanceCents: bal, spendableCents: bal - promo, promoCents: promo };
}

/** The account's wallet as bare metal sees it. Fails closed: on a read error nothing counts as spendable. */
export async function dedicatedWallet(user: { id: string; balanceCents: number; signupCreditCents?: number | null }): Promise<DedicatedWallet> {
  try {
    const [coupons, riddle, referral] = await Promise.all([
      db.couponRedemption.aggregate({ where: { userId: user.id, context: "topup", state: "CONSUMED" }, _sum: { amountCents: true } }),
      db.riddleWinner.aggregate({ where: { userId: user.id }, _sum: { awardCents: true } }).catch(() => ({ _sum: { awardCents: 0 } })),
      db.walletTransaction.aggregate({ where: { userId: user.id, amountCents: { gt: 0 }, description: { startsWith: "Referral bonus" } }, _sum: { amountCents: true } }),
    ]);
    const promo = (user.signupCreditCents ?? 0) + (coupons._sum.amountCents ?? 0) + (riddle._sum.awardCents ?? 0) + (referral._sum.amountCents ?? 0);
    return splitPromoCredit(user.balanceCents, promo);
  } catch {
    return splitPromoCredit(user.balanceCents, user.balanceCents);
  }
}

