/*
 * Bare metal — the portal's dedicated-server surfaces (catalogue, configure,
 * review, pay, owned-server dashboard).
 *
 * Owner brief (2026-10-07): "the cards are hard to read, there's just a lot of
 * blue", then (2026-10-08, after picking from four rendered concepts) the
 * surfaces must match the rest of the portal instead of being their own
 * graphite island ("mixed and matched"). So: the portal's navy surfaces and
 * rims, neutral white-alpha fills inside them, and the brand accent
 * (violet -> blue) only where it carries meaning: selection, the primary
 * action, the price.
 *
 * Everything is scoped under `.bm` (rendered by the bare-metal components
 * only), so nothing here reaches the rest of the portal, marketing or admin.
 * Light theme: `:root[data-theme="light"] .bm`. Keyframes live at the top
 * level (a @keyframes nested in a style rule is silently dropped).
 */

.bm {
  --bm-page: transparent;
  --bm-card: #020c1f;
  --bm-card-2: rgba(255, 255, 255, 0.035);
  --bm-card-3: rgba(255, 255, 255, 0.07);
  --bm-line: #002a5e;
  --bm-line-2: rgba(72, 148, 255, 0.34);
  --bm-ink: #ffffff;
  --bm-ink-2: #c4d2f0;
  --bm-ink-3: #93aede;
  --bm-ink-4: #5f7cb4;
  --bm-accent: #8b6cff;
  --bm-accent-2: #4f7dff;
  --bm-accent-ink: #b9a8ff;
  --bm-accent-soft: rgba(139, 108, 255, 0.14);
  --bm-ok: #2fd39a;
  --bm-ok-soft: rgba(47, 211, 154, 0.12);
  --bm-warn: #f2b84b;
  --bm-warn-soft: rgba(242, 184, 75, 0.12);
  --bm-bad: #ff6b88;
  --bm-bad-soft: rgba(255, 107, 136, 0.12);
  --bm-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 18px 40px -24px rgba(0, 0, 0, 0.8);
  --bm-grad: linear-gradient(100deg, #8b6cff, #4f7dff);
  --bm-card-bg: linear-gradient(180deg, rgba(10, 22, 48, 0.55), rgba(2, 7, 20, 0.72));
  --bm-pop: #061a3a;
  color: var(--bm-ink);
}

:root[data-theme="light"] .bm {
  --bm-card: #ffffff;
  --bm-card-2: #f6f8fb;
  --bm-card-3: #eef1f6;
  --bm-line: #e3e7ee;
  --bm-line-2: #cfd6e1;
  --bm-ink: #0d1420;
  --bm-ink-2: #3f4a5c;
  --bm-ink-3: #5d6779;
  --bm-ink-4: #7a8394;
  --bm-accent: #6a43f0;
  --bm-accent-2: #2f5fe8;
  --bm-accent-ink: #5532d6;
  --bm-accent-soft: rgba(106, 67, 240, 0.09);
  --bm-ok: #0b8a5e;
  --bm-ok-soft: rgba(11, 138, 94, 0.09);
  --bm-warn: #9a6408;
  --bm-warn-soft: rgba(196, 128, 10, 0.11);
  --bm-bad: #c4223f;
  --bm-bad-soft: rgba(196, 34, 63, 0.08);
  --bm-shadow: 0 1px 2px rgba(13, 20, 32, 0.05), 0 12px 32px -22px rgba(13, 20, 32, 0.28);
  --bm-grad: linear-gradient(100deg, #6a43f0, #2f5fe8);
  --bm-card-bg: var(--bm-card);
  --bm-pop: #ffffff;
}

/* An always-dark region (the hero art) re-declares the dark ink. */
.bm .bm-island,
:root[data-theme="light"] .bm .bm-island {
  --bm-ink: #f3f5f9;
  --bm-ink-2: #c4cbd8;
  --bm-ink-3: #97a0b0;
  --bm-line: rgba(255, 255, 255, 0.1);
  --bm-accent-ink: #c3b5ff;
  color: var(--bm-ink);
}

/* ---------- surfaces ---------- */
.bm-card {
  background: var(--bm-card-bg, var(--bm-card));
  border: 1px solid var(--bm-line);
  border-radius: 18px;
  box-shadow: var(--bm-shadow);
}
.bm-sub {
  background: var(--bm-card-2);
  border: 1px solid var(--bm-line);
  border-radius: 13px;
}
.bm-rule { border-color: var(--bm-line); }
.bm-hero {
  position: relative; overflow: hidden; border-radius: 22px; isolation: isolate;
  background:
    radial-gradient(80% 120% at 85% 10%, rgba(123, 63, 239, 0.32), transparent 60%),
    radial-gradient(60% 90% at 70% 100%, rgba(59, 107, 232, 0.28), transparent 65%),
    linear-gradient(180deg, #080d1a 0%, #060a14 100%);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.bm-hero-grid {
  position: absolute; inset: 0; z-index: -1; opacity: 0.35;
  background-image: linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 32px 32px;
  -webkit-mask-image: radial-gradient(70% 90% at 70% 40%, #000, transparent 75%);
  mask-image: radial-gradient(70% 90% at 70% 40%, #000, transparent 75%);
}
