"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): the deploy wizard's hero (owner request
 * 2026-10-08: "a nice but simple hero section"). Same language as the catalogue
 * card: the build's size render on the aurora plate, its name, the spec
 * mini-cards (showing what is CHOSEN right now), the location with its flag, and
 * the Configure / Review / Pay step indicator. Always dark (`bm-island`), like
 * the server dashboard hero.
 */
import type { OrderBuild } from "@/lib/dedicated/order";
import { NX_FAMILY_INFO } from "@/lib/dedicated/nx-names";
import { buildArt } from "@/lib/dedicated/size-tier";
import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { BrandLogo } from "../BrandLogo";
import { Flag, Tags } from "../ui";

export const WIZARD_STEPS = ["Configure", "Review", "Pay"] as const;

const cpuShort = (cpu: string) => cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1");
const storageHead = (s: string) => s.replace(/\s*\((Soft|Hard) RAID\)/i, "").trim() || "—";
const raidOf = (s: string) => /\((Soft|Hard) RAID\)/i.exec(s)?.[0].replace(/[()]/g, "") ?? "";

/** Steps 1-3 (Configure, Review, Pay). Earlier steps are links back; later ones are not reachable yet. */
export function WizardSteps({ at, onJump }: { at: 1 | 2 | 3; onJump: (i: 1 | 2 | 3) => void }) {
  return (
    <ol className="bm-steps" aria-label="Deploy progress">
      {WIZARD_STEPS.map((s, i) => {
        const n = (i + 1) as 1 | 2 | 3;
        const done = n < at, on = n === at;
        return (
          <li key={s} className="flex flex-none items-center">
            <button type="button" className="bm-step" data-state={done ? "done" : on ? "on" : "todo"} disabled={n > at} aria-current={on ? "step" : undefined} onClick={() => onJump(n)}>
              <span className="bm-step-n" aria-hidden>{done ? <Icon name="check" size={9} tone="inherit" /> : n}</span>
              <span>{s}</span>
            </button>
            {i < WIZARD_STEPS.length - 1 && <span aria-hidden className="bm-step-bar" data-done={done ? "1" : "0"} />}
          </li>
        );
      })}
    </ol>
  );
}

export function WizardHero({ build, step, onJump, location, memory, storage, network }: {
  build: Pick<OrderBuild, "name" | "family" | "tags" | "cpu" | "cores" | "threads" | "baseGhz" | "boostGhz" | "gpu" | "ramGb" | "storage" | "bandwidth">;
  step: 1 | 2 | 3;
  onJump: (i: 1 | 2 | 3) => void;
  location: { label: string; country: string } | null;
  /** The CURRENT choices (labels), so the hero always describes the machine being bought. */
  memory: string | null;
  storage: string | null;
  network: string | null;
}) {
