"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): the bare-metal deploy wizard —
 * Configure (location, memory, storage, network, OS, term, name) -> Review (the
 * server's own quote) -> Pay (card, wallet, or both) -> the server page, which
 * shows the live order tracker.
 *
 * Money rules:
 *   - Every figure on Configure comes from the server-computed price table
 *     (OrderVariant.allPrices, the same function the charge uses) and the
 *     itemised lines add up to the exact total (lib/dedicated/price-lines.ts).
 *   - Review and Pay show the SERVER quote (lib/actions-dedicated-order.ts). If it
 *     differs from what Configure showed, the change is called out, never silent.
 *     The pay action re-checks the total the customer saw (`expectedTotalCents`)
 *     and refuses a different one.
 *   - No discounts and no refunds on bare metal (owner, 2026-10-08): no promo
 *     field, the rule is stated on Review and Pay, and the Deploy button only
 *     works once the customer ticks the acknowledgement (sent as
 *     `acceptedNoRefund: true`; the server refuses without it).
 *   - Only SPENDABLE wallet funds can pay (promotional credit can't); the card
 *     path is never blocked by the wallet.
 *
 * Choices survive going back to the catalogue and reopening the build
 * (`saved` / `onSave`, held by BareMetalFlow for the visit).
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { OrderBuild, OrderOption, OrderVariant } from "@/lib/dedicated/order";
import type { DedicatedQuoteResult } from "@/lib/actions-dedicated-order";
import { payDedicatedOrder, quoteDedicatedOrderAction } from "@/lib/actions-dedicated-order";
import { DEDICATED_OS, NO_REFUND_ACK, NO_REFUND_NOTICE, SETUP_ETA, type DedicatedTerm } from "@/lib/dedicated/order-core";
import { optionDelta, priceSummary, type PriceTable } from "@/lib/dedicated/price-lines";
import { Icon } from "@/components/nx/Icon";
import { NxCardFields } from "@/components/nx/NxCardFields";
import { Flag, StockDot, usd } from "../ui";
import { WizardHero, WizardSteps } from "./WizardHero";

/** Kept for older imports (the loading skeleton). */
export const FLOW_STEPS = ["Configure", "Review", "Pay"] as const;
export { WizardSteps as Stepper };

export type SavedConfig = {
  region: string;
  memoryId: string | null;
  storageId: string | null;
  bandwidthId: string | null;
  os: string;
  term: DedicatedTerm;
  label: string;
  orderKey: string;
};

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

const comboKey = (m: string | null, d: string | null) => `${m ?? ""}|${d ?? ""}`;
const defId = (list: OrderOption[]) => list.find((o) => o.isDefault)?.id ?? list[0]?.id ?? null;

function bestPartner(v: OrderVariant, fixed: "memory" | "storage", id: string | null): string | null {
  const other = fixed === "memory" ? v.storage : v.memory;
  if (!other.length) return null;
  const ok = other.filter((o) => v.inStock.includes(fixed === "memory" ? comboKey(id, o.id) : comboKey(o.id, id)));
  return (ok[0] ?? other.find((o) => o.isDefault) ?? other[0]).id;
}

const tableOf = (v: OrderVariant): PriceTable => ({ allPrices: v.allPrices, baseMonthlyCents: v.baseMonthlyCents, defaults: v.defaults, setupCents: v.setupCents });

type Method = "card" | "wallet" | "split";
type Step = 1 | 2 | 3;
const STEP_HASH: Record<Step, string | null> = { 1: null, 2: "review", 3: "pay" };

export function Configurator({ build, initialRegion, balanceCents, spendableCents, promoCents, email, onBack, saved, onSave }: {
  build: OrderBuild;
  initialRegion: string | null;
  balanceCents: number;
  /** Real funds that may pay for bare metal (promotional credit excluded; lib/dedicated/wallet-view.ts). */
  spendableCents: number;
  /** Promotional credit in the wallet that can't be used here. */
  promoCents: number;
  email: string;
  onBack: () => void;
  saved?: SavedConfig;
  onSave?: (c: SavedConfig) => void;
}) {
  const router = useRouter();
  const firstRegion =
    build.variants.find((v) => v.region === (saved?.region ?? initialRegion) && v.inStock.length) ??
    build.variants.find((v) => v.inStock.length) ?? build.variants[0];
  const [step, setStepState] = useState<Step>(1);
  const [region, setRegion] = useState(firstRegion.region);
  const variant = build.variants.find((v) => v.region === region) ?? firstRegion;
  const initialCombo = (v: OrderVariant): { m: string | null; d: string | null } => {
    const m = defId(v.memory), d = defId(v.storage);
    if (v.inStock.includes(comboKey(m, d)) || !v.inStock.length) return { m, d };
    const [mm, dd] = v.inStock[0].split("|");
    return { m: mm || null, d: dd || null };
  };
  const savedOk = !!saved && saved.region === firstRegion.region && firstRegion.inStock.includes(comboKey(saved.memoryId, saved.storageId));
  const [memoryId, setMemoryId] = useState<string | null>(savedOk ? saved!.memoryId : initialCombo(firstRegion).m);
  const [storageId, setStorageId] = useState<string | null>(savedOk ? saved!.storageId : initialCombo(firstRegion).d);
  const [bandwidthId, setBandwidthId] = useState<string | null>(savedOk && firstRegion.bandwidth.some((b) => b.id === saved!.bandwidthId) ? saved!.bandwidthId : defId(firstRegion.bandwidth));
  const [os, setOs] = useState(saved?.os && DEDICATED_OS.some((o) => o.id === saved.os) ? saved.os : DEDICATED_OS[0].id);
  const [term, setTerm] = useState<DedicatedTerm>(saved?.term ?? 1);
  const [label, setLabel] = useState(saved?.label ?? "");
  const orderKey = useRef<string>(saved?.orderKey ?? "");
  if (!orderKey.current) orderKey.current = newKey();
  const [ack, setAck] = useState(false);
  const ackRef = useRef<HTMLLabelElement>(null);

  // Keep the choices for this visit (back to the catalogue and reopening restores them).
  useEffect(() => {
    onSave?.({ region, memoryId, storageId, bandwidthId, os, term, label, orderKey: orderKey.current });
  }, [region, memoryId, storageId, bandwidthId, os, term, label, onSave]);

  // The step lives in the URL hash (replace, not push: browser Back still returns to the catalogue).
  const setStep = useCallback((n: Step) => {
    setStepState(n);
    try {
      const url = new URL(window.location.href);
      const h = new URLSearchParams(url.hash.replace(/^#/, ""));
      if (h.get("build") || url.searchParams.get("build")) {
        if (STEP_HASH[n]) h.set("step", STEP_HASH[n]!); else h.delete("step");
        if (!h.get("build")) h.set("build", url.searchParams.get("build")!);
        url.hash = h.toString();
        window.history.replaceState(window.history.state, "", url);
      }
    } catch { /* URL sync is a convenience */ }
    window.scrollTo({ top: 0 });
  }, []);
  // A refresh on #step=review|pay comes back to Review (Pay needs a fresh quote + the acknowledgement).
  useEffect(() => {
    const s = new URLSearchParams(window.location.hash.replace(/^#/, "")).get("step");
    if (s === "review" || s === "pay") setStepState(2);
  }, []);

  const chooseRegion = (code: string) => {
    const next = build.variants.find((v) => v.region === code);
    if (!next) return;
    const byLabel = (from: OrderOption[], to: OrderOption[], id: string | null): string | null => to.find((o) => o.label === from.find((x) => x.id === id)?.label)?.id ?? defId(to);
    let m: string | null = byLabel(variant.memory, next.memory, memoryId);
    let d: string | null = byLabel(variant.storage, next.storage, storageId);
    if (next.inStock.length && !next.inStock.includes(comboKey(m, d))) {
      const alt = bestPartner(next, "memory", m);
      if (next.inStock.includes(comboKey(m, alt))) d = alt;
      else ({ m, d } = initialCombo(next));
    }
    setRegion(code);
    setMemoryId(m);
    setStorageId(d);
    setBandwidthId(byLabel(variant.bandwidth, next.bandwidth, bandwidthId));
  };
  const [autoNote, setAutoNote] = useState<string | null>(null);
  const chooseMemory = (id: string) => {
    setMemoryId(id);
    setAutoNote(null);
    if (!variant.inStock.includes(comboKey(id, storageId))) {
      const p = bestPartner(variant, "memory", id);
      setStorageId(p);
      setAutoNote(`Storage switched to ${variant.storage.find((o) => o.id === p)?.label ?? "an in-stock option"}: the one you had isn't in stock with this memory.`);
    }
  };
  const chooseStorage = (id: string) => {
    setStorageId(id);
    setAutoNote(null);
    if (!variant.inStock.includes(comboKey(memoryId, id))) {
      const p = bestPartner(variant, "storage", id);
      setMemoryId(p);
      setAutoNote(`Memory switched to ${variant.memory.find((o) => o.id === p)?.label ?? "an in-stock option"}: the one you had isn't in stock with this storage.`);
    }
  };

  const table = tableOf(variant);
  const picks = { memoryId, storageId, bandwidthId };
  const sum = priceSummary(table, picks, term);
  const inStock = variant.inStock.includes(comboKey(memoryId, storageId));
  const memOk = (id: string) => variant.inStock.some((k) => k.startsWith(`${id}|`));
  const diskOk = (id: string) => variant.inStock.some((k) => k.endsWith(`|${id}`));
  const mem = variant.memory.find((o) => o.id === memoryId);
  const disk = variant.storage.find((o) => o.id === storageId);
  const bw = variant.bandwidth.find((o) => o.id === bandwidthId);
  const osObj = DEDICATED_OS.find((o) => o.id === os)!;
  const canContinue = inStock && sum.monthlyCents != null && (variant.prices[`${memoryId ?? ""}|${storageId ?? ""}|${bandwidthId ?? ""}`] ?? null) != null;

  const intent = useMemo(() => ({
    itemId: variant.itemId, region, os, termMonths: term, memoryId, storageId, bandwidthId, label: label.trim(), orderKey: orderKey.current,
  }), [variant.itemId, region, os, term, memoryId, storageId, bandwidthId, label]);

  /* ---------- review: the server's quote ---------- */
  const [quote, setQuote] = useState<DedicatedQuoteResult | null>(null);
  const [quoting, startQuote] = useTransition();
  const shownNet = useRef<number | null>(null);
  const runQuote = useCallback(() => startQuote(async () => setQuote(await quoteDedicatedOrderAction(intent, true))), [intent]);
  useEffect(() => { if (step === 2) runQuote(); }, [step, runQuote]);
  const q = quote && quote.ok ? quote : null;
  const total = q?.quote.money.totalCents ?? 0;
  const priceMoved = q && shownNet.current != null && q.quote.money.netCents !== shownNet.current ? { was: shownNet.current, now: q.quote.money.netCents } : null;

  /* ---------- pay ---------- */
  const spend = q ? q.spendableCents : spendableCents;
  const promo = q ? q.promoCents : promoCents;
  const canWallet = spend >= total && total > 0;
  const canSplit = spend > 0 && spend < total;
  const [method, setMethod] = useState<Method>("card");
  const toReview = () => { shownNet.current = sum.dueTodayCents; setStep(2); };
  // Chosen synchronously when entering Pay (an effect would render one frame as "card" first and
  // open a card session the customer never sees).
  const toPay = () => { if (!ack) { ackRef.current?.scrollIntoView({ block: "center", behavior: "smooth" }); ackRef.current?.querySelector("input")?.focus(); return; } setMethod(canWallet ? "wallet" : "card"); setStep(3); };
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number; walletApplied: number; method: Method } | null>(null);
  const [payError, setPayError] = useState<string | null>(null);
  const [paying, setPaying] = useState(false);
  const [done, setDone] = useState(false);
  const [preparing, startPrep] = useTransition();
  const inFlight = useRef(false);
  const cardConfirm = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const onConfirmReady = useCallback((fn: (() => Promise<void>) | null) => { cardConfirm.current = fn; setCanConfirm(!!fn); }, []);
  const onBusy = useCallback((b: boolean, err: string | null) => { setPaying(b); setPayError(err); if (!b) inFlight.current = false; }, []);
  const payload = useCallback((useWallet: boolean) => ({ ...intent, acceptedNoRefund: true, expectedTotalCents: total }), [intent, total]);

  // Open the card session for the chosen method (card or wallet+card) once per method.
  useEffect(() => {
    if (step !== 3 || method === "wallet" || !q || !ack) return;
    if (checkout && checkout.method === method) return;
    setCheckout(null);
    setCanConfirm(false);
    setPayError(null);
    startPrep(async () => {
      const r = await payDedicatedOrder(payload(method === "split"), method === "split");
      if (!r.ok) setPayError(r.error);
      else if ("checkout" in r) setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied, method });
      else { setDone(true); router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`); }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step, method, q, ack]);

  const deploy = () => {
    if (inFlight.current || done || !ack) return;
    setPayError(null);
    inFlight.current = true;
    if (method === "wallet") {
      setPaying(true);
      startPrep(async () => {
        const r = await payDedicatedOrder(payload(true), true);
        if (!r.ok) { setPayError(r.error); setPaying(false); inFlight.current = false; return; }
        if ("serverId" in r) { setDone(true); router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`); }
        else { setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied, method: "split" }); setMethod("split"); setPaying(false); inFlight.current = false; }
      });
      return;
    }
    if (!cardConfirm.current) { inFlight.current = false; return; }
    void cardConfirm.current();
  };

  const cardDue = method === "card" ? total : method === "split" ? (checkout?.method === "split" ? checkout.cardCents : Math.max(0, total - spend)) : 0;
  const walletDue = method === "wallet" ? total : method === "split" ? (checkout?.method === "split" ? checkout.walletApplied : Math.min(spend, total)) : 0;
  const deployReady = ack && !paying && !preparing && !done && (method === "wallet" ? canWallet : canConfirm && checkout?.method === method);

  const location = { label: variant.label, country: variant.country };
  const lineLabel: Record<string, string> = {
    base: `${build.name}${mem && !mem.isDefault ? "" : ""}`,
    memory: `Memory: ${mem?.label ?? ""}`,
    storage: `Storage: ${disk?.label ?? ""}`,
    bandwidth: `Network: ${bw?.label ?? ""}`,
  };
  const configLines: [string, string][] = sum.lines.filter((l) => l.key === "base" || l.cents > 0).map((l) => [l.key === "base" ? `${lineLabel.base} (base build)` : lineLabel[l.key], l.key === "base" ? `${usd(l.cents)}/mo` : `+${usd(l.cents)}/mo`]);

  return (
    <div className="bm-enter flex flex-col gap-4 pb-24 xl:pb-0">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <button type="button" onClick={step === 1 ? onBack : () => setStep((step - 1) as Step)} className="bm-btn-ghost">
          <span aria-hidden>←</span>{step === 1 ? "All builds" : step === 2 ? "Back to configure" : "Back to review"}
        </button>
        <span className="hidden text-[12px] bm-ink-3 sm:inline">Your choices are kept if you go back.</span>
      </div>

      <WizardHero build={build} step={step} location={location}
                  memory={mem?.label ?? null} storage={disk?.label ?? null} network={bw?.label ?? null}
                  onJump={(i) => (i === 1 ? setStep(1) : i === 2 ? (canContinue ? toReview() : undefined) : toPay())} />

      {step === 1 && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <div className="flex min-w-0 flex-col gap-4">
            <Section n={1} title="Location" help="Where your server runs. Only locations with this build in stock can be ordered.">
              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3" role="radiogroup" aria-label="Location">
                {build.variants.map((v) => {
                  const ok = v.inStock.length > 0;
                  const from = ok ? Math.min(...Object.values(v.prices)) : null;
                  return (
                    <button key={v.region} type="button" role="radio" aria-checked={v.region === region} className="bm-pick flex items-center gap-3 p-3" disabled={!ok} onClick={() => ok && chooseRegion(v.region)}>
                      <Flag country={v.country} width={24} />
                      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                        <span className="trunc text-[13.5px] font-bold bm-ink">{v.label}</span>
                        <span className="flex items-center gap-1.5 text-[11.5px] bm-ink-3"><StockDot on={ok} />{ok ? `from ${usd(from!)}/mo` : "Sold out here"}</span>
                      </span>
                      {v.region === region && <Icon name="checkcircle" size={15} tone="inherit" className="bm-accent flex-none" />}
                    </button>
                  );
                })}
              </div>
            </Section>
            {variant.memory.length > 0 && (
              <Section n={2} title="Memory" help="Dedicated RAM, fitted before handover. Prices are the change to your monthly price.">
                <Options name="Memory" list={variant.memory} on={memoryId} ok={memOk} pick={chooseMemory} delta={(id) => optionDelta(table, "memory", id, picks)} />
              </Section>
            )}
            {variant.storage.length > 0 && (
              <Section n={3} title="Storage" help="Your own disks, in software RAID unless the option says otherwise.">
                <Options name="Storage" list={variant.storage} on={storageId} ok={diskOk} pick={chooseStorage} delta={(id) => optionDelta(table, "storage", id, picks)} />
              </Section>
            )}
            {autoNote && <p className="bm-note" role="status"><Icon name="swap" size={13} tone="inherit" />{autoNote}</p>}
            {variant.bandwidth.length > 1 && (
              <Section n={4} title="Network" help="Unmetered public bandwidth. DDoS protection is always included.">
                <Options name="Network" list={variant.bandwidth} on={bandwidthId} ok={() => true} pick={setBandwidthId} delta={(id) => optionDelta(table, "bandwidth", id, picks)} />
              </Section>
            )}
            <Section n={variant.bandwidth.length > 1 ? 5 : 4} title="Operating system" help="Installed and hardened by our team with your SSH key. You get full root. Included in the price.">
              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3" role="radiogroup" aria-label="Operating system">
                {DEDICATED_OS.map((o) => (
                  <button key={o.id} type="button" role="radio" aria-checked={o.id === os} className="bm-pick flex items-center gap-3 p-3" onClick={() => setOs(o.id)}>
                    <Icon name="terminal" size={14} tone="inherit" className="bm-ink-3 flex-none" />
                    <span className="flex min-w-0 flex-col gap-0.5">
                      <span className="trunc text-[13.5px] font-bold bm-ink">{o.label}</span>
                      <span className="text-[11.5px] leading-snug bm-ink-3">{o.note}</span>
                    </span>
                  </button>
                ))}
              </div>
            </Section>
            <Section n={variant.bandwidth.length > 1 ? 6 : 5} title="Billing term" help="Same monthly price either way. Annual is 12 months paid up front.">
              <div className="grid gap-2.5 sm:grid-cols-2" role="radiogroup" aria-label="Billing term">
                {([1, 12] as const).map((t) => (
                  <button key={t} type="button" role="radio" aria-checked={term === t} className="bm-pick flex flex-col gap-1 p-3.5" onClick={() => setTerm(t)}>
                    <span className="text-[14px] font-extrabold bm-ink">{t === 1 ? "Monthly" : "Annual"}</span>
                    <span className="bm-num text-[13px] font-bold bm-ink-2">{sum.monthlyCents != null ? (t === 1 ? `${usd(sum.monthlyCents)}/mo` : `${usd(sum.monthlyCents * 12)}/yr`) : "—"}</span>
                    <span className="text-[11.5px] bm-ink-3">{t === 1 ? "Billed every month." : `12 × ${sum.monthlyCents != null ? usd(sum.monthlyCents) : "—"}, billed once a year.`}</span>
                  </button>
                ))}
              </div>
            </Section>
            <Section n={variant.bandwidth.length > 1 ? 7 : 6} title="Name it" help="Optional. Shown on your dashboard and invoices.">
              <label className="flex max-w-[420px] flex-col gap-1.5">
                <span className="sr-only">Server name</span>
                <input value={label} onChange={(e) => setLabel(e.target.value.replace(/[<>]/g, "").slice(0, 40))} placeholder={`e.g. ${build.name} · ${variant.label}`} className="bm-field" maxLength={40} />
                <span className="text-[11px] bm-ink-4">{label.length}/40</span>
              </label>
            </Section>
          </div>
          <aside className="xl:sticky xl:top-4 xl:self-start">
            <section className="bm-card flex flex-col gap-4 p-5" aria-label="Price summary">
              <div className="flex items-center justify-between gap-2">
                <span className="text-[15px] font-extrabold bm-ink">Price summary</span>
                <span className="bm-chip pointer-events-none !py-1 text-[11px]">{term === 12 ? "Annual" : "Monthly"}</span>
              </div>
              {canContinue ? (
                <>
                  <Money rows={configLines} total={["Monthly price", `${usd(sum.monthlyCents!)}/mo`]} live />
                  <div className="bm-hr" />
                  <Money rows={[
                    [term === 12 ? `12 months × ${usd(sum.monthlyCents!)}` : "First month", usd(sum.termCents!)],
                    ["One-time setup fee", sum.setupCents > 0 ? usd(sum.setupCents) : "Free"],
                  ]} total={["Due today", usd(sum.dueTodayCents!)]} live big />
                  <ul className="flex flex-col gap-1.5 text-[11.5px] bm-ink-3">
                    <li className="flex gap-2"><Icon name="clock" size={11} tone="inherit" className="mt-0.5 flex-none" />{SETUP_ETA} of payment.</li>
                    <li className="flex gap-2"><Icon name="refresh" size={11} tone="inherit" className="mt-0.5 flex-none" />Renews at {term === 12 ? `${usd(sum.monthlyCents! * 12)}/yr` : `${usd(sum.monthlyCents!)}/mo`}. The setup fee is charged once.</li>
                    <li className="flex gap-2"><Icon name="tag" size={11} tone="inherit" className="mt-0.5 flex-none" />Tax, if any, is added on the next step from your billing country.</li>
                  </ul>
                </>
              ) : (
                <p className="rounded-[11px] px-3 py-2.5 text-[12.5px]" role="alert" style={{ background: "var(--bm-warn-soft)", color: "var(--bm-warn)" }}>
                  This combination isn&apos;t in stock in {variant.label}. Pick another memory or storage option, or another location.
                </p>
              )}
              <button type="button" disabled={!canContinue} onClick={toReview} className="bm-btn w-full">Review order <span aria-hidden>→</span></button>
            </section>
          </aside>
        </div>
      )}

      {step === 2 && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="bm-card flex min-w-0 flex-col gap-4 p-5">
            <div className="flex items-start justify-between gap-3">
              <div>
                <h2 className="text-[17px] font-extrabold bm-ink">Review your server</h2>
                <p className="text-[12px] bm-ink-3">Priced just now from live stock. Nothing is charged until you deploy.</p>
              </div>
              <button type="button" onClick={() => setStep(1)} className="bm-btn-ghost">Change</button>
            </div>
            {!quote || quoting ? (
              <div className="grid gap-3 sm:grid-cols-2" aria-busy="true" aria-label="Pricing your order">{Array.from({ length: 6 }, (_, i) => <div key={i} className="bm-skel h-[64px]" />)}</div>
            ) : !quote.ok ? (
              <ErrorBox msg={quote.error} onBack={() => setStep(1)} onRetry={runQuote} />
            ) : (
              <>
                {priceMoved && (
                  <p className="bm-note bm-note-warn" role="alert">
                    <Icon name="warncircle" size={13} tone="inherit" />
                    The price changed while you were choosing: due today is now {usd(priceMoved.now)} before tax (was {usd(priceMoved.was)}). Stock or pricing moved; this is the price you&apos;ll pay.
                  </p>
                )}
                <dl className="grid gap-3 sm:grid-cols-2">
                  {[
                    ["Processor", quote.quote.spec.cpu, `${quote.quote.spec.cores} cores · ${quote.quote.spec.threads} threads`, "cpu"],
                    ["Memory", `${quote.quote.spec.ramGb} GB`, mem?.label ?? "Dedicated to you", "ram"],
                    ["Storage", quote.quote.spec.storage, "Your own disks", "database"],
                    ["Network", quote.quote.spec.bandwidth || "—", "DDoS protection included", "pingwave"],
                    ["Location", quote.quote.regionLabel, "Your server's data center", "pin"],
                    ["Operating system", quote.quote.osLabel, "Full root access, your SSH key", "terminal"],
                    ...(quote.quote.spec.gpu ? [["GPU", quote.quote.spec.gpu, "Dedicated to you", "bmgpu"]] : []),
                    ["Billing", quote.quote.termLabel, `Renews at ${quote.quote.renewal}`, "calendar"],
                  ].map(([k, v, sub, icon]) => (
                    <div key={k} className="bm-spec">
                      <span className="bm-spec-ico">{k === "Location" ? <Flag country={variant.country} width={18} /> : <Icon name={icon} size={15} tone="inherit" />}</span>
                      <span className="flex min-w-0 flex-col">
                        <dt className="bm-label">{k}</dt>
                        <dd className="text-[13px] font-bold leading-snug bm-ink">{v}</dd>
                        {sub && <dd className="text-[11px] bm-ink-3">{sub}</dd>}
                      </span>
                    </div>
                  ))}
                </dl>
                {label.trim() && <p className="text-[12px] bm-ink-3">Named <b className="bm-ink-2">{label.trim()}</b> on your dashboard and invoices.</p>}
                <WhatNext />
              </>
            )}
          </section>
          <aside className="xl:sticky xl:top-4 xl:self-start">
            <section className="bm-card flex flex-col gap-3.5 p-5" aria-label="Order summary">
              <span className="text-[15px] font-extrabold bm-ink">Order summary</span>
              {q ? (
                <>
                  <QuoteMoney q={q} lines={q.quote.money.monthlyCents === sum.monthlyCents ? configLines : null} />
                  <NoRefund ack={ack} setAck={setAck} ackRef={ackRef} />
                  <button type="button" onClick={toPay} aria-disabled={!ack} className="btn-deploy bm-deploy w-full" data-off={!ack ? "1" : undefined}>
                    Continue to payment <span className="dep-arrow" aria-hidden>→</span>
                  </button>
                  {!ack && <span className="text-center text-[11px] bm-ink-3">Tick the box above to continue.</span>}
                </>
              ) : quote && !quote.ok ? (
                <p className="text-[12.5px] bm-ink-3">We&apos;ll show the total once the order is priced.</p>
              ) : (
                <div className="flex flex-col gap-2" aria-hidden><div className="bm-skel h-4" /><div className="bm-skel h-4 w-2/3" /><div className="bm-skel h-10" /></div>
              )}
            </section>
          </aside>
        </div>
      )}

      {step === 3 && q && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="bm-card flex min-w-0 flex-col gap-4 p-5">
            <div className="flex items-center gap-2.5">
              <Icon name="lock" size={16} tone="inherit" className="bm-accent" />
              <div>
                <h2 className="text-[17px] font-extrabold bm-ink">How would you like to pay?</h2>
                <p className="text-[12px] bm-ink-3">Card details are handled by our payment processor and never touch our servers.</p>
              </div>
            </div>
            <div className="grid gap-2.5 sm:grid-cols-3" role="radiogroup" aria-label="Payment method">
              <MethodTile on={method === "card"} onPick={() => setMethod("card")} icon="card" title="Card" sub={`${usd(total)} by credit or debit card`} />
              <MethodTile on={method === "wallet"} onPick={() => setMethod("wallet")} disabled={!canWallet} icon="gift" title="Wallet balance"
                          sub={canWallet ? `${usd(total)} from your ${usd(spend)} balance` : spend > 0 ? `${usd(spend)} available, not enough on its own` : "No balance available for this"} />
              {canSplit && <MethodTile on={method === "split"} onPick={() => setMethod("split")} icon="swap" title="Balance + card" sub={`${usd(Math.min(spend, total))} from balance, the rest by card`} />}
            </div>
            {promo > 0 && (
              <p className="bm-note" role="note">
                <Icon name="gift" size={13} tone="inherit" />
                <span>Promotional credit can&apos;t be used for dedicated servers. {usd(promo)} of your {usd(q.balanceCents)} balance is promotional, so {usd(spend)} is available here.</span>
              </p>
            )}
            <div className="bm-sub min-h-[200px] p-4">
              {method === "wallet" ? (
                <div className="flex h-full flex-col items-center justify-center gap-1.5 py-8 text-center">
                  <Icon name="checkcircle" size={24} tone="inherit" className="bm-ok" />
                  <span className="text-[14px] font-bold bm-ink">Covered by your balance</span>
                  <span className="text-[12px] bm-ink-3">{usd(total)} will be taken from your balance when you press Deploy server.</span>
                </div>
              ) : checkout && checkout.method === method ? (
                <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={onConfirmReady} onBusy={onBusy} />
              ) : payError ? null : !ack ? (
                <div className="flex flex-col items-center gap-2 py-10 text-center">
                  <Icon name="lock" size={22} tone="inherit" className="bm-ink-3" />
                  <span className="text-[13.5px] font-bold bm-ink">Tick the non-refundable confirmation to load the card form.</span>
                </div>
              ) : (
                <div className="flex flex-col items-center gap-2 py-10 text-center" aria-busy="true">
                  <Icon name="lock" size={22} tone="inherit" className="bm-ink-3" />
                  <span className="text-[13.5px] font-bold bm-ink">Preparing your secure card form…</span>
                </div>
              )}
              {payError && <ErrorBox msg={payError} onBack={() => setStep(2)} backLabel="Back to review" />}
            </div>
          </section>
          <aside className="xl:sticky xl:top-4 xl:self-start">
            <section className="bm-card flex flex-col gap-3.5 p-5" aria-label="Payment summary">
              <span className="text-[15px] font-extrabold bm-ink">Payment summary</span>
              <p className="flex items-center gap-2 text-[12.5px] bm-ink-2"><Flag country={variant.country} width={16} /><span><b className="bm-ink">{q.quote.spec.name}</b> · {q.quote.spec.ramGb} GB · {q.quote.regionLabel}</span></p>
              <QuoteMoney q={q} lines={null} />
              {(walletDue > 0 || method !== "card") && (
                <Money rows={[
                  ...(walletDue > 0 ? [["From wallet", `−${usd(walletDue)}`] as [string, string]] : []),
                ]} total={[method === "wallet" ? "From your balance" : "Charged to your card", usd(method === "wallet" ? total : cardDue)]} />
              )}
              <NoRefund ack={ack} setAck={setAck} ackRef={ackRef} />
              <DeployButton ready={deployReady} busy={paying || (preparing && method === "wallet")} done={done} onClick={deploy}
                            amount={usd(method === "wallet" ? total : cardDue)} hint={!ack ? "Tick the box above to deploy." : method !== "wallet" && !canConfirm ? "Fill in your card details." : null} />
              <span className="text-center text-[10.5px] bm-ink-4">Signed in as {email}</span>
            </section>
          </aside>
        </div>
      )}

      {/* Phones: the total and the next action stay in reach. */}
      <MobileDock step={step} dueToday={step === 1 ? sum.dueTodayCents : q ? (step === 3 ? (method === "wallet" ? total : cardDue) : total) : null}
                  taxNote={step === 1} canGo={step === 1 ? canContinue : step === 2 ? !!q : deployReady}
                  label={step === 1 ? "Review order" : step === 2 ? "Continue to payment" : done ? "Deployed" : paying ? "Deploying…" : "Deploy server"}
                  deployStyle={step > 1} onGo={step === 1 ? toReview : step === 2 ? toPay : deploy} />
    </div>
  );
}

/* ---------------- pieces ---------------- */

function Section({ n, title, help, children }: { n: number; title: string; help: string; children: React.ReactNode }) {
  return (
    <section className="bm-card p-5" aria-labelledby={`bm-sec-${n}`}>
      <div className="mb-3.5 flex items-start gap-3">
        <span className="grid h-6 w-6 flex-none place-items-center rounded-full text-[11px] font-extrabold" style={{ background: "var(--bm-card-3)", color: "var(--bm-ink-2)" }}>{n}</span>
        <span className="flex flex-col">
          <h2 id={`bm-sec-${n}`} className="text-[15px] font-extrabold bm-ink">{title}</h2>
          <span className="text-[12px] bm-ink-3">{help}</span>
        </span>
      </div>
      {children}
    </section>
  );
}

function Options({ name, list, on, ok, pick, delta }: { name: string; list: OrderOption[]; on: string | null; ok: (id: string) => boolean; pick: (id: string) => void; delta: (id: string) => number }) {
  return (
    <div className="grid gap-2.5 sm:grid-cols-2" role="radiogroup" aria-label={name}>
      {list.map((o) => {
        const avail = ok(o.id);
        const d = delta(o.id);
        return (
          <button key={o.id} type="button" role="radio" aria-checked={o.id === on} className="bm-pick flex items-center gap-3 p-3" disabled={!avail} onClick={() => avail && pick(o.id)}>
            <span className="grid h-[17px] w-[17px] flex-none place-items-center rounded-full" style={{ border: `1.5px solid ${o.id === on ? "var(--bm-accent)" : "var(--bm-line-2)"}` }} aria-hidden>
              {o.id === on && <span className="h-[8px] w-[8px] rounded-full" style={{ background: "var(--bm-accent)" }} />}
            </span>
            <span className="flex min-w-0 flex-1 flex-col gap-0.5">
              <span className="text-[13px] font-bold leading-snug bm-ink">{o.label}</span>
              {!avail && <span className="text-[11px] bm-ink-3">Not in stock in this location</span>}
            </span>
            <span className="flex-none text-right text-[12.5px] font-bold bm-num bm-ink-2">{o.isDefault ? "Included" : d === 0 ? "No extra cost" : <>+{usd(d)}<span className="font-medium bm-ink-3">/mo</span></>}</span>
          </button>
        );
      })}
    </div>
  );
}

function MethodTile({ on, onPick, disabled, icon, title, sub }: { on: boolean; onPick: () => void; disabled?: boolean; icon: string; title: string; sub: string }) {
  return (
    <button type="button" role="radio" aria-checked={on} disabled={disabled} onClick={onPick} className="bm-pick flex items-start gap-3 p-3.5">
      <span className="grid h-9 w-9 flex-none place-items-center rounded-[10px]" style={{ background: on ? "var(--bm-grad)" : "var(--bm-card-3)", color: on ? "#fff" : "var(--bm-ink-2)" }}>
        <Icon name={icon} size={15} tone="inherit" />
      </span>
      <span className="flex min-w-0 flex-col gap-0.5 text-left">
        <span className="text-[13.5px] font-extrabold bm-ink">{title}</span>
        <span className="text-[11.5px] leading-snug bm-ink-3">{sub}</span>
      </span>
    </button>
  );
}

function Money({ rows, total, live, big }: { rows: [string, string][]; total: [string, string]; live?: boolean; big?: boolean }) {
  return (
    <dl className="flex flex-col gap-1.5 text-[13px]" aria-live={live ? "polite" : undefined}>
      {rows.map(([k, v]) => <div key={k} className="flex items-baseline justify-between gap-3"><dt className="min-w-0 bm-ink-3">{k}</dt><dd className="flex-none bm-num font-semibold bm-ink-2">{v}</dd></div>)}
      <div className="mt-1 flex items-baseline justify-between gap-3 border-t pt-2.5 bm-rule"><dt className="font-bold bm-ink">{total[0]}</dt><dd className={"bm-price " + (big ? "text-[24px]" : "text-[17px]")}>{total[1]}</dd></div>
    </dl>
  );
}

/** The server quote, itemised: (optional upgrade lines) monthly, term, setup, tax, total today, renewal. */
function QuoteMoney({ q, lines }: { q: Extract<DedicatedQuoteResult, { ok: true }>; lines: [string, string][] | null }) {
  const m = q.quote.money;
  return (
    <>
      {lines && lines.length > 1 && <Money rows={lines} total={["Monthly price", `${usd(m.monthlyCents)}/mo`]} />}
      <Money rows={[
        [m.termMonths === 12 ? `12 months × ${usd(m.monthlyCents)}` : "First month", usd(m.termCents)],
        ["One-time setup fee", m.setupCents ? usd(m.setupCents) : "Free"],
        ...(m.taxCents ? [[`Tax (${m.taxRatePercent}%${m.taxCountry ? ` ${m.taxCountry}` : ""})`, usd(m.taxCents)] as [string, string]] : []),
      ]} total={["Due today", usd(m.totalCents)]} big />
      <p className="text-[12px] bm-ink-3">Then renews at <b className="bm-ink-2">{q.quote.renewal}</b>{m.taxCents ? " plus tax" : ""}. The setup fee is charged once.</p>
    </>
  );
}

function NoRefund({ ack, setAck, ackRef }: { ack: boolean; setAck: (b: boolean) => void; ackRef: React.RefObject<HTMLLabelElement | null> }) {
  return (
    <div className="bm-norefund">
      <p className="flex gap-2 text-[12px] font-semibold bm-ink-2"><Icon name="shield" size={13} tone="inherit" className="mt-0.5 flex-none bm-warn" />{NO_REFUND_NOTICE}</p>
      <label ref={ackRef} className="bm-check !m-0 !items-start !px-0 !py-1">
        <input type="checkbox" className="sr-only" checked={ack} onChange={(e) => setAck(e.target.checked)} />
        <span className="bm-checkbox mt-px" aria-hidden>
          <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"><path d="M3.5 8.5l3 3 6-6.5" pathLength="1" /></svg>
        </span>
        <span className="text-[12px] leading-snug">{NO_REFUND_ACK}</span>
      </label>
    </div>
  );
}

/** The portal's classic deploy button (`btn-deploy`) with disabled / working / done states. */
function DeployButton({ ready, busy, done, onClick, amount, hint }: { ready: boolean; busy: boolean; done: boolean; onClick: () => void; amount: string; hint: string | null }) {
  return (
    <div className="flex flex-col gap-1.5">
      <button type="button" onClick={onClick} disabled={!ready || busy || done} aria-busy={busy || undefined}
              className="btn-deploy bm-deploy h-[48px] w-full text-[14px] font-bold">
        {done ? <><Icon name="check" size={13} tone="inherit" />Deployed, opening your server…</>
          : busy ? <><span className="bm-spin" aria-hidden />Deploying…</>
          : <>Deploy server <span className="dep-arrow" aria-hidden>→</span></>}
      </button>
      <span className="text-center text-[11.5px] bm-ink-3">{done ? "Payment confirmed." : hint ?? `You'll pay ${amount} now.`}</span>
    </div>
  );
}

function MobileDock({ step, dueToday, taxNote, canGo, label, onGo, deployStyle }: { step: Step; dueToday: number | null; taxNote: boolean; canGo: boolean; label: string; onGo: () => void; deployStyle: boolean }) {
  return (
    <div className="bm-dock xl:hidden" role="region" aria-label="Order total">
      <span className="flex min-w-0 flex-col leading-tight">
        <span className="text-[10.5px] font-bold uppercase tracking-[0.1em] bm-ink-3">{step === 3 ? "Pay now" : "Due today"}</span>
        <span className="bm-price text-[18px]">{dueToday != null ? usd(dueToday) : "—"}{taxNote && dueToday != null ? <span className="ml-1 text-[10.5px] font-semibold bm-ink-3">+ tax if any</span> : null}</span>
      </span>
      <button type="button" onClick={onGo} disabled={step === 1 && !canGo} aria-disabled={!canGo || undefined} className={(deployStyle ? "btn-deploy bm-deploy" : "bm-btn") + " h-[42px] flex-none px-4 text-[13px]"} data-off={!canGo ? "1" : undefined}>
        {label} <span className="dep-arrow" aria-hidden>→</span>
      </button>
    </div>
  );
}

function WhatNext() {
  const steps = [
    { t: "You deploy", d: "Payment confirms and your build is reserved for you." },
    { t: "We set it up", d: "Our data center team racks, tests and installs your system." },
    { t: SETUP_ETA, d: "Track each step live; the IP and login appear on its page." },
  ];
  return (
    <div className="bm-sub p-4">
      <span className="bm-label">After you deploy</span>
      <ol className="mt-3 grid gap-3 sm:grid-cols-3">
        {steps.map((s, i) => (
          <li key={s.t} className="flex items-start gap-2.5">
            <span className="grid h-6 w-6 flex-none place-items-center rounded-full text-[11px] font-extrabold text-[#fff]" style={{ background: "var(--bm-grad)" }}>{i + 1}</span>
            <span className="min-w-0"><span className="block text-[12.5px] font-bold bm-ink">{s.t}</span><span className="block text-[11.5px] bm-ink-3">{s.d}</span></span>
          </li>
        ))}
      </ol>
    </div>
  );
}

function ErrorBox({ msg, onBack, onRetry, backLabel = "Change the order" }: { msg: string; onBack: () => void; onRetry?: () => void; backLabel?: string }) {
  return (
    <div className="flex flex-col items-start gap-2 rounded-[12px] p-4" role="alert" style={{ background: "var(--bm-bad-soft)", border: "1px solid color-mix(in srgb, var(--bm-bad) 35%, transparent)" }}>
      <span className="flex items-center gap-2 text-[13px] font-bold bm-ink"><Icon name="warntriangle" size={14} tone="inherit" className="bm-bad" />We couldn&apos;t continue</span>
      <span className="text-[12.5px] bm-ink-2">{msg}</span>
      <div className="flex flex-wrap gap-2">
        <button type="button" onClick={onBack} className="bm-btn-ghost">{backLabel}</button>
        {onRetry && <button type="button" onClick={onRetry} className="bm-btn-ghost">Try again</button>}
        <Link href="/dashboard/support" className="bm-btn-ghost">Contact support</Link>
      </div>
    </div>
  );
}

