"use server";

/**
 * The bare-metal order tracker's poll (components/dedicated/OrderTracker.tsx,
 * every 25 s while an order is not yet online). Reads OUR cached records only
 * (lib/dedicated/tracking-load.ts), never the supplier. Gated like every
 * dedicated customer action and owner-checked: someone else's server id
 * returns null.
 */
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { dedicatedAccessFor } from "./dedicated/gate";
import { loadCustomerTracking, type CustomerTracking } from "./dedicated/tracking-load";

export async function getDedicatedTrackingAction(id: unknown): Promise<CustomerTracking | null> {
  try {
    if (typeof id !== "string" || !/^[a-z0-9]{8,40}$/i.test(id)) return null;
    const user = await requireUser();
    if (!(await dedicatedAccessFor(user)).allowed) return null;
    // A tab left open polls ~24 times per 10 minutes; leave room for a few tabs.
    if (!checkRateLimit(`dedicated-track:${user.id}`, { max: 120, windowMs: 10 * 60_000 }).ok) return null;
    return await loadCustomerTracking(id, user.id);
  } catch {
    return null;
  }
}

