          <BuildingVisual art={t.art} level={v.progress} tone={tone} />
          <div className="flex min-w-0 flex-col gap-2">
            <h2 className="text-[22px] font-extrabold leading-tight tracking-[-0.02em] sm:text-[26px]" style={{ color: "var(--bm-ink)" }} aria-live="polite">{v.headline}</h2>
            {v.sub && <p className="text-[13px] bm-ink-2">{v.sub}</p>}
            <div className="bm-trk-bar" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={v.progress} aria-label="Deployment progress">
              <span style={{ width: `${Math.max(4, v.progress)}%` }} />
            </div>
            <div className="flex flex-wrap items-center gap-x-4 gap-y-1.5 text-[12px] bm-ink-3">
              <span className="flex items-center gap-1.5"><Flag country={t.country} width={16} />{t.location}</span>
              {!v.delivered && !v.ended && <span className="flex items-center gap-1.5" suppressHydrationWarning><Icon name="clock" size={11} tone="inherit" />{v.elapsedText} since your order</span>}
              {v.eta?.dueAt && !v.delivered && <span suppressHydrationWarning title={v.eta.basisText}>Expected by {when(v.eta.dueAt)}</span>}
            </div>
            {v.eta && !v.delivered && <p className="text-[11.5px] bm-ink-3">{v.eta.basisText}</p>}
          </div>
          {v.delivered ? (
            <div className="flex flex-wrap items-center gap-2.5">
              <button type="button" className="btn-deploy h-[42px] px-5 text-[13.5px] font-bold" onClick={() => router.refresh()}>
                Open your server <span className="dep-arrow" aria-hidden>→</span>
              </button>
              <span className="text-[12px] bm-ink-3">IP address and login are waiting on the next screen.</span>
            </div>
          ) : (
            <div className="flex flex-wrap items-center gap-3 text-[11.5px] bm-ink-3">
              <span suppressHydrationWarning aria-live="polite">{stale ? "Couldn't refresh just now, showing the last update from " : "Last updated "}{clock(t.fetchedAt)}</span>
              {!preview && active && (
                <button type="button" className="bm-btn-ghost !h-[30px] !px-2.5 !text-[11.5px]" onClick={() => void refresh()} disabled={busy} style={{ background: "rgba(255,255,255,0.05)" }}>
                  <Icon name="refresh" size={11} tone="inherit" className={busy ? "motion-safe:animate-spin" : ""} />{busy ? "Checking…" : "Refresh"}
                </button>
              )}
              <span>We&apos;ll also notify you when it&apos;s online.</span>
            </div>
          )}
        </div>
        <ol className="bm-trk-steps" aria-label="Steps">
          {v.steps.map((s, i) => <StepRow key={s.key} s={s} last={i === v.steps.length - 1} />)}
        </ol>
      </div>
    </section>
  );
}

function StepRow({ s, last }: { s: TrackingStep; last: boolean }) {
  return (
    <li className="bm-trk-step" data-state={s.state} aria-current={s.state === "current" ? "step" : undefined}>
      <span className="bm-trk-dot" aria-hidden>
        {s.state === "done" ? <Icon name="check" size={11} tone="inherit" /> : s.state === "delayed" ? <Icon name="clock" size={11} tone="inherit" /> : s.state === "current" ? <span className="bm-trk-pulse" /> : null}
      </span>
      {!last && <span className="bm-trk-line" aria-hidden />}
      <span className="flex min-w-0 flex-col gap-0.5 pb-5">
        <span className="flex flex-wrap items-baseline justify-between gap-x-3">
          <span className="text-[13.5px] font-bold leading-snug" style={{ color: s.state === "todo" ? "var(--bm-ink-3)" : "var(--bm-ink)" }}>{s.label}</span>
          {s.at && s.state !== "todo" && <span className="flex-none text-[11px] bm-ink-3" suppressHydrationWarning>{s.state === "done" ? when(s.at) : `since ${when(s.at)}`}</span>}
        </span>
        <span className="text-[12px] bm-ink-3">
          <span className="sr-only">{s.state === "done" ? "Done. " : s.state === "current" ? "In progress. " : s.state === "delayed" ? "Delayed. " : "Not started. "}</span>
          {s.note}
        </span>
      </span>
    </li>
  );
}

/** The size render, lit up to `level` percent, with a slow light band over its silhouette. */
export function BuildingVisual({ art, level, tone, small = false }: { art: string; level: number; tone: string; small?: boolean }) {
  const lvl = tone === "ok" ? 100 : Math.max(16, Math.min(96, level));
  const mask = { WebkitMaskImage: `url(${art})`, maskImage: `url(${art})` } as React.CSSProperties;
  return (
    <div className={"bm-trk-vis" + (small ? " bm-trk-vis-sm" : "")} data-tone={tone} style={{ ["--lvl" as string]: `${lvl}%` }} aria-hidden>
      {/* eslint-disable @next/next/no-img-element -- the owner's size render, twice (dim + lit) */}
      <img src="/nx/plates/aurora-veil-card.webp" alt="" className="bm-trk-plate" decoding="async" />
      <span className="bm-trk-floor" />
      <img src={art} alt="" className="bm-trk-img bm-trk-dim" decoding="async" />
      <img src={art} alt="" className="bm-trk-img bm-trk-lit" decoding="async" />
      {/* eslint-enable @next/next/no-img-element */}
      {tone !== "ok" && tone !== "off" && <span className="bm-trk-scan" style={mask}><span className="bm-trk-band" /></span>}
    </div>
  );
}

