/* The always-dark island keeps dark FILLS too in the light theme (spec tiles, chips). */
:root[data-theme="light"] .bm .bm-island {
  --bm-card-2: rgba(255, 255, 255, 0.05);
  --bm-card-3: rgba(255, 255, 255, 0.09);
  --bm-line-2: rgba(72, 148, 255, 0.34);
  --bm-ink-4: #7d8aa3;
  --bm-accent: #8b6cff;
  --bm-accent-soft: rgba(139, 108, 255, 0.16);
  --bm-ok: #2fd39a;
  --bm-ok-soft: rgba(47, 211, 154, 0.14);
  --bm-warn: #f2b84b;
  --bm-warn-soft: rgba(242, 184, 75, 0.14);
  --bm-grad: linear-gradient(100deg, #8b6cff, #4f7dff);
}

/* ---------- wizard hero ---------- */
.bm-wh { display: grid; grid-template-columns: minmax(0, 1fr); gap: 4px 22px; padding: 18px; }
@media (min-width: 768px) { .bm-wh { grid-template-columns: 210px minmax(0, 1fr); padding: 20px 22px; } }
@media (min-width: 1280px) { .bm-wh { grid-template-columns: 250px minmax(0, 1fr); } }
.bm-wh-art { position: relative; display: none; overflow: hidden; border-radius: 15px; background: #050d20; min-height: 180px; border: 1px solid rgba(255, 255, 255, 0.06); }
@media (min-width: 768px) { .bm-wh-art { display: block; } }
.bm-wh-plate { position: absolute; left: 0; bottom: 0; width: 100%; height: 120%; object-fit: cover; object-position: bottom; opacity: 0.6; }
.bm-wh-render { position: absolute; left: 6%; right: 6%; bottom: 6px; width: 88%; height: 92%; object-fit: contain; object-position: bottom; filter: drop-shadow(0 18px 30px rgba(60, 40, 200, 0.4)); animation: bm-in 0.5s cubic-bezier(0.2, 0.7, 0.2, 1) both; }
.bm-wh-loc { display: inline-flex; align-items: center; gap: 7px; height: 26px; padding: 0 10px 0 7px; border-radius: 999px; font-size: 12px; font-weight: 700; color: var(--bm-ink); background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.1); backdrop-filter: blur(6px); }

/* ---------- step indicator ---------- */
.bm-steps { display: flex; align-items: center; gap: 0; margin: 0; padding: 3px; list-style: none; border-radius: 999px; background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.08); }
.bm-step { display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 11px 0 4px; border-radius: 999px; font-size: 12px; font-weight: 750; color: var(--bm-ink-3); transition: color .15s, background .15s; }
.bm-step:disabled { cursor: default; }
.bm-step:not(:disabled):hover { color: var(--bm-ink); }
.bm-step[data-state="on"] { color: var(--bm-ink); background: var(--bm-accent-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--bm-accent) 70%, transparent); }
.bm-step[data-state="done"] { color: var(--bm-ink-2); }
.bm-step-n { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 999px; font-size: 10.5px; background: var(--bm-card-3); color: var(--bm-ink-3); }
.bm-step[data-state="on"] .bm-step-n { background: var(--bm-grad); color: #fff; }
.bm-step[data-state="done"] .bm-step-n { background: var(--bm-ok-soft); color: var(--bm-ok); }
.bm-step-bar { width: 12px; height: 1px; background: rgba(255, 255, 255, 0.14); }
.bm-step-bar[data-done="1"] { background: color-mix(in srgb, var(--bm-ok) 60%, transparent); }
.bm-step:focus-visible { outline: 2px solid var(--bm-accent); outline-offset: 2px; }
@media (max-width: 420px) { .bm-step { padding-right: 8px; font-size: 11.5px; } .bm-step-bar { width: 6px; } }

/* ---------- notes, acknowledgement ---------- */
.bm-note { display: flex; align-items: flex-start; gap: 8px; padding: 10px 12px; border-radius: 11px; font-size: 12.5px; line-height: 1.45; color: var(--bm-ink-2); background: var(--bm-accent-soft); border: 1px solid color-mix(in srgb, var(--bm-accent) 28%, transparent); }
.bm-note > svg, .bm-note > .nx-ico { flex: none; margin-top: 2px; color: var(--bm-accent-ink); }
.bm-note-warn { color: var(--bm-ink); background: var(--bm-warn-soft); border-color: color-mix(in srgb, var(--bm-warn) 40%, transparent); }
.bm-note-warn > svg, .bm-note-warn > .nx-ico { color: var(--bm-warn); }
.bm-norefund { display: flex; flex-direction: column; gap: 8px; padding: 12px; border-radius: 12px; background: var(--bm-warn-soft); border: 1px solid color-mix(in srgb, var(--bm-warn) 32%, transparent); }
.bm-norefund .bm-check { color: var(--bm-ink); }
.bm-norefund .bm-check:hover { background: transparent; }

/* ---------- the classic deploy button inside the wizard ---------- */
.bm .bm-deploy { display: inline-flex; align-items: center; justify-content: center; gap: 8px; }
.bm .bm-deploy:disabled, .bm .bm-deploy[data-off="1"] { opacity: 0.45; cursor: not-allowed; transform: none; box-shadow: none; }
.bm .bm-deploy:disabled::before, .bm .bm-deploy[data-off="1"]::before { animation: none; }
.bm .bm-deploy:focus-visible { outline: 2px solid var(--bm-accent); outline-offset: 3px; }
.bm-spin { width: 14px; height: 14px; border-radius: 999px; border: 2px solid rgba(255, 255, 255, 0.35); border-top-color: #fff; animation: bm-spin 0.8s linear infinite; }
@keyframes bm-spin { to { transform: rotate(360deg); } }

/* ---------- phone dock ---------- */
.bm-dock { position: fixed; left: 12px; right: 12px; bottom: 12px; z-index: 40; display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 10px 10px 16px; border-radius: 16px; background: color-mix(in srgb, var(--bm-card) 92%, transparent); border: 1px solid var(--bm-line-2); box-shadow: 0 18px 40px -12px rgba(0, 0, 0, 0.6); backdrop-filter: blur(14px); }
@media (min-width: 640px) { .bm-dock { left: auto; width: 440px; } }
@media (min-width: 1280px) { .bm-dock { display: none; } }

/* ---------- order tracker ---------- */
.bm-trk[data-tone="ok"] { border-color: color-mix(in srgb, var(--bm-ok) 35%, transparent); }
.bm-trk[data-tone="warn"] { border-color: color-mix(in srgb, var(--bm-warn) 35%, transparent); }
.bm-trk-badge { align-self: flex-start; display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 999px; font-size: 11.5px; font-weight: 750; color: var(--bm-ok); background: var(--bm-ok-soft); border: 1px solid color-mix(in srgb, var(--bm-ok) 30%, transparent); }
.bm-trk-bar { position: relative; height: 6px; overflow: hidden; border-radius: 999px; background: rgba(255, 255, 255, 0.08); }
.bm-trk-bar > span { position: absolute; inset: 0 auto 0 0; border-radius: inherit; background: var(--bm-grad); box-shadow: 0 0 14px -2px color-mix(in srgb, var(--bm-accent) 70%, transparent); transition: width 1.2s cubic-bezier(0.2, 0.7, 0.2, 1); }
.bm-trk[data-tone="ok"] .bm-trk-bar > span { background: linear-gradient(100deg, #2fd39a, #4f7dff); }
.bm-trk[data-tone="warn"] .bm-trk-bar > span { background: linear-gradient(100deg, #f2b84b, #8b6cff); }

.bm-trk-vis { position: relative; height: 220px; overflow: hidden; border-radius: 16px; background: #050d20; border: 1px solid rgba(255, 255, 255, 0.06); }
.bm-trk-vis-sm { height: 120px; }
.bm-trk-plate { position: absolute; left: 0; bottom: 0; width: 100%; height: 125%; object-fit: cover; object-position: bottom; opacity: 0.5; }
.bm-trk-floor { position: absolute; left: 15%; right: 15%; bottom: -30px; height: 80px; border-radius: 50%; background: radial-gradient(closest-side, color-mix(in srgb, var(--bm-accent) 55%, transparent), transparent); opacity: 0.55; animation: bm-trk-breathe 5s ease-in-out infinite; }
.bm-trk-vis[data-tone="ok"] .bm-trk-floor { background: radial-gradient(closest-side, rgba(47, 211, 154, 0.55), transparent); animation: none; opacity: 0.7; }
.bm-trk-vis[data-tone="warn"] .bm-trk-floor { background: radial-gradient(closest-side, rgba(242, 184, 75, 0.45), transparent); }
.bm-trk-img, .bm-trk-scan { position: absolute; left: 8%; right: 8%; bottom: 8px; width: 84%; height: 90%; object-fit: contain; object-position: bottom; }
.bm-trk-dim { filter: brightness(0.38) saturate(0.4); }
.bm-trk-lit { clip-path: inset(calc(100% - var(--lvl, 20%)) 0 0 0); filter: drop-shadow(0 16px 28px rgba(60, 40, 200, 0.4)); transition: clip-path 1.4s cubic-bezier(0.2, 0.7, 0.2, 1); }
.bm-trk-scan { overflow: hidden; -webkit-mask-size: contain; mask-size: contain; -webkit-mask-repeat: no-repeat; mask-repeat: no-repeat; -webkit-mask-position: bottom center; mask-position: bottom center; clip-path: inset(calc(100% - var(--lvl, 20%)) 0 0 0); }
.bm-trk-band { position: absolute; left: 0; right: 0; height: 26%; top: 100%; background: linear-gradient(180deg, transparent, rgba(195, 181, 255, 0.55) 50%, transparent); animation: bm-trk-band 5.2s cubic-bezier(0.45, 0, 0.55, 1) infinite; }
.bm-trk-vis[data-tone="warn"] .bm-trk-band { animation-duration: 8s; background: linear-gradient(180deg, transparent, rgba(242, 184, 75, 0.4) 50%, transparent); }
@keyframes bm-trk-band { 0% { top: 100%; opacity: 0; } 12% { opacity: 1; } 80% { opacity: 1; } 100% { top: -26%; opacity: 0; } }
@keyframes bm-trk-breathe { 0%, 100% { opacity: 0.35; } 50% { opacity: 0.7; } }

.bm-trk-steps { margin: 0; padding: 0; list-style: none; align-self: start; }
.bm-trk-step { position: relative; display: grid; grid-template-columns: 26px minmax(0, 1fr); gap: 12px; }
.bm-trk-dot { position: relative; z-index: 1; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 999px; color: var(--bm-ink-3); background: #0a1328; border: 1.5px solid rgba(255, 255, 255, 0.14); }
.bm-trk-step[data-state="done"] .bm-trk-dot { color: #fff; background: var(--bm-grad); border-color: transparent; }
.bm-trk-step[data-state="current"] .bm-trk-dot { border-color: var(--bm-accent); box-shadow: 0 0 0 4px var(--bm-accent-soft); }
.bm-trk-step[data-state="delayed"] .bm-trk-dot { color: var(--bm-warn); border-color: var(--bm-warn); box-shadow: 0 0 0 4px var(--bm-warn-soft); }
.bm-trk-pulse { width: 8px; height: 8px; border-radius: 999px; background: var(--bm-accent); animation: bm-trk-pulse 1.8s ease-in-out infinite; }
@keyframes bm-trk-pulse { 0%, 100% { transform: scale(0.8); opacity: 0.7; } 50% { transform: scale(1.15); opacity: 1; } }
.bm-trk-line { position: absolute; left: 12.25px; top: 28px; bottom: 2px; width: 1.5px; background: rgba(255, 255, 255, 0.12); }
.bm-trk-step[data-state="done"] .bm-trk-line { background: color-mix(in srgb, var(--bm-accent) 65%, transparent); }

@media (prefers-reduced-motion: reduce) {
  .bm-wh-render, .bm-trk-floor, .bm-trk-band, .bm-trk-pulse, .bm-spin { animation: none !important; }
  .bm-trk-scan { display: none; }
  .bm-trk-lit, .bm-trk-bar > span { transition: none; }
}
