test("every customer action re-checks the gate (requests, credentials, checkout)", () => {
  const src = read("lib/actions-dedicated-customer.ts");
  assert.match(src, /async function ownedDedicated[\s\S]*?dedicatedAccessFor\(user\)/);
  for (const fn of ["requestDedicatedAction", "revealDedicatedCredentials"]) {
    const body = src.slice(src.indexOf(`export async function ${fn}`));
    assert.match(body.slice(0, 600), /ownedDedicated\(/, fn);
  }
});

test("checkout actions re-check the gate before anything else", () => {
  const src = read("lib/actions-dedicated-order.ts");
  assert.match(src, /async function gatedUser[\s\S]*?dedicatedAccessFor\(user\)[\s\S]*?throw new Error\(NOT_FOUND\)/);
  for (const fn of ["quoteDedicatedOrderAction", "payDedicatedOrder"]) {
    const body = src.slice(src.indexOf(`export async function ${fn}`));
    assert.match(body.slice(0, 900), /gatedUser\(\)/, fn);
  }
});

test("the portal nav entry is added only for viewers who pass the gate", () => {
  const layout = read("app/dashboard/layout.tsx");
  assert.match(layout, /if \(\(await dedicatedAccessFor\(user\)\.catch\(\(\) => \(\{ allowed: false \}\)\)\)\.allowed\) extraNav\.push\(DEDICATED_NAV_ITEM\)/);
  const nav = read("lib/nx/nav.ts");
  assert.doesNotMatch(nav, /dedicated/i, "the designed rail itself must not list dedicated servers");
});

test("not in the sitemap while off: static paths, live marketing routes, and the gated core entry", () => {
  const sections = read("lib/sitemap-sections.ts");
  const staticBlock = sections.slice(sections.indexOf("export const STATIC_PATHS"), sections.indexOf("];", sections.indexOf("export const STATIC_PATHS")));
  assert.ok(!staticBlock.includes('"/dedicated-servers"'));
  assert.ok(!staticBlock.includes("/dashboard/dedicated"));
  assert.match(sections, /dedicatedSitemapPaths\(await dedicatedPublicEnabled\(\)\)/);
  // The NXM site serves /dedicated-servers (live-routes.json) but it is EXCLUDED from the NXM sitemap list,
  // and so is every country page (DEDICATED_MARKETING_PATHS).
  assert.match(sections, /const EXCLUDE = new Set<string>\(\[[^\]]*"\/dedicated-servers"/);
  assert.match(sections, /const EXCLUDE = new Set<string>\(\[[^\]]*\.\.\.DEDICATED_MARKETING_PATHS/);
});

test("the NXM dedicated page 404s through the same gate and is noindex unless public", () => {
  const src = read("app/nxm/_data/dedicated-servers.ts");
  assert.match(src, /async function inStockCards[\s\S]*?await requireDedicatedAccess\(\)/);
  assert.match(src, /export async function load[\s\S]*?await inStockCards\(\)/);
  assert.match(src, /noindex: !on/);
});

test("bare metal country pages go through the same gated loader", () => {
  const src = read("app/nxm/dedicated-servers/[country]/page.tsx");
  assert.match(src, /import \{ load, meta \} from "..\/..\/_data\/dedicated-servers"/);
  assert.match(src, /await load\(\{ country: page\.slug \}\)/);
  assert.match(src, /noindex: m\.noindex/);
});

test("My Services and the dashboard home list bare metal only through the gated helper", () => {
  const rows = read("lib/dedicated/services-rows.ts");
  assert.match(rows, /if \(!\(await dedicatedAccessFor\(user\)\)\.allowed\) return \[\]/);
  assert.match(read("lib/nx/services.ts"), /await bareMetalRows\(user\)/);
  assert.match(read("app/dashboard/page.tsx"), /await bareMetalRows\(user\)/);
  // the empty Bare Metal tab is never shown (it would advertise the product)
  assert.match(read("components/customer/services/ServicesView.tsx"), /t\.key !== "dedicated" \|\| counts\.dedicated > 0/);
});

test("NXM nav: the Dedicated entries are injected only for viewers who pass the gate", async () => {
  const { withDedicatedNav } = await import("../app/nxm/_components/dedicated-nav.ts");
  const nav = read("app/nxm/_pages/vps/content.ts");
  const html = JSON.parse(nav.slice(nav.indexOf("BODY_HTML = ") + 12, nav.indexOf(";\nexport const BODY_ATTRS")));
  assert.equal(withDedicatedNav(html, false), html, "unchanged for everyone else");
  const on = withDedicatedNav(html, true);
  assert.equal((on.match(/href="\/nxm\/dedicated-servers"/g) ?? []).length, 3, "desktop tab + products menu + mobile sheet");
  assert.match(read("app/nxm/_components/NxmPage.tsx"), /withDedicatedNav\(html, dedi\.allowed\)/);
  assert.match(read("app/nxm/page.tsx"), /withDedicatedNav\([\s\S]*dedi\.allowed\)/);
});

export async function payDedicatedOrder(raw: unknown, useWallet = true): Promise<DedicatedPayResult> {
  try {
    try {
      await assertNotImpersonating();
    } catch {
      return { ok: false, error: "Payments are disabled while you are viewing this account as an admin." };
    }
    const { user, previewAll } = await gatedUser();
    const unverified = await emailVerificationError(user);
    if (unverified) return { ok: false, error: unverified };
    if (!checkRateLimit(`dedicated-pay:${user.id}`, { max: 10, windowMs: 10 * 60_000 }).ok) {
      return { ok: false, error: "Too many attempts. Please wait a few minutes and try again." };
    }
    if (!raw || typeof raw !== "object" || (raw as { acceptedNoRefund?: unknown }).acceptedNoRefund !== true) return { ok: false, error: NO_REFUND_REQUIRED };
    const intent = parseDedicatedIntent(raw);
    if (!intent) return { ok: false, error: "That configuration isn't valid. Please pick again." };
    const [q, wallet] = await Promise.all([quoteDedicatedOrder(intent, user, { previewAll }), dedicatedWallet(user)]);
    // The customer confirmed a total on screen; never charge a different one silently.
    const expected = (raw as { expectedTotalCents?: unknown }).expectedTotalCents;
    if (typeof expected === "number" && Number.isInteger(expected) && expected !== q.money.totalCents) {
      return { ok: false, error: `The price changed to ${usd(q.money.totalCents)} (from ${usd(expected)}) while you were checking out. Nothing was charged. Go back to review to see the new total.` };
    }
    const split = walletSplit({ dueCents: q.money.totalCents, balanceCents: wallet.spendableCents, useWallet });
    if (split.cardCents <= 0) {
      const { serverId } = await placeDedicatedOrder(user, intent, { previewAll, via: "wallet" });
      return { ok: true, serverId };
    }
    const checkout = await createDedicatedOrderPaymentSession(user, split.cardCents, intent, q.money, `${q.spec.name} · ${q.regionLabel}`);
    if (!checkout) return { ok: false, error: "Card payments aren't available right now. Top up your wallet to cover the order instead." };
    return { ok: true, checkout, cardCents: split.cardCents, walletApplied: split.walletApplied };

