const log = (...a) => console.log(...a);
async function ctxFor(w, theme, who = "customer") {
  const m = w < 600;
  const ctx = await b.newContext({ viewport: { width: w, height: m ? 844 : 900 }, isMobile: m, hasTouch: m, reducedMotion: process.env.RM ? "reduce" : "no-preference" });
  await ctx.addCookies([{ name: "nxeon_session", value: S.tokens[who], domain: "127.0.0.1", path: "/" }, { name: "nxeon_authed", value: "1", domain: "127.0.0.1", path: "/" }, { name: "nx_cookie_consent", value: "1", domain: "127.0.0.1", path: "/" }]);
