  for (let i = 0; i < 5; i++) { try { await p.goto(BASE + url, { waitUntil: "networkidle", timeout: 180000 }); break; } catch (e) { if (i === 4) throw e; await p.waitForTimeout(8000); } }
  await dismiss(p);
}
async function dismiss(p) { const ok = p.getByRole("button", { name: "Got it" }); if (await ok.count() && await ok.first().isVisible().catch(() => false)) await ok.first().click().catch(() => {}); }
const shot = async (p, name, full = true) => { await p.waitForTimeout(700); await dismiss(p); await p.screenshot({ path: `${OUT}/${name}.png`, fullPage: full }); log("shot", name); };
const want = (k) => !only.length || only.includes(k);

for (const combo of combos) {
